{
  "name": "HemoSim 0D",
  "description": "Real-time 0D closed-loop hemodynamic simulator using Runge-Kutta 4 integration. Visualizes Pressure-Volume loops and hemodynamic waveforms with interactive physiological parameters."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface SimulationParams {
    // Resistances
    Ras: number;
    Rcs: number;
    Rvs: number;
    Ras_prox: number;
    Rcp: number;
    Rap: number;
    Rvp: number;
    Rap_prox: number;
    Rmv: number;
    Rtv: number;
    Rda: number;

    // Compliances
    Cas: number;
    Cvs: number;
    Cas_prox: number;
    Cap: number;
    Cvp: number;
    Cap_prox: number;
    Cda: number;

    // Left Ventricle
    LV_Ees: number;
    LV_V0: number;
    LV_alpha: number;
    LV_beta: number;
    LV_Tmax: number;
    LV_tau: number;
    LV_AV_delay: number;

    // Left Atrium
    LA_Ees: number;
    LA_V0: number;
    LA_alpha: number;
    LA_beta: number;
    LA_Tmax: number;
    LA_tau: number;
    LA_AV_delay: number;

    // Right Ventricle
    RV_Ees: number;
    RV_V0: number;
    RV_alpha: number;
    RV_beta: number;
    RV_Tmax: number;
    RV_tau: number;
    RV_AV_delay: number;

    // Right Atrium
    RA_Ees: number;
    RA_V0: number;
    RA_alpha: number;
    RA_beta: number;
    RA_Tmax: number;
    RA_tau: number;
    RA_AV_delay: number;

    // General
    HR: number;

    // Valve Regurgitation (Resistance backward)
    Ravr: number;
    Ravs: number;
    Rmvr: number;
    Rmvs: number;
    Rpvr: number;
    Rpvs: number;
    Rtvr: number;
    Rtvs: number;
}

export interface SimulationState {
    Qvs: number;
    Qas: number;
    Qap: number;
    Qvp: number;
    Qlv: number;
    Qla: number;
    Qrv: number;
    Qra: number;
    Qas_prox: number;
    Qda: number;
    Qap_prox: number;
    Qtube: number;
}

export interface SimulationOutput {
    t: number;
    y: SimulationState;
    aux: {
      Plv: number;
      Pla: number;
      Prv: number;
      Pra: number;
      AoP: number;
      PAP: number;
    };
}

export type StateVector = number[];

import { SimulationParams, StateVector, SimulationOutput } from '../types';

// Helper: Activation function
function e_func(_t: number, Tmax: number, tau: number, HR: number): number {
  const T = 60000.0 / HR;
  const t = _t % T;
  if (t < Tmax) {
    const base = Math.exp(-(T - 1.5 * Tmax) / tau) / 2.0;
    return ((-Math.cos(Math.PI * t / Tmax) + 1.0) / 2.0) * (1.0 - base) + base;
  }
  if (t < 9.0 * Tmax / 8.0) {
    return (Math.cos(2.0 * Math.PI * t / Tmax) + 1.0) / 2.0;
  }
  return Math.exp(-(t - 9.0 * Tmax / 8.0) / tau) * (2.0 + Math.sqrt(2.0)) / 4.0;
}

// Helper: Pressure in chamber
function P_ch(V: number, t: number, Ees: number, V0: number, alpha: number, beta: number, Tmax: number, tau: number, AV_delay: number, HR: number): number {
  const Ped = beta * (Math.exp(alpha * (V - V0)) - 1.0);
  const Pes = Ees * (V - V0);
  return Ped + e_func(t - AV_delay, Tmax, tau, HR) * (Pes - Ped);
}

// Helper: Valve flow
function valve_flow(deltaP: number, R: number, Rs: number, Rr: number): number {
  if (deltaP > 0) {
    if (Rs === 0) {
      return deltaP / R;
    }
    return (-R + Math.sqrt(R * R + 4.0 * Rs * deltaP)) / (2.0 * Rs);
  } else {
    if (Rr >= 100000) {
      return deltaP / (R + Rr);
    }
    const disc = R * R - 4.0 * Rr * deltaP;
    return (-R - Math.sqrt(disc)) / (2.0 * Rr);
  }
}

// Right-Hand Side of ODEs
// y = [Qvs, Qas, Qap, Qvp, Qlv, Qla, Qrv, Qra, Qas_prox, Qda, Qap_prox, Qtube]
function rhs(t: number, y: StateVector, p: SimulationParams): { dy: StateVector, aux: any } {
  const [Qvs, Qas, Qap, Qvp, Qlv, Qla, Qrv, Qra, Qas_prox, Qda, Qap_prox] = y;
  // Qtube is y[11], but unused in derivative calc (constant)

  const HR = p.HR;

  const Plv = P_ch(Qlv, t, p.LV_Ees, p.LV_V0, p.LV_alpha, p.LV_beta, p.LV_Tmax, p.LV_tau, p.LV_AV_delay, HR);
  const Pla = P_ch(Qla, t, p.LA_Ees, p.LA_V0, p.LA_alpha, p.LA_beta, p.LA_Tmax, p.LA_tau, p.LA_AV_delay, HR);
  const Prv = P_ch(Qrv, t, p.RV_Ees, p.RV_V0, p.RV_alpha, p.RV_beta, p.RV_Tmax, p.RV_tau, p.RV_AV_delay, HR);
  const Pra = P_ch(Qra, t, p.RA_Ees, p.RA_V0, p.RA_alpha, p.RA_beta, p.RA_Tmax, p.RA_tau, p.RA_AV_delay, HR);

  const Paop = Qas_prox / p.Cas_prox;
  const PAP = Qap_prox / p.Cap_prox;
  const Pda = Qda / p.Cda;
  const Pas = Qas / p.Cas;
  const Pvs = Qvs / p.Cvs;
  const Pvp = Qvp / p.Cvp;
  const Pap = Qap / p.Cap;

  const Ida = (Paop - Pda) / p.Rda;
  const Ias = (Pda - Pas) / p.Ras;
  const Ics = (Pas - Pvs) / p.Rcs;
  const Ivs = (Pvs - Pra) / p.Rvs;

  const Ivp = (Pvp - Pla) / p.Rvp;
  const Iap = (Pap - Pvp) / p.Rap;
  const Icp = (PAP - Pap) / p.Rcp;

  const Itv = valve_flow(Pra - Prv, p.Rtv, p.Rtvs, p.Rtvr);
  const Imv = valve_flow(Pla - Plv, p.Rmv, p.Rmvs, p.Rmvr);
  const Iasp = valve_flow(Plv - Paop, p.Ras_prox, p.Ravs, p.Ravr);
  const Iapp = valve_flow(Prv - PAP, p.Rap_prox, p.Rpvs, p.Rpvr);

  const dQvs = Ics - Ivs;
  const dQas = Ias - Ics;
  const dQap = Icp - Iap;
  const dQvp = Iap - Ivp;

  const dQlv = Imv - Iasp;
  const dQla = Ivp - Imv;
  const dQrv = Itv - Iapp;
  const dQra = Ivs - Itv;

  const dQas_prox = Iasp - Ida;
  const dQda = Ida - Ias;
  const dQap_prox = Iapp - Icp;
  const dQtube = 0.0;

  const dy = [dQvs, dQas, dQap, dQvp, dQlv, dQla, dQrv, dQra, dQas_prox, dQda, dQap_prox, dQtube];
  const aux = { Plv, Pla, Prv, Pra, AoP: Paop, PAP, Imv, Iasp };
  return { dy, aux };
}

// RK4 Integration Step
export function stepRK4(t: number, y: StateVector, dt: number, p: SimulationParams): { tNext: number, yNext: StateVector, aux: any } {
  const { dy: k1, aux: aux } = rhs(t, y, p); // Capture aux from start of step for plotting

  // k2
  const y_k2 = y.map((val, i) => val + dt * k1[i] / 2.0);
  const { dy: k2 } = rhs(t + dt / 2.0, y_k2, p);

  // k3
  const y_k3 = y.map((val, i) => val + dt * k2[i] / 2.0);
  const { dy: k3 } = rhs(t + dt / 2.0, y_k3, p);

  // k4
  const y_k4 = y.map((val, i) => val + dt * k3[i]);
  const { dy: k4 } = rhs(t + dt, y_k4, p);

  const yNext = y.map((val, i) => val + dt * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]) / 6.0);

  return {
    tNext: t + dt,
    yNext,
    aux
  };
}

export function mapStateToObject(y: StateVector): any {
    // Helper if needed for debugging
    return {
        Qvs: y[0], Qas: y[1], Qap: y[2], Qvp: y[3],
        Qlv: y[4], Qla: y[5], Qrv: y[6], Qra: y[7],
        Qas_prox: y[8], Qda: y[9], Qap_prox: y[10], Qtube: y[11]
    }
}

import React from 'react';
import { SimulationParams } from '../types';

interface ControlsProps {
  params: SimulationParams;
  setParams: React.Dispatch<React.SetStateAction<SimulationParams>>;
}

const Slider = ({ label, value, min, max, step, onChange, unit }: { label: string, value: number, min: number, max: number, step: number, onChange: (val: number) => void, unit?: string }) => (
  <div className="mb-3">
    <div className="flex justify-between text-xs text-slate-400 mb-1">
      <span>{label}</span>
      <span>{value.toFixed(2)} {unit}</span>
    </div>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={(e) => onChange(parseFloat(e.target.value))}
      className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500 hover:accent-blue-400"
    />
  </div>
);

export const Controls: React.FC<ControlsProps> = ({ params, setParams }) => {
  const update = (key: keyof SimulationParams, val: number) => {
    setParams(prev => ({ ...prev, [key]: val }));
  };

  return (
    <div className="space-y-6">
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
        <h3 className="text-sm font-bold text-slate-100 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Global</h3>
        <Slider label="Heart Rate" value={params.HR} min={40} max={180} step={1} onChange={(v) => update('HR', v)} unit="bpm" />
      </div>

      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
        <h3 className="text-sm font-bold text-purple-400 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Left Ventricle</h3>
        <Slider label="Contractility (Ees)" value={params.LV_Ees} min={0.5} max={5.0} step={0.1} onChange={(v) => update('LV_Ees', v)} unit="mmHg/mL" />
        <Slider label="Unstressed Vol (V0)" value={params.LV_V0} min={-50} max={100} step={5} onChange={(v) => update('LV_V0', v)} unit="mL" />
        <Slider label="Relaxation Tau" value={params.LV_tau} min={10} max={80} step={1} onChange={(v) => update('LV_tau', v)} unit="ms" />
      </div>

      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
        <h3 className="text-sm font-bold text-blue-400 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Systemic Afterload</h3>
        <Slider label="Arterial Resist (Ras)" value={params.Ras} min={5} max={50} step={1} onChange={(v) => update('Ras', v)} unit="mmHg.s/mL" />
        <Slider label="Aortic Compliance (Cas_prox)" value={params.Cas_prox} min={0.1} max={3.0} step={0.05} onChange={(v) => update('Cas_prox', v)} unit="mL/mmHg" />
        <Slider label="Peripheral Resist (Rcs)" value={params.Rcs} min={200} max={2000} step={50} onChange={(v) => update('Rcs', v)} unit="mmHg.s/mL" />
      </div>

      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
        <h3 className="text-sm font-bold text-orange-400 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Right Ventricle</h3>
        <Slider label="Contractility (Ees)" value={params.RV_Ees} min={0.1} max={2.0} step={0.05} onChange={(v) => update('RV_Ees', v)} unit="mmHg/mL" />
      </div>

      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
        <h3 className="text-sm font-bold text-emerald-400 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Pulmonary</h3>
        <Slider label="Pulm. Resist (Rap)" value={params.Rap} min={1} max={50} step={1} onChange={(v) => update('Rap', v)} unit="mmHg.s/mL" />
      </div>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { SimulationOutput } from '../types';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, Legend } from 'recharts';

interface ChartProps {
  dataBuffer: React.MutableRefObject<SimulationOutput[]>;
  currentHeadIndex: React.MutableRefObject<number>;
  hr: number;
}

// --------------------------------------------------------
// 1. D3 Canvas PV Loop (Optimized for high performance)
// --------------------------------------------------------
export const PVLoopChart: React.FC<ChartProps> = ({ dataBuffer, currentHeadIndex, hr }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Dimensions
    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;

    // Handle Retina displays
    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;

    // Scales
    const xScale = d3.scaleLinear().domain([0, 250]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 160]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      // Clear
      ctx.clearRect(0, 0, width, height);

      // Draw Grid
      ctx.strokeStyle = '#334155'; // Slate-700
      ctx.lineWidth = 1;
      ctx.beginPath();
      // Vertical grid
      xScale.ticks(5).forEach(t => {
        ctx.moveTo(xScale(t), height - 40);
        ctx.lineTo(xScale(t), 20);
      });
      // Horizontal grid
      yScale.ticks(5).forEach(t => {
        ctx.moveTo(50, yScale(t));
        ctx.lineTo(width - 20, yScale(t));
      });
      ctx.stroke();

      // Axes Labels
      ctx.fillStyle = '#94a3b8'; // Slate-400
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xScale.ticks(5).forEach(t => {
        ctx.fillText(t.toString(), xScale(t), height - 25);
      });
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yScale.ticks(5).forEach(t => {
        ctx.fillText(t.toString(), 45, yScale(t));
      });

      // Axis Titles
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("LV Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();


      // Draw Loop
      const buffer = dataBuffer.current;
      if (buffer.length === 0) {
        animationFrameId = requestAnimationFrame(render);
        return;
      }

      ctx.beginPath();
      ctx.strokeStyle = '#a855f7'; // Purple-500
      ctx.lineWidth = 2.5;

      // Draw lines connecting points
      // Since buffer is circular-ish or just array, we iterate.
      // We skip jumps in time if the buffer was reset or looped (handled by index check)

      const len = buffer.length;
      if (len > 1) {
          const first = buffer[0];
          ctx.moveTo(xScale(first.y.Qlv), yScale(first.aux.Plv));

          for (let i = 1; i < len; i++) {
              const pt = buffer[i];
              // Optional: optimize by not drawing every single point if resolution is high
              ctx.lineTo(xScale(pt.y.Qlv), yScale(pt.aux.Plv));
          }
      }
      ctx.stroke();

      // Draw Current Head Point
      if (len > 0) {
        const last = buffer[len - 1];
        ctx.beginPath();
        ctx.fillStyle = '#ffffff';
        ctx.arc(xScale(last.y.Qlv), yScale(last.aux.Plv), 4, 0, 2 * Math.PI);
        ctx.fill();
      }

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    // Resize observer
    const resizeObserver = new ResizeObserver(() => {
       if(!containerRef.current) return;
       width = containerRef.current.clientWidth;
       height = containerRef.current.clientHeight;
       canvas.width = width * dpr;
       canvas.height = height * dpr;
       ctx.scale(dpr, dpr);
       canvas.style.width = `${width}px`;
       canvas.style.height = `${height}px`;
       xScale.range([50, width - 20]);
       yScale.range([height - 40, 20]);
    });
    resizeObserver.observe(containerRef.current);

    return () => {
      cancelAnimationFrame(animationFrameId);
      resizeObserver.disconnect();
    };
  }, [hr]); // Re-init if drastic structure changes, but mainly runs on ref

  return (
    <div ref={containerRef} className="w-full h-full relative">
      <canvas ref={canvasRef} className="block" />
    </div>
  );
};

// --------------------------------------------------------
// 2. Real-time Waveforms (Recharts with optimization)
// --------------------------------------------------------
export const TimeSeriesChart: React.FC<ChartProps> = ({ dataBuffer }) => {
    const [renderData, setRenderData] = React.useState<any[]>([]);

    // We throttle the Recharts update to 30fps to keep UI responsive
    // while the physics runs at 500Hz and Canvas at 60fps.
    useEffect(() => {
        let lastUpdate = 0;
        let frameId: number;

        const loop = (now: number) => {
            if (now - lastUpdate > 33) { // ~30fps
                // Sampling: Recharts can't handle 2000 points easily at 60fps. 
                // We take a subsample (e.g., every 5th point)
                const raw = dataBuffer.current;
                const downsampled = [];
                for(let i=0; i<raw.length; i+=5) {
                    downsampled.push({
                        time: raw[i].t,
                        Plv: Math.round(raw[i].aux.Plv),
                        AoP: Math.round(raw[i].aux.AoP),
                        Pla: Math.round(raw[i].aux.Pla)
                    });
                }
                setRenderData(downsampled);
                lastUpdate = now;
            }
            frameId = requestAnimationFrame(loop);
        }
        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, []);

    return (
        <ResponsiveContainer width="100%" height="100%">
            <LineChart data={renderData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                <XAxis 
                    dataKey="time" 
                    type="number" 
                    domain={['auto', 'auto']} 
                    tick={false} 
                    stroke="#94a3b8"
                />
                <YAxis domain={[0, 160]} stroke="#94a3b8" />
                <Tooltip 
                    contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', color: '#f8fafc' }}
                    itemStyle={{ fontSize: '12px' }}
                    labelFormatter={() => ''}
                />
                <Legend />
                <Line type="monotone" dataKey="Plv" stroke="#a855f7" strokeWidth={2} dot={false} isAnimationActive={false} name="LV Pressure" />
                <Line type="monotone" dataKey="AoP" stroke="#ef4444" strokeWidth={2} dot={false} isAnimationActive={false} name="Aortic Pres." />
                <Line type="monotone" dataKey="Pla" stroke="#22c55e" strokeWidth={2} dot={false} isAnimationActive={false} name="LA Pressure" />
            </LineChart>
        </ResponsiveContainer>
    );
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, StateVector } from './types';
import { stepRK4 } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopChart, TimeSeriesChart } from './components/Charts';

function App() {
  const [params, setParams] = useState<SimulationParams>(DEFAULT_PARAMS);

  // Simulation State Refs (Mutable for performance, bypassing React render cycle for physics)
  const stateRef = useRef<StateVector>([...INITIAL_STATE_VECTOR]);
  const timeRef = useRef<number>(INITIAL_TIME);

  // Data Buffer for plotting (Stores last 2 beats)
  // Window size logic: HR=60 -> T=1000ms. 2 beats = 2000ms.
  // dt=2ms -> 1000 points.
  const dataBufferRef = useRef<SimulationOutput[]>([]);
  const currentHeadIndex = useRef<number>(0);

  // Stats for display
  const [displayStats, setDisplayStats] = useState({ t: 0, plv: 0, qlv: 0 });

  // Physics Loop
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; // ms

    // We want to run physics faster than frame rate to match real-time
    // 60fps = 16.67ms.
    // If we want 1x real-time speed, we need to advance simulation by ~16.67ms per frame.
    // Steps per frame = 16.67 / 2.0 ~= 8 steps.
    const stepsPerFrame = 8;

    const loop = () => {
      const p = params; // Closure captures current params
      const windowSizeMs = (60000 / p.HR) * 2; // 2 beats window

      for (let i = 0; i < stepsPerFrame; i++) {
        const t = timeRef.current;
        const y = stateRef.current;

        const { tNext, yNext, aux } = stepRK4(t, y, dt, p);

        // Update refs
        timeRef.current = tNext;
        stateRef.current = yNext;

        // Add to buffer
        const output: SimulationOutput = {
            t: tNext,
            y: {
                Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
            },
            aux
        };

        dataBufferRef.current.push(output);

        // Prune old data (Simple array shift for now, could be optimized with ring buffer)
        // Remove points older than current time - windowSize
        const cutoffTime = tNext - windowSizeMs;
        while (dataBufferRef.current.length > 0 && dataBufferRef.current[0].t < cutoffTime) {
            dataBufferRef.current.shift();
        }
      }

      // Update basic UI stats occasionally (not every frame to avoid thrashing)
      // Actually React handles state updates in RAF reasonably well if not too complex
      // But let's just do it.
      setDisplayStats({
          t: timeRef.current,
          plv: dataBufferRef.current[dataBufferRef.current.length - 1]?.aux.Plv || 0,
          qlv: stateRef.current[4]
      });

      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => cancelAnimationFrame(animationFrameId);
  }, [params]); // Re-start loop if params change (closures update)

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden">
      {/* Sidebar Controls */}
      <aside className="w-80 h-full bg-slate-900 border-r border-slate-800 overflow-y-auto flex-shrink-0 z-10 shadow-xl">
        <div className="p-5">
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
            HemoSim 0D
          </h1>
          <div className="mb-4 p-3 bg-slate-800/50 rounded-lg text-xs font-mono">
            <div className="flex justify-between">
              <span className="text-slate-500">Time</span>
              <span>{(displayStats.t / 1000).toFixed(2)} s</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-500">LVP</span>
