import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { SimulationOutput, SimulationParams, Snapshot, ChamberId } from '../types';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, Legend } from 'recharts';

interface PVLoopChartProps {
  dataBuffer: React.MutableRefObject<SimulationOutput[]>;
  params: SimulationParams;
  visibleChambers: Set<ChamberId>;
  snapshots: Snapshot[];
  showGuides: boolean;
}

interface TimeSeriesChartProps {
    dataBuffer: React.MutableRefObject<SimulationOutput[]>;
}

// Colors for chambers
const COLORS = {
    LV: '#a855f7', // Purple
    LA: '#22c55e', // Green
    RV: '#f97316', // Orange
    RA: '#06b6d4', // Cyan
};

// --------------------------------------------------------
// 1. D3 Canvas PV Loop (Advanced)
// --------------------------------------------------------
export const PVLoopChart: React.FC<PVLoopChartProps> = ({ dataBuffer, params, visibleChambers, snapshots, showGuides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Dimensions
    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;

    // Scales - Fixed to reasonable physiology but could be dynamic
    const xScale = d3.scaleLinear().domain([0, 300]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 180]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // --- Draw Grid ---
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      xScale.ticks(6).forEach(t => {
        ctx.moveTo(xScale(t), height - 40);
        ctx.lineTo(xScale(t), 20);
      });
      yScale.ticks(6).forEach(t => {
        ctx.moveTo(50, yScale(t));
        ctx.lineTo(width - 20, yScale(t));
      });
      ctx.stroke();

      // --- Draw Axes Labels ---
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xScale.ticks(6).forEach(t => {
        ctx.fillText(t.toString(), xScale(t), height - 25);
      });
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yScale.ticks(6).forEach(t => {
        ctx.fillText(t.toString(), 45, yScale(t));
      });

      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // --- Draw ESPVR / EDPVR Guides (for LV only usually) ---
      if (showGuides && visibleChambers.has('LV')) {
          ctx.save();
          ctx.setLineDash([5, 5]);
          ctx.lineWidth = 1.5;

          // ESPVR: Pes = Ees * (V - V0)
          ctx.strokeStyle = '#f472b6'; // Pink-400
          ctx.beginPath();
          const vMax = 250;
          const pesMax = params.LV_Ees * (vMax - params.LV_V0);

          // Start point (V0, 0)
          if (params.LV_V0 >= 0) {
             ctx.moveTo(xScale(params.LV_V0), yScale(0));
             ctx.lineTo(xScale(vMax), yScale(pesMax));
          } else {
             // If V0 is negative, line starts from P=0 intercept
             const vIntercept = params.LV_V0; 
             ctx.moveTo(xScale(vIntercept), yScale(0));
             ctx.lineTo(xScale(vMax), yScale(pesMax));
          }
          ctx.stroke();

          // EDPVR: Ped = beta * (exp(alpha * (V - V0)) - 1)
          ctx.strokeStyle = '#60a5fa'; // Blue-400
          ctx.beginPath();
          ctx.moveTo(xScale(Math.max(0, params.LV_V0)), yScale(0));
          for (let v = Math.max(0, params.LV_V0); v <= 300; v += 5) {
              const ped = params.LV_beta * (Math.exp(params.LV_alpha * (v - params.LV_V0)) - 1);
              if (ped > 180) break;
              ctx.lineTo(xScale(v), yScale(ped));
          }
          ctx.stroke();
          ctx.restore();
      }

      // --- Helper to draw a single loop ---
      const drawLoop = (data: SimulationOutput[], chamber: ChamberId, color: string, alpha: number = 1, dash: boolean = false) => {
        if (data.length < 2) return;

        ctx.beginPath();
        ctx.strokeStyle = color;
        ctx.lineWidth = dash ? 1.5 : 2.5;
        ctx.globalAlpha = alpha;
        if (dash) ctx.setLineDash([4, 4]);
        else ctx.setLineDash([]);

        // Get V and P based on chamber
        const getVP = (pt: SimulationOutput) => {
            switch(chamber) {
                case 'LV': return [pt.y.Qlv, pt.aux.Plv];
                case 'LA': return [pt.y.Qla, pt.aux.Pla];
                case 'RV': return [pt.y.Qrv, pt.aux.Prv];
                case 'RA': return [pt.y.Qra, pt.aux.Pra];
                default: return [0,0];
            }
        };

        const [startV, startP] = getVP(data[0]);
        ctx.moveTo(xScale(startV), yScale(startP));

        for (let i = 1; i < data.length; i++) {
             const [v, p] = getVP(data[i]);
             ctx.lineTo(xScale(v), yScale(p));
        }
        ctx.stroke();
        ctx.globalAlpha = 1;
        ctx.setLineDash([]);

        // Head dot (only for live)
        if (!dash) {
            const [endV, endP] = getVP(data[data.length - 1]);
            ctx.beginPath();
            ctx.fillStyle = '#ffffff';
            ctx.arc(xScale(endV), yScale(endP), 4, 0, 2 * Math.PI);
            ctx.fill();
        }
      };

      // --- Draw Snapshots ---
      snapshots.forEach(snap => {
          visibleChambers.forEach(chamber => {
             drawLoop(snap.data, chamber, snap.color, 0.4, true);
          });
      });

      // --- Draw Live Data ---
      const buffer = dataBuffer.current;
      visibleChambers.forEach(chamber => {
          drawLoop(buffer, chamber, COLORS[chamber], 1, false);
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    const resizeObserver = new ResizeObserver(() => {
       if(!containerRef.current) return;
       width = containerRef.current.clientWidth;
       height = containerRef.current.clientHeight;
       canvas.width = width * dpr;
       canvas.height = height * dpr;
       ctx.scale(dpr, dpr);
       canvas.style.width = `${width}px`;
       canvas.style.height = `${height}px`;
       xScale.range([50, width - 20]);
       yScale.range([height - 40, 20]);
    });
    resizeObserver.observe(containerRef.current);

    return () => {
      cancelAnimationFrame(animationFrameId);
      resizeObserver.disconnect();
    };
  }, [params, visibleChambers, snapshots, showGuides]);

  return (
    <div ref={containerRef} className="w-full h-full relative">
      <canvas ref={canvasRef} className="block" />
    </div>
  );
};

// --------------------------------------------------------
// 2. Real-time Waveforms
// --------------------------------------------------------
export const TimeSeriesChart: React.FC<TimeSeriesChartProps> = ({ dataBuffer }) => {
    const [renderData, setRenderData] = React.useState<any[]>([]);

    useEffect(() => {
        let lastUpdate = 0;
        let frameId: number;

        const loop = (now: number) => {
            if (now - lastUpdate > 33) { 
                const raw = dataBuffer.current;
                const downsampled = [];
                // Only take last 1000ms worth of data approx (500 pts at dt=2ms)
                // We subsample every 5th point
                const len = raw.length;
                const start = Math.max(0, len - 500);

                for(let i=start; i<len; i+=5) {
                    downsampled.push({
                        time: raw[i].t,
                        Plv: Math.round(raw[i].aux.Plv),
                        AoP: Math.round(raw[i].aux.AoP),
                        Pla: Math.round(raw[i].aux.Pla),
                        Prv: Math.round(raw[i].aux.Prv),
                        PAP: Math.round(raw[i].aux.PAP)
                    });
                }
                setRenderData(downsampled);
                lastUpdate = now;
            }
            frameId = requestAnimationFrame(loop);
        }
        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, []);

    return (
        <ResponsiveContainer width="100%" height="100%">
            <LineChart data={renderData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                <XAxis 
                    dataKey="time" 
                    type="number" 
                    domain={['auto', 'auto']} 
                    tick={false} 
                    stroke="#94a3b8"
                />
                <YAxis domain={[0, 160]} stroke="#94a3b8" />
                <Tooltip 
                    contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', color: '#f8fafc' }}
                    itemStyle={{ fontSize: '12px' }}
                    labelFormatter={() => ''}
                />
                <Legend />
                <Line type="monotone" dataKey="Plv" stroke={COLORS.LV} strokeWidth={2} dot={false} isAnimationActive={false} name="LV" />
                <Line type="monotone" dataKey="AoP" stroke="#ef4444" strokeWidth={2} dot={false} isAnimationActive={false} name="Aortic" />
                <Line type="monotone" dataKey="Pla" stroke={COLORS.LA} strokeWidth={1} dot={false} isAnimationActive={false} name="LA" />
                <Line type="monotone" dataKey="Prv" stroke={COLORS.RV} strokeWidth={1} dot={false} isAnimationActive={false} name="RV" />
            </LineChart>
        </ResponsiveContainer>
    );
}

