import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, StateVector, Snapshot, ChamberId } from './types';
import { stepRK4 } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopChart, TimeSeriesChart } from './components/Charts';

function App() {
  const [params, setParams] = useState<SimulationParams>(DEFAULT_PARAMS);
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [visibleChambers, setVisibleChambers] = useState<Set<ChamberId>>(new Set(['LV']));
  const [showGuides, setShowGuides] = useState<boolean>(true);
  const [snapshots, setSnapshots] = useState<Snapshot[]>([]);
  const [showTimeSeries, setShowTimeSeries] = useState<boolean>(true);

  // Simulation State Refs
  const stateRef = useRef<StateVector>([...INITIAL_STATE_VECTOR]);
  const timeRef = useRef<number>(INITIAL_TIME);
  const dataBufferRef = useRef<SimulationOutput[]>([]);

  // Stats
  const [displayStats, setDisplayStats] = useState({ t: 0, plv: 0, qlv: 0 });

  // Physics Loop
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; // ms
    const baseStepsPerFrame = 8; // approx 16ms / 2ms = 8 steps for real-time

    const loop = () => {
      const p = params;
      // Calculate steps based on timeScale
      // If timeScale is 0.5, we run 4 steps. If 0, we pause.
      const stepsToRun = Math.round(baseStepsPerFrame * timeScale);

      const windowSizeMs = (60000 / p.HR) * 2; // 2 beats

      for (let i = 0; i < stepsToRun; i++) {
        const t = timeRef.current;
        const y = stateRef.current;

        const { tNext, yNext, aux } = stepRK4(t, y, dt, p);

        timeRef.current = tNext;
        stateRef.current = yNext;

        const output: SimulationOutput = {
            t: tNext,
            y: {
                Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
            },
            aux
        };

        dataBufferRef.current.push(output);

        // Buffer Pruning
        const cutoffTime = tNext - windowSizeMs;
        while (dataBufferRef.current.length > 0 && dataBufferRef.current[0].t < cutoffTime) {
            dataBufferRef.current.shift();
        }
      }

      if (dataBufferRef.current.length > 0) {
        setDisplayStats({
            t: timeRef.current,
            plv: dataBufferRef.current[dataBufferRef.current.length - 1].aux.Plv,
            qlv: stateRef.current[4]
        });
      }

      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => cancelAnimationFrame(animationFrameId);
  }, [params, timeScale]);

  // Actions
  const toggleChamber = (c: ChamberId) => {
      setVisibleChambers(prev => {
          const next = new Set(prev);
          if (next.has(c)) next.delete(c);
          else next.add(c);
          return next;
      });
  };

  const handleSnapshot = () => {
      // Capture 1 beat of data approx.
      // We take the last beat from the buffer.
      const beatDuration = 60000 / params.HR;
      const buffer = dataBufferRef.current;
      if (buffer.length === 0) return;

      const lastTime = buffer[buffer.length - 1].t;
      const startTime = lastTime - beatDuration;

      const snapData = buffer.filter(d => d.t >= startTime);

      const newSnap: Snapshot = {
          id: Date.now().toString(),
          label: `Sim ${snapshots.length + 1}`,
          data: snapData,
          params: { ...params },
          color: '#94a3b8' // Default grey for history
      };

      setSnapshots(prev => [...prev, newSnap]);
  };

  const handleDeleteSnapshot = (id: string) => {
      setSnapshots(prev => prev.filter(s => s.id !== id));
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      {/* Sidebar Controls */}
      <aside className="w-80 h-full bg-slate-900 border-r border-slate-800 overflow-y-auto flex-shrink-0 z-20 shadow-xl">
        <div className="p-5">
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
            HemoSim 0D
          </h1>
          <div className="mb-4 p-3 bg-slate-800/50 rounded-lg text-xs font-mono">
            <div className="flex justify-between">
              <span className="text-slate-500">Time</span>
              <span>{(displayStats.t / 1000).toFixed(2)} s</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-500">LVP</span>
              <span>{displayStats.plv.toFixed(0)} mmHg</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-500">LV Vol</span>
              <span>{displayStats.qlv.toFixed(0)} mL</span>
            </div>
          </div>

          <Controls 
            params={params} setParams={setParams} 
            timeScale={timeScale} setTimeScale={setTimeScale}
            visibleChambers={visibleChambers} toggleChamber={toggleChamber}
            showGuides={showGuides} setShowGuides={setShowGuides}
            onSnapshot={handleSnapshot} snapshots={snapshots} onDeleteSnapshot={handleDeleteSnapshot}
          />
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative bg-slate-950">

        {/* Panel Toolbar */}
        <div className="absolute top-4 right-4 z-10 flex gap-2">
            <button 
                onClick={() => setShowTimeSeries(!showTimeSeries)}
                className={`px-3 py-1 rounded-full text-xs font-bold border backdrop-blur-md transition-all ${showTimeSeries ? 'bg-blue-500/20 text-blue-300 border-blue-500/50' : 'bg-slate-800/50 text-slate-400 border-slate-700'}`}
            >
                {showTimeSeries ? 'Hide Waveforms' : 'Show Waveforms'}
            </button>
        </div>

        {/* Top: PV Loop Panel */}
        <div className={`transition-all duration-300 p-4 min-h-0 ${showTimeSeries ? 'h-2/3' : 'h-full'}`}>
          <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner overflow-hidden relative group">
            <div className="absolute top-4 left-4 z-10 bg-slate-950/80 px-3 py-1 rounded-full border border-slate-800 backdrop-blur-sm pointer-events-none">
                <span className="text-sm font-semibold text-slate-200">Pressure-Volume Loop</span>
            </div>
            <div className="flex-1 w-full h-full p-2">
                <PVLoopChart 
                    dataBuffer={dataBufferRef} 
                    params={params}
                    visibleChambers={visibleChambers}
                    snapshots={snapshots}
                    showGuides={showGuides}
                />
            </div>
          </div>
        </div>

        {/* Bottom: Time Series Panel */}
        {showTimeSeries && (
            <div className="h-1/3 p-4 pt-0 min-h-[200px] transition-all duration-300">
            <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner relative">
                <div className="absolute top-2 left-4 z-10 pointer-events-none">
                    <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">Real-time Waveforms</span>
                </div>
                <div className="flex-1 w-full h-full p-2 mt-4">
                    <TimeSeriesChart dataBuffer={dataBufferRef} />
                </div>
            </div>
            </div>
        )}
      </main>
    </div>
  );
}

