        <div className="flex flex-wrap gap-2 mb-4">
             <Toggle label="LV" checked={visibleChambers.has('LV')} onChange={() => toggleChamber('LV')} colorClass="bg-purple-600" />
             <Toggle label="LA" checked={visibleChambers.has('LA')} onChange={() => toggleChamber('LA')} colorClass="bg-green-600" />
             <Toggle label="RV" checked={visibleChambers.has('RV')} onChange={() => toggleChamber('RV')} colorClass="bg-orange-600" />
             <Toggle label="RA" checked={visibleChambers.has('RA')} onChange={() => toggleChamber('RA')} colorClass="bg-cyan-600" />
        </div>

        <div className="flex items-center gap-2 mb-2">
            <input 
                type="checkbox" 
                id="guides" 
                checked={showGuides} 
                onChange={(e) => setShowGuides(e.target.checked)}
                className="rounded bg-slate-700 border-slate-600 accent-pink-500"
            />
            <label htmlFor="guides" className="text-xs text-slate-300">Show ESPVR/EDPVR (LV)</label>
        </div>
      </div>

      {/* Instances Management */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
          <div className="flex justify-between items-center mb-2 border-b border-slate-800 pb-2">
            <h3 className="text-sm font-bold text-white uppercase tracking-wider">Hearts</h3>
            <button onClick={addInstance} className="text-xs bg-indigo-600 hover:bg-indigo-500 px-2 py-1 rounded text-white">+ Add</button>
          </div>
          <div className="space-y-2">
              {instances.map(inst => (
                  <div 
                    key={inst.id} 
                    className={`flex items-center justify-between p-2 rounded cursor-pointer border ${activeInstanceId === inst.id ? 'bg-slate-800 border-indigo-500/50' : 'bg-slate-950 border-slate-800 hover:border-slate-700'}`}
                    onClick={() => setActiveInstanceId(inst.id)}
                  >
                      <div className="flex items-center gap-2">
                          <div className="w-3 h-3 rounded-full" style={{ backgroundColor: inst.color }}></div>
                          <span className="text-xs font-semibold text-slate-200">{inst.name}</span>
                      </div>
                      <div className="flex items-center gap-2">
                          <button 
                            onClick={(e) => { e.stopPropagation(); toggleInstanceVisibility(inst.id); }}
                            className={`text-[10px] px-1.5 py-0.5 rounded ${inst.isVisible ? 'bg-slate-700 text-slate-200' : 'bg-slate-900 text-slate-600'}`}
                          >
                              {inst.isVisible ? 'Show' : 'Hide'}
                          </button>
                          {instances.length > 1 && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); removeInstance(inst.id); }}
                                className="text-slate-500 hover:text-red-400 px-1"
                            >
                                ✕
                            </button>
                          )}
                      </div>
                  </div>
              ))}
          </div>
      </div>

      {/* Params for Active Instance */}
      {params && (
          <>
            <div className="p-4 bg-slate-900 rounded-xl border border-slate-800 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-1 h-full" style={{ backgroundColor: activeInstance.color }}></div>
                <h3 className="text-sm font-bold text-white uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">
                    {activeInstance.name} Settings
                </h3>

                <h4 className="text-xs font-bold text-purple-400 uppercase mb-2">Left Ventricle</h4>
                <Slider label="Contractility (Ees)" value={params.LV_Ees} min={0.5} max={5.0} step={0.1} onChange={(v) => update('LV_Ees', v)} unit="mmHg/mL" />
                <Slider label="Unstressed Vol (V0)" value={params.LV_V0} min={-50} max={100} step={5} onChange={(v) => update('LV_V0', v)} unit="mL" />

                <div className="my-4 border-t border-slate-800"></div>
                <h4 className="text-xs font-bold text-slate-200 uppercase mb-2">General</h4>
                <Slider label="Heart Rate" value={params.HR} min={40} max={180} step={1} onChange={(v) => update('HR', v)} unit="bpm" />

                <div className="my-4 border-t border-slate-800"></div>
                <h4 className="text-xs font-bold text-blue-400 uppercase mb-2">Afterload</h4>
                <Slider label="Arterial Resist (Ras)" value={params.Ras} min={5} max={50} step={1} onChange={(v) => update('Ras', v)} unit="mmHg.s/mL" />
                <Slider label="Peripheral Resist (Rcs)" value={params.Rcs} min={200} max={2000} step={50} onChange={(v) => update('Rcs', v)} unit="mmHg.s/mL" />
            </div>
          </>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, StateVector, SimInstance, ChamberId, PhysicsRefState } from './types';
import { stepRK4 } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopChart, WaveformMonitor } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [visibleChambers, setVisibleChambers] = useState<Set<ChamberId>>(new Set(['LV']));
  const [showGuides, setShowGuides] = useState<boolean>(true);
  const [waveformWindow, setWaveformWindow] = useState<number>(10000); // 10s default

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], params: { ...DEFAULT_PARAMS }, isVisible: true }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Physics Refs ---
  // A map storing the mutable physics state for each instance ID.
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());

  // Init physics refs for new instances
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              physicsRefs.current.set(inst.id, {
                  t: INITIAL_TIME,
                  y: [...INITIAL_STATE_VECTOR],
                  buffer: [],
                  lastRenderX: 0
              });
          }
      });
      // Cleanup deleted instances
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) {
              physicsRefs.current.delete(id);
          }
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; // ms
    const baseStepsPerFrame = 8; 

    const loop = () => {
      const stepsToRun = Math.round(baseStepsPerFrame * timeScale);

      // We iterate through all instances registered in physicsRefs
      // But we need the *latest* params from the React state.
      // Accessing state inside RAF is tricky if not using Refs for params.
      // However, since `instances` updates cause a re-effect, this loop might be recreated.
      // If we use `instances` in dependency array, the loop restarts on every slider change.
      // This is acceptable but maybe slightly jittery. 
      // Better: Store params in a ref map as well? 
      // For simplicity/robustness, restarting the loop on param change is fine for this scale.

      // Wait, restarting loop clears RAF, so smooth. 
      // BUT, stateRef is persistent.

      for (let i = 0; i < stepsToRun; i++) {
         instances.forEach(inst => {
             const phys = physicsRefs.current.get(inst.id);
             if (!phys) return;

             // Step Physics
             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, inst.params);

             // Update Ref
             phys.t = tNext;
             phys.y = yNext;

             // Add to Buffer (PV Loop needs ~2 beats history)
             const windowSizeMs = (60000 / inst.params.HR) * 2; 
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };

            phys.buffer.push(output);

            // Prune Buffer
            const cutoffTime = tNext - windowSizeMs;
            // Optimization: Remove in chunks or just shift
            while (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }

      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => cancelAnimationFrame(animationFrameId);
  }, [instances, timeScale]); // Re-binds when instances/params change. Physics state persists in Ref.

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];
      const newInst: SimInstance = {
          id: newId,
          name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color: color,
          params: { ...DEFAULT_PARAMS }, // Copy default
          isVisible: true
      };
      setInstances(prev => [...prev, newInst]);
      setActiveInstanceId(newId);
  };

  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) {
          setActiveInstanceId(instances[0]?.id || '');
      }
  };

  const toggleInstanceVisibility = (id: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, isVisible: !inst.isVisible } : inst
    ));
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      {/* Sidebar Controls */}
      <aside className="w-80 h-full bg-slate-900 border-r border-slate-800 overflow-y-auto flex-shrink-0 z-20 shadow-xl">
        <div className="p-5">
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
            HemoSim 0D
          </h1>
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            toggleInstanceVisibility={toggleInstanceVisibility}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            visibleChambers={visibleChambers} toggleChamber={toggleChamber}
            showGuides={showGuides} setShowGuides={setShowGuides}
            waveformWindow={waveformWindow} setWaveformWindow={setWaveformWindow}
          />
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative bg-slate-950">

        {/* Top: PV Loop Panel */}
        <div className="h-1/2 p-4 min-h-0">
          <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner overflow-hidden relative group">
            <div className="absolute top-4 left-4 z-10 bg-slate-950/80 px-3 py-1 rounded-full border border-slate-800 backdrop-blur-sm pointer-events-none">
                <span className="text-sm font-semibold text-slate-200">Pressure-Volume Loop</span>
            </div>
            <div className="flex-1 w-full h-full p-2">
                <PVLoopChart 
                    physicsRefs={physicsRefs}
                    instances={instances}
                    visibleChambers={visibleChambers}
                    showGuides={showGuides}
                />
            </div>
          </div>
        </div>

        {/* Bottom: Waveform Monitor */}
        <div className="h-1/2 p-4 pt-0 min-h-[200px]">
            <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner relative overflow-hidden">
                <div className="absolute top-2 left-4 z-10 pointer-events-none">
                    <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">Real-time LV Pressure Monitor</span>
                </div>
                <div className="flex-1 w-full h-full p-2 mt-4">
                    <WaveformMonitor 
                        physicsRefs={physicsRefs}
                        instances={instances}
                        timeWindow={waveformWindow}
                    />
                </div>
            </div>
        </div>
      </main>
    </div>
  );
}

export default App;

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { SimulationOutput, SimInstance, PhysicsRefState, ChamberId } from '../types';

interface PVLoopChartProps {
  // Map of instance ID to its physics state
  physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
  instances: SimInstance[];
  visibleChambers: Set<ChamberId>;
  showGuides: boolean;
}

interface WaveformMonitorProps {
    physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
    instances: SimInstance[];
    timeWindow: number; // in ms
}

// --------------------------------------------------------
// 1. D3 Canvas PV Loop (Multi-Instance)
// --------------------------------------------------------
export const PVLoopChart: React.FC<PVLoopChartProps> = ({ physicsRefs, instances, visibleChambers, showGuides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // High DPI setup
    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    // Scales
    const xScale = d3.scaleLinear().domain([0, 300]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 180]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // --- Grid & Axes ---
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      // Update ranges in render loop if size changes, or rely on resize observer
      xScale.range([50, width - 20]);
      yScale.range([height - 40, 20]);

      xScale.ticks(6).forEach(t => {
        ctx.moveTo(xScale(t), height - 40);
        ctx.lineTo(xScale(t), 20);
      });
      yScale.ticks(6).forEach(t => {
        ctx.moveTo(50, yScale(t));
        ctx.lineTo(width - 20, yScale(t));
      });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xScale.ticks(6).forEach(t => {
        ctx.fillText(t.toString(), xScale(t), height - 25);
      });
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yScale.ticks(6).forEach(t => {
        ctx.fillText(t.toString(), 45, yScale(t));
      });

      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // --- Draw Loops for each Instance ---
      instances.forEach(inst => {
          if (!inst.isVisible) return;
          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          // ESPVR/EDPVR Guides (Only for first instance or all? Let's do all if showGuides is true)
          // To avoid clutter, maybe only show for the first visible one, or draw faint lines for all.
          // Let's draw for all but with the instance color, dashed.
          if (showGuides && visibleChambers.has('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;

              // ESPVR
              ctx.beginPath();
              const vMax = 250;
              const pesMax = inst.params.LV_Ees * (vMax - inst.params.LV_V0);
              const vIntercept = inst.params.LV_V0;
              ctx.moveTo(xScale(vIntercept), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(pesMax));
              ctx.stroke();

              // EDPVR
              ctx.beginPath();
              ctx.moveTo(xScale(Math.max(0, inst.params.LV_V0)), yScale(0));
              for (let v = Math.max(0, inst.params.LV_V0); v <= 300; v += 10) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > 180) break;
                  ctx.lineTo(xScale(v), yScale(ped));
              }
              ctx.stroke();
              ctx.restore();
          }

          // Draw Loops
          const drawChamberLoop = (chamber: ChamberId) => {
              const buffer = physState.buffer;
              ctx.beginPath();
              ctx.strokeStyle = inst.color;
              ctx.lineWidth = 2;

              // Helper to extract data
              const getPt = (idx: number) => {
                  const d = buffer[idx];
                  switch(chamber) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              }

              const [startV, startP] = getPt(0);
              ctx.moveTo(xScale(startV), yScale(startP));

              for(let i=1; i<buffer.length; i++) {
                  const [v, p] = getPt(i);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();

              // Head Dot
              const [endV, endP] = getPt(buffer.length-1);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(endV), yScale(endP), 3, 0, 2 * Math.PI);
              ctx.fill();
          };

          visibleChambers.forEach(c => drawChamberLoop(c));
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    const observer = new ResizeObserver(resize);
    observer.observe(containerRef.current);

    return () => {
        cancelAnimationFrame(animationFrameId);
        observer.disconnect();
    }
  }, [instances, visibleChambers, showGuides]);

  return (
    <div ref={containerRef} className="w-full h-full relative">
      <canvas ref={canvasRef} className="block" />
    </div>
  );
};

// --------------------------------------------------------
// 2. Sweep Waveform Monitor (Canvas-based)
// --------------------------------------------------------
export const WaveformMonitor: React.FC<WaveformMonitorProps> = ({ physicsRefs, instances, timeWindow }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const prevTimeRef = useRef<Map<string, number>>(new Map());

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const initCanvas = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;

            // Draw initial grid
            drawGrid();
        };

        const drawGrid = () => {
            // We only clear if we are resetting fully, but for sweep we want persistent buffer.
            // However, implementing sweep on a transparent canvas over a static grid background is better.
            // Since we can't easily layer divs here without complexity, we'll just draw the background color.
            // Actually, for sweep, we need to clear rects. So the background needs to be redrawn in the cleared rect.
            // Simplification: Just clear rect to transparent. CSS background provides the color/grid.
        };

        initCanvas();

        // Pressure Scale
        const yMin = 0;
        const yMax = 160;
        const yScale = (p: number) => height - ((p - yMin) / (yMax - yMin)) * height;

        let animationFrameId: number;

        const render = () => {
            // We do NOT clear the whole canvas. We only draw new segments and clear the "eraser bar".

            instances.forEach(inst => {
                if (!inst.isVisible) return;

                const phys = physicsRefs.current.get(inst.id);
                if (!phys) return;

                // We process all points accumulated since last render? 
                // Since physics runs faster than 60fps, 'buffer' has multiple new points.
                // However, the 'buffer' in physState is for PV Loop (fixed time window).
                // We should rely on the fact that 'buffer' contains the latest data points.
                // But 'buffer' contains 2 beats. We only want to draw the *newest* points added since last frame.
                // A robust way: compare phys.t with a stored 'lastRenderT'.

                const lastRenderT = prevTimeRef.current.get(inst.id) || phys.t - 20; // fallback
                // Find points in buffer newer than lastRenderT
                const newPoints = phys.buffer.filter(p => p.t > lastRenderT);

                if (newPoints.length === 0) return;

                ctx.lineWidth = 2;
                ctx.strokeStyle = inst.color;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';

                ctx.beginPath();

                // We need the point *just before* the new points to connect the line
                // Or just use the first new point as start if it's close enough.
                // Let's grab the last point processed previously, or the first of newPoints.

                let prevX = (lastRenderT % timeWindow) / timeWindow * width;
                let prevY = yScale(newPoints[0].aux.Plv); // Approximation for start

                // If we have a previous point in buffer that is <= lastRenderT, use it for continuity
                // const continuityPt = phys.buffer.findLast(p => p.t <= lastRenderT);
                let continuityPt = undefined;
                for (let k = phys.buffer.length - 1; k >= 0; k--) {
                    if (phys.buffer[k].t <= lastRenderT) {
                        continuityPt = phys.buffer[k];
                        break;
                    }
                }

                if (continuityPt) {
                    prevY = yScale(continuityPt.aux.Plv);
                }

                for (let i = 0; i < newPoints.length; i++) {
                    const pt = newPoints[i];
                    const t = pt.t;
                    const val = pt.aux.Plv;

                    const x = (t % timeWindow) / timeWindow * width;
                    const y = yScale(val);

                    // Check for wrap-around
                    if (x < prevX) {
                        ctx.stroke(); // Draw up to edge
                        ctx.beginPath(); // Start new line
                        prevX = x;
                        prevY = y;
                        ctx.moveTo(prevX, prevY);
                        continue;
                    }

                    // Eraser Bar: Clear a rectangle ahead of the current X
                    // We clear a strip of e.g., 20px wide or 2% of width
                    const eraserWidth = width * 0.05; // 5% eraser
                    const clearStart = x;
                    // Note: clearRect acts on the canvas pixels. 
                    // To keep the grid, we would need to redraw the grid in this strip.
                    // For now, we clear to transparent (assuming CSS bg).
                    ctx.clearRect(clearStart, 0, 5, height); // Clear small slice ahead
                    // If eraser wraps
                    if (clearStart + 5 > width) {
                        ctx.clearRect(0, 0, 5, height);
                    }

                    ctx.moveTo(prevX, prevY);
                    ctx.lineTo(x, y);

                    prevX = x;
                    prevY = y;
                }
                ctx.stroke();

                // Update last processed time
                prevTimeRef.current.set(inst.id, newPoints[newPoints.length - 1].t);
            });

            animationFrameId = requestAnimationFrame(render);
        };

        render();

        const resizeObserver = new ResizeObserver(() => {
            initCanvas();
            // Resetting canvas clears it, so history is lost on resize. Acceptable.
            prevTimeRef.current.clear();
        });
        resizeObserver.observe(containerRef.current);

        return () => {
            cancelAnimationFrame(animationFrameId);
            resizeObserver.disconnect();
        }
    }, [instances, timeWindow]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            {/* CSS Grid Background */}
            <div className="absolute inset-0 pointer-events-none" 
                 style={{ 
                     backgroundImage: 'linear-gradient(#334155 1px, transparent 1px), linear-gradient(90deg, #334155 1px, transparent 1px)', 
                     backgroundSize: '40px 40px',
                     opacity: 0.3
                 }} 
            />
            <canvas ref={canvasRef} className="block relative z-10" />

            {/* Legend / Info */}
            <div className="absolute top-2 right-2 flex flex-col items-end pointer-events-none">
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded">Window: {timeWindow/1000}s</span>
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded mt-1">Scale: 0-160 mmHg</span>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, StateVector, SimInstance, ChamberId, PhysicsRefState } from './types';
import { stepRK4 } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopChart, WaveformMonitor } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [visibleChambers, setVisibleChambers] = useState<Set<ChamberId>>(new Set(['LV']));
  const [showGuides, setShowGuides] = useState<boolean>(true);
  const [waveformWindow, setWaveformWindow] = useState<number>(10000); // 10s default

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], params: { ...DEFAULT_PARAMS }, isVisible: true }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Physics Refs ---
  // A map storing the mutable physics state for each instance ID.
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());

  // Init physics refs for new instances
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              physicsRefs.current.set(inst.id, {
                  t: INITIAL_TIME,
                  y: [...INITIAL_STATE_VECTOR],
                  buffer: [],
                  lastRenderX: 0
              });
          }
      });
      // Cleanup deleted instances
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) {
              physicsRefs.current.delete(id);
          }
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; // ms
    const baseStepsPerFrame = 8; 

    const loop = () => {
      const stepsToRun = Math.round(baseStepsPerFrame * timeScale);

      // We iterate through all instances registered in physicsRefs
      // But we need the *latest* params from the React state.
      // Accessing state inside RAF is tricky if not using Refs for params.
      // However, since `instances` updates cause a re-effect, this loop might be recreated.
      // If we use `instances` in dependency array, the loop restarts on every slider change.
      // This is acceptable but maybe slightly jittery. 
      // Better: Store params in a ref map as well? 
      // For simplicity/robustness, restarting the loop on param change is fine for this scale.

      // Wait, restarting loop clears RAF, so smooth. 
      // BUT, stateRef is persistent.

      for (let i = 0; i < stepsToRun; i++) {
         instances.forEach(inst => {
             const phys = physicsRefs.current.get(inst.id);
             if (!phys) return;

             // Step Physics
             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, inst.params);

             // Update Ref
             phys.t = tNext;
             phys.y = yNext;

             // Add to Buffer (PV Loop needs ~2 beats history)
             const windowSizeMs = (60000 / inst.params.HR) * 2; 
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };

            phys.buffer.push(output);

            // Prune Buffer
            const cutoffTime = tNext - windowSizeMs;
            // Optimization: Remove in chunks or just shift
            while (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }

      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => cancelAnimationFrame(animationFrameId);
  }, [instances, timeScale]); // Re-binds when instances/params change. Physics state persists in Ref.

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];
      const newInst: SimInstance = {
          id: newId,
          name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color: color,
          params: { ...DEFAULT_PARAMS }, // Copy default
          isVisible: true
      };
      setInstances(prev => [...prev, newInst]);
      setActiveInstanceId(newId);
  };

  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) {
          setActiveInstanceId(instances[0]?.id || '');
      }
  };

  const toggleInstanceVisibility = (id: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, isVisible: !inst.isVisible } : inst
    ));
  };

  const toggleChamber = (c: ChamberId) => {
    setVisibleChambers(prev => {
        const next = new Set(prev);
        if (next.has(c)) {
            next.delete(c);
        } else {
            next.add(c);
        }
        return next;
    });
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      {/* Sidebar Controls */}
      <aside className="w-80 h-full bg-slate-900 border-r border-slate-800 overflow-y-auto flex-shrink-0 z-20 shadow-xl">
        <div className="p-5">
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
            HemoSim 0D
          </h1>
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            toggleInstanceVisibility={toggleInstanceVisibility}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            visibleChambers={visibleChambers} toggleChamber={toggleChamber}
            showGuides={showGuides} setShowGuides={setShowGuides}
            waveformWindow={waveformWindow} setWaveformWindow={setWaveformWindow}
          />
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative bg-slate-950">

        {/* Top: PV Loop Panel */}
        <div className="h-1/2 p-4 min-h-0">
          <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner overflow-hidden relative group">
            <div className="absolute top-4 left-4 z-10 bg-slate-950/80 px-3 py-1 rounded-full border border-slate-800 backdrop-blur-sm pointer-events-none">
                <span className="text-sm font-semibold text-slate-200">Pressure-Volume Loop</span>
            </div>
            <div className="flex-1 w-full h-full p-2">
                <PVLoopChart 
                    physicsRefs={physicsRefs}
                    instances={instances}
                    visibleChambers={visibleChambers}
                    showGuides={showGuides}
                />
            </div>
          </div>
        </div>

        {/* Bottom: Waveform Monitor */}
        <div className="h-1/2 p-4 pt-0 min-h-[200px]">
            <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner relative overflow-hidden">
                <div className="absolute top-2 left-4 z-10 pointer-events-none">
                    <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">Real-time LV Pressure Monitor</span>
                </div>
                <div className="flex-1 w-full h-full p-2 mt-4">
                    <WaveformMonitor 
                        physicsRefs={physicsRefs}
                        instances={instances}
                        timeWindow={waveformWindow}
                    />
                </div>
            </div>
        </div>
      </main>
    </div>
  );
}

export default App;

