// --------------------------------------------------------
// 1. D3 Canvas PV Loop (Multi-Instance + Scaling)
// --------------------------------------------------------
export const PVLoopChart: React.FC<PVLoopChartProps> = ({ physicsRefs, instances, visibleChambers, showGuides, scaleConfig }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // High DPI setup
    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    // Scales
    const xScale = d3.scaleLinear().domain([0, scaleConfig.vMax]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, scaleConfig.pMax]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // --- Update Scales ---
      xScale.domain([0, scaleConfig.vMax]).range([50, width - 20]);
      yScale.domain([0, scaleConfig.pMax]).range([height - 40, 20]);

      // --- Grid & Axes ---
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();

      xScale.ticks(6).forEach(t => {
        ctx.moveTo(xScale(t), height - 40);
        ctx.lineTo(xScale(t), 20);
      });
      yScale.ticks(6).forEach(t => {
        ctx.moveTo(50, yScale(t));
        ctx.lineTo(width - 20, yScale(t));
      });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xScale.ticks(6).forEach(t => {
        ctx.fillText(t.toString(), xScale(t), height - 25);
      });
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yScale.ticks(6).forEach(t => {
        ctx.fillText(t.toString(), 45, yScale(t));
      });

      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // --- Draw Loops for each Instance ---
      instances.forEach(inst => {
          if (!inst.isVisible) return;
          const physState = physicsRefs.current.get(inst.id);
          // Just take last ~1000 points (2000ms at 2ms dt) for PV loop visualization to keep it clean
          if (!physState || physState.buffer.length < 2) return;

          const loopData = physState.buffer.slice(-1200); 

          // ESPVR/EDPVR Guides
          if (showGuides && visibleChambers.has('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;

              // ESPVR
              ctx.beginPath();
              const vMax = scaleConfig.vMax;
              const pesMax = inst.params.LV_Ees * (vMax - inst.params.LV_V0);
              const vIntercept = inst.params.LV_V0;
              ctx.moveTo(xScale(vIntercept), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(pesMax));
              ctx.stroke();

              // EDPVR
              ctx.beginPath();
              ctx.moveTo(xScale(Math.max(0, inst.params.LV_V0)), yScale(0));
              for (let v = Math.max(0, inst.params.LV_V0); v <= scaleConfig.vMax; v += 5) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > scaleConfig.pMax) break;
                  ctx.lineTo(xScale(v), yScale(ped));
              }
              ctx.stroke();
              ctx.restore();
          }

          // Draw Loops
          const drawChamberLoop = (chamber: ChamberId) => {
              ctx.beginPath();
              ctx.strokeStyle = inst.color;
              ctx.lineWidth = 2;

              const getPt = (idx: number) => {
                  const d = loopData[idx];
                  switch(chamber) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              }

              if(loopData.length === 0) return;

              const [startV, startP] = getPt(0);
              ctx.moveTo(xScale(startV), yScale(startP));

              for(let i=1; i<loopData.length; i++) {
                  const [v, p] = getPt(i);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();

              // Head Dot
              const [endV, endP] = getPt(loopData.length-1);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(endV), yScale(endP), 3, 0, 2 * Math.PI);
              ctx.fill();
          };

          visibleChambers.forEach(c => drawChamberLoop(c));
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    const observer = new ResizeObserver(resize);
    observer.observe(containerRef.current);

    return () => {
        cancelAnimationFrame(animationFrameId);
        observer.disconnect();
    }
  }, [instances, visibleChambers, showGuides, scaleConfig]);

  return (
    <div ref={containerRef} className="w-full h-full relative">
      <canvas ref={canvasRef} className="block" />
    </div>
  );
};

// --------------------------------------------------------
// 2. Sweep Waveform Monitor (Redraw-All Strategy)
// --------------------------------------------------------
export const WaveformMonitor: React.FC<WaveformMonitorProps> = ({ physicsRefs, instances, timeWindow, enabledSignals }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        // Scale
        const yMin = 0;
        const yMax = 160;
        const yScale = (p: number) => height - ((p - yMin) / (yMax - yMin)) * height;

        let animationFrameId: number;

        const render = () => {
            ctx.clearRect(0, 0, width, height);

            // Draw current time bar (Sweep Head) for reference?
            // Since there are multiple instances, they might have slightly different times, 
            // but generally they are synced. We pick the first visible instance for the "scan line" visual.
            const leadInstance = instances.find(i => i.isVisible && physicsRefs.current.has(i.id));
            let headX = -1;
            if (leadInstance) {
                const phys = physicsRefs.current.get(leadInstance.id);
                if(phys) {
                    headX = (phys.t % timeWindow) / timeWindow * width;

                    // Eraser / Highlight Bar
                    ctx.fillStyle = 'rgba(15, 23, 42, 0.8)'; // Dark slate, same as bg approximately but transparent?
                    // Actually clearer to draw a "scan line"
                    ctx.beginPath();
                    ctx.strokeStyle = '#475569';
                    ctx.lineWidth = 1;
                    ctx.moveTo(headX, 0);
                    ctx.lineTo(headX, height);
                    ctx.stroke();

                    // Fade out future (gap)
                    const gapWidth = 20;
                    ctx.fillStyle = 'rgba(15, 23, 42, 0.9)'; // Opaque-ish to hide "old" data just ahead of sweep
                    ctx.fillRect(headX, 0, gapWidth, height);
                    if (headX + gapWidth > width) {
                        ctx.fillRect(0, 0, (headX + gapWidth) % width, height);
                    }
                }
            }

            instances.forEach(inst => {
                if (!inst.isVisible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 2) return;

                // Optimization: We are drawing ~10s of data points (5000pts).
                // We redraw ALL points in buffer.
                // We need to handle the wrap-around at x = width.

                const drawSignal = (sig: SignalType, dash: number[]) => {
                    ctx.beginPath();
                    ctx.strokeStyle = inst.color;
                    ctx.lineWidth = 2;
                    ctx.setLineDash(dash);

                    let first = true;
                    let prevX = -1;
                    let prevY = -1;

                    // Downsample for rendering performance? 5000 points is fine for canvas.
                    // But we can step by 2 or 3.
                    const step = 2; 

                    for(let i=0; i<phys.buffer.length; i+=step) {
                        const pt = phys.buffer[i];
                        const t = pt.t;
                        // Value selection
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }

                        const x = (t % timeWindow) / timeWindow * width;
                        const y = yScale(val);

                        if (first) {
                            ctx.moveTo(x, y);
                            first = false;
                        } else {
                            // Detect wrap
                            if (x < prevX) {
                                // Break the line
                                ctx.moveTo(x, y);
                            } else {
                                // Draw
                                ctx.lineTo(x, y);
                            }
                        }
                        prevX = x;
                        prevY = y;
                    }
                    ctx.stroke();
                    ctx.setLineDash([]);
                };

                // Draw enabled signals
                // LVP: solid
                if (enabledSignals.has('Plv')) drawSignal('Plv', []);
                // AoP: dotted
                if (enabledSignals.has('AoP')) drawSignal('AoP', [2, 2]);
                // LA: dashed
                if (enabledSignals.has('Pla')) drawSignal('Pla', [5, 5]);
                // Right side: solid/dotted/dashed but maybe thinner?
                if (enabledSignals.has('Prv')) drawSignal('Prv', []); // same color as inst, confusion risk?
                if (enabledSignals.has('Pra')) drawSignal('Pra', [5, 5]);
                if (enabledSignals.has('PAP')) drawSignal('PAP', [2, 2]);
            });

            animationFrameId = requestAnimationFrame(render);
        };

        render();

        const resizeObserver = new ResizeObserver(resize);
        observer.observe(containerRef.current);

        return () => {
            cancelAnimationFrame(animationFrameId);
            resizeObserver.disconnect();
        }
    }, [instances, timeWindow, enabledSignals]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            {/* CSS Grid Background */}
            <div className="absolute inset-0 pointer-events-none" 
                 style={{ 
                     backgroundImage: 'linear-gradient(#334155 1px, transparent 1px), linear-gradient(90deg, #334155 1px, transparent 1px)', 
                     backgroundSize: '40px 40px',
                     opacity: 0.3
                 }} 
            />
            <canvas ref={canvasRef} className="block relative z-10" />

            {/* Legend / Info */}
            <div className="absolute top-2 right-2 flex flex-col items-end pointer-events-none">
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded">Window: {timeWindow/1000}s</span>
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded mt-1">Scale: 0-160 mmHg</span>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, StateVector, SimInstance, ChamberId, PhysicsRefState, ScaleConfig, SignalType } from './types';
import { stepRK4 } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopChart, WaveformMonitor } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

const SCALES: ScaleConfig[] = [
    { label: 'Systemic (LV)', vMax: 300, pMax: 180 },
    { label: 'High Pressure', vMax: 350, pMax: 300 },
    { label: 'Pulmonary (RV)', vMax: 300, pMax: 80 },
    { label: 'Atrial (RA/LA)', vMax: 150, pMax: 40 },
];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [visibleChambers, setVisibleChambers] = useState<Set<ChamberId>>(new Set(['LV']));
  const [showGuides, setShowGuides] = useState<boolean>(true);
  const [waveformWindow, setWaveformWindow] = useState<number>(10000); // 10s default

  // Scaling & Signals
  const [pvScale, setPvScale] = useState<ScaleConfig>(SCALES[0]);
  const [enabledSignals, setEnabledSignals] = useState<Set<SignalType>>(new Set(['Plv', 'AoP']));

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], params: { ...DEFAULT_PARAMS }, isVisible: true }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Physics Refs ---
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());

  // Init physics refs for new instances
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              physicsRefs.current.set(inst.id, {
                  t: INITIAL_TIME,
                  y: [...INITIAL_STATE_VECTOR],
                  buffer: [],
                  lastRenderX: 0
              });
          }
      });
      // Cleanup deleted instances
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) {
              physicsRefs.current.delete(id);
          }
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; // ms
    const baseStepsPerFrame = 8; 

    const loop = () => {
      const stepsToRun = Math.round(baseStepsPerFrame * timeScale);

      for (let i = 0; i < stepsToRun; i++) {
         instances.forEach(inst => {
             const phys = physicsRefs.current.get(inst.id);
             if (!phys) return;

             // Step Physics
             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, inst.params);

             // Update Ref
             phys.t = tNext;
             phys.y = yNext;

             // Add to Buffer
             // We need to keep enough data for the waveform window + a bit extra to be safe
             // Also min 2 beats for PV loop if HR is slow.
             const bufferRequiredMs = Math.max(waveformWindow + 1000, 5000);
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };

            phys.buffer.push(output);

            // Prune Buffer
            const cutoffTime = tNext - bufferRequiredMs;
            // Batch remove from start
            // To avoid shifting every step (O(N)), we can check head timestamp
            if (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                // If we need to remove, remove a chunk to amortize? 
                // For simplicity in this loop, shift is fine for ~5000 elements array. 
                // JS engines optimize shift nicely for packed arrays.
                phys.buffer.shift();
            }
         });
      }

      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => cancelAnimationFrame(animationFrameId);
  }, [instances, timeScale, waveformWindow]);

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];
      const newInst: SimInstance = {
          id: newId,
          name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color: color,
          params: { ...DEFAULT_PARAMS }, // Copy default
          isVisible: true
      };
      setInstances(prev => [...prev, newInst]);
      setActiveInstanceId(newId);
  };

  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) {
          setActiveInstanceId(instances[0]?.id || '');
      }
  };

  const toggleInstanceVisibility = (id: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, isVisible: !inst.isVisible } : inst
    ));
  };

  const toggleChamber = (c: ChamberId) => {
    setVisibleChambers(prev => {
        const next = new Set(prev);
        if (next.has(c)) next.delete(c);
        else next.add(c);
        return next;
    });
  };

  const toggleSignal = (s: SignalType) => {
      setEnabledSignals(prev => {
          const next = new Set(prev);
          if (next.has(s)) next.delete(s);
          else next.add(s);
          return next;
      });
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      {/* Sidebar Controls */}
      <aside className="w-80 h-full bg-slate-900 border-r border-slate-800 overflow-y-auto flex-shrink-0 z-20 shadow-xl">
        <div className="p-5">
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
            HemoSim 0D
          </h1>
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            toggleInstanceVisibility={toggleInstanceVisibility}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            visibleChambers={visibleChambers} toggleChamber={toggleChamber}
            showGuides={showGuides} setShowGuides={setShowGuides}
            waveformWindow={waveformWindow} setWaveformWindow={setWaveformWindow}
          />
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative bg-slate-950">

        {/* Top: PV Loop Panel */}
        <div className="h-1/2 p-4 min-h-0">
          <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner overflow-hidden relative group">
            {/* Header */}
            <div className="absolute top-4 left-4 z-10 flex gap-2 pointer-events-auto">
                <div className="bg-slate-950/80 px-3 py-1 rounded-full border border-slate-800 backdrop-blur-sm">
                    <span className="text-sm font-semibold text-slate-200">PV Loop</span>
                </div>

                {/* Scale Dropdown */}
                <select 
                    value={pvScale.label}
                    onChange={(e) => {
                        const s = SCALES.find(s => s.label === e.target.value);
                        if(s) setPvScale(s);
                    }}
                    className="bg-slate-950/80 text-xs text-slate-300 border border-slate-800 rounded-full px-2 py-1 outline-none hover:border-slate-600 cursor-pointer"
                >
                    {SCALES.map(s => <option key={s.label} value={s.label}>{s.label}</option>)}
                </select>
            </div>

            <div className="flex-1 w-full h-full p-2">
                <PVLoopChart 
                    physicsRefs={physicsRefs}
                    instances={instances}
                    visibleChambers={visibleChambers}
                    showGuides={showGuides}
                    scaleConfig={pvScale}
                />
            </div>
          </div>
        </div>

        {/* Bottom: Waveform Monitor */}
        <div className="h-1/2 p-4 pt-0 min-h-[200px]">
            <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner relative overflow-hidden">
                {/* Header */}
                <div className="absolute top-2 left-4 z-10 flex gap-2 items-center pointer-events-auto max-w-full overflow-x-auto p-1">
                    <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide mr-2">Monitor</span>
                    {(['Plv', 'AoP', 'Pla', 'Prv', 'PAP', 'Pra'] as SignalType[]).map(sig => (
                        <button
                            key={sig}
                            onClick={() => toggleSignal(sig)}
                            className={`px-2 py-0.5 text-[10px] font-bold rounded border ${enabledSignals.has(sig) ? 'bg-slate-700 text-slate-200 border-slate-600' : 'bg-transparent text-slate-500 border-slate-800 hover:border-slate-700'}`}
                        >
                            {sig}
                        </button>
                    ))}
                </div>

                <div className="flex-1 w-full h-full p-2 mt-6">
                    <WaveformMonitor 
                        physicsRefs={physicsRefs}
                        instances={instances}
                        timeWindow={waveformWindow}
                        enabledSignals={enabledSignals}
                    />
                </div>
            </div>
        </div>
      </main>
    </div>
  );
}

export default App;

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { SimulationOutput, SimInstance, PhysicsRefState, ChamberId, ScaleConfig, SignalType } from '../types';

interface PVLoopChartProps {
  physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
  instances: SimInstance[];
  visibleChambers: Set<ChamberId>;
  showGuides: boolean;
  scaleConfig: ScaleConfig;
}

interface WaveformMonitorProps {
    physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
    instances: SimInstance[];
    timeWindow: number; // in ms
    enabledSignals: Set<SignalType>;
}

// --------------------------------------------------------
// 1. D3 Canvas PV Loop (Multi-Instance + Scaling)
// --------------------------------------------------------
export const PVLoopChart: React.FC<PVLoopChartProps> = ({ physicsRefs, instances, visibleChambers, showGuides, scaleConfig }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // High DPI setup
    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    // Scales
    const xScale = d3.scaleLinear().domain([0, scaleConfig.vMax]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, scaleConfig.pMax]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // --- Update Scales ---
      xScale.domain([0, scaleConfig.vMax]).range([50, width - 20]);
      yScale.domain([0, scaleConfig.pMax]).range([height - 40, 20]);

      // --- Grid & Axes ---
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();

      xScale.ticks(6).forEach(t => {
        ctx.moveTo(xScale(t), height - 40);
        ctx.lineTo(xScale(t), 20);
      });
      yScale.ticks(6).forEach(t => {
        ctx.moveTo(50, yScale(t));
        ctx.lineTo(width - 20, yScale(t));
      });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xScale.ticks(6).forEach(t => {
        ctx.fillText(t.toString(), xScale(t), height - 25);
      });
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yScale.ticks(6).forEach(t => {
        ctx.fillText(t.toString(), 45, yScale(t));
      });

      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // --- Draw Loops for each Instance ---
      instances.forEach(inst => {
          if (!inst.isVisible) return;
          const physState = physicsRefs.current.get(inst.id);
          // Just take last ~1000 points (2000ms at 2ms dt) for PV loop visualization to keep it clean
          if (!physState || physState.buffer.length < 2) return;

          const loopData = physState.buffer.slice(-1200); 

          // ESPVR/EDPVR Guides
          if (showGuides && visibleChambers.has('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;

              // ESPVR
              ctx.beginPath();
              const vMax = scaleConfig.vMax;
              const pesMax = inst.params.LV_Ees * (vMax - inst.params.LV_V0);
              const vIntercept = inst.params.LV_V0;
              ctx.moveTo(xScale(vIntercept), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(pesMax));
              ctx.stroke();

              // EDPVR
              ctx.beginPath();
              ctx.moveTo(xScale(Math.max(0, inst.params.LV_V0)), yScale(0));
              for (let v = Math.max(0, inst.params.LV_V0); v <= scaleConfig.vMax; v += 5) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > scaleConfig.pMax) break;
                  ctx.lineTo(xScale(v), yScale(ped));
              }
              ctx.stroke();
              ctx.restore();
          }

          // Draw Loops
          const drawChamberLoop = (chamber: ChamberId) => {
              ctx.beginPath();
              ctx.strokeStyle = inst.color;
              ctx.lineWidth = 2;

              const getPt = (idx: number) => {
                  const d = loopData[idx];
                  switch(chamber) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              }

              if(loopData.length === 0) return;

              const [startV, startP] = getPt(0);
              ctx.moveTo(xScale(startV), yScale(startP));

              for(let i=1; i<loopData.length; i++) {
                  const [v, p] = getPt(i);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();

              // Head Dot
              const [endV, endP] = getPt(loopData.length-1);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(endV), yScale(endP), 3, 0, 2 * Math.PI);
              ctx.fill();
          };

          visibleChambers.forEach(c => drawChamberLoop(c));
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    const observer = new ResizeObserver(resize);
    observer.observe(containerRef.current);

    return () => {
        cancelAnimationFrame(animationFrameId);
        observer.disconnect();
    }
  }, [instances, visibleChambers, showGuides, scaleConfig]);

  return (
    <div ref={containerRef} className="w-full h-full relative">
      <canvas ref={canvasRef} className="block" />
    </div>
  );
};

// --------------------------------------------------------
// 2. Sweep Waveform Monitor (Redraw-All Strategy)
// --------------------------------------------------------
export const WaveformMonitor: React.FC<WaveformMonitorProps> = ({ physicsRefs, instances, timeWindow, enabledSignals }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        // Scale
        const yMin = 0;
        const yMax = 160;
        const yScale = (p: number) => height - ((p - yMin) / (yMax - yMin)) * height;

        let animationFrameId: number;

        const render = () => {
            ctx.clearRect(0, 0, width, height);

            // Draw current time bar (Sweep Head) for reference?
            // Since there are multiple instances, they might have slightly different times, 
            // but generally they are synced. We pick the first visible instance for the "scan line" visual.
            const leadInstance = instances.find(i => i.isVisible && physicsRefs.current.has(i.id));
            let headX = -1;
            if (leadInstance) {
                const phys = physicsRefs.current.get(leadInstance.id);
                if(phys) {
                    headX = (phys.t % timeWindow) / timeWindow * width;

                    // Eraser / Highlight Bar
                    ctx.fillStyle = 'rgba(15, 23, 42, 0.8)'; // Dark slate, same as bg approximately but transparent?
                    // Actually clearer to draw a "scan line"
                    ctx.beginPath();
                    ctx.strokeStyle = '#475569';
                    ctx.lineWidth = 1;
                    ctx.moveTo(headX, 0);
                    ctx.lineTo(headX, height);
                    ctx.stroke();

                    // Fade out future (gap)
                    const gapWidth = 20;
                    ctx.fillStyle = 'rgba(15, 23, 42, 0.9)'; // Opaque-ish to hide "old" data just ahead of sweep
                    ctx.fillRect(headX, 0, gapWidth, height);
                    if (headX + gapWidth > width) {
                        ctx.fillRect(0, 0, (headX + gapWidth) % width, height);
                    }
                }
            }

            instances.forEach(inst => {
                if (!inst.isVisible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 2) return;

                // Optimization: We are drawing ~10s of data points (5000pts).
                // We redraw ALL points in buffer.
                // We need to handle the wrap-around at x = width.

                const drawSignal = (sig: SignalType, dash: number[]) => {
                    ctx.beginPath();
                    ctx.strokeStyle = inst.color;
                    ctx.lineWidth = 2;
                    ctx.setLineDash(dash);

                    let first = true;
                    let prevX = -1;
                    let prevY = -1;

                    // Downsample for rendering performance? 5000 points is fine for canvas.
                    // But we can step by 2 or 3.
                    const step = 2; 

                    for(let i=0; i<phys.buffer.length; i+=step) {
                        const pt = phys.buffer[i];
                        const t = pt.t;
                        // Value selection
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }

                        const x = (t % timeWindow) / timeWindow * width;
                        const y = yScale(val);

                        if (first) {
                            ctx.moveTo(x, y);
                            first = false;
                        } else {
                            // Detect wrap
                            if (x < prevX) {
                                // Break the line
                                ctx.moveTo(x, y);
                            } else {
                                // Draw
                                ctx.lineTo(x, y);
                            }
                        }
                        prevX = x;
                        prevY = y;
                    }
                    ctx.stroke();
                    ctx.setLineDash([]);
                };

                // Draw enabled signals
                // LVP: solid
                if (enabledSignals.has('Plv')) drawSignal('Plv', []);
                // AoP: dotted
                if (enabledSignals.has('AoP')) drawSignal('AoP', [2, 2]);
                // LA: dashed
                if (enabledSignals.has('Pla')) drawSignal('Pla', [5, 5]);
                // Right side: solid/dotted/dashed but maybe thinner?
                if (enabledSignals.has('Prv')) drawSignal('Prv', []); // same color as inst, confusion risk?
                if (enabledSignals.has('Pra')) drawSignal('Pra', [5, 5]);
                if (enabledSignals.has('PAP')) drawSignal('PAP', [2, 2]);
            });

            animationFrameId = requestAnimationFrame(render);
        };

        render();

        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);

        return () => {
            cancelAnimationFrame(animationFrameId);
            resizeObserver.disconnect();
        }
    }, [instances, timeWindow, enabledSignals]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            {/* CSS Grid Background */}
            <div className="absolute inset-0 pointer-events-none" 
                 style={{ 
                     backgroundImage: 'linear-gradient(#334155 1px, transparent 1px), linear-gradient(90deg, #334155 1px, transparent 1px)', 
                     backgroundSize: '40px 40px',
                     opacity: 0.3
                 }} 
            />
            <canvas ref={canvasRef} className="block relative z-10" />

            {/* Legend / Info */}
            <div className="absolute top-2 right-2 flex flex-col items-end pointer-events-none">
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded">Window: {timeWindow/1000}s</span>
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded mt-1">Scale: 0-160 mmHg</span>
            </div>
        </div>
    );
};

export interface SimulationParams {
    // Resistances
    Ras: number;
    Rcs: number;
    Rvs: number;
    Ras_prox: number;
    Rcp: number;
    Rap: number;
    Rvp: number;
    Rap_prox: number;
    Rmv: number;
    Rtv: number;
    Rda: number;

    // Compliances
    Cas: number;
    Cvs: number;
    Cas_prox: number;
    Cap: number;
    Cvp: number;
    Cap_prox: number;
    Cda: number;

    // Left Ventricle
    LV_Ees: number;
    LV_V0: number;
    LV_alpha: number;
    LV_beta: number;
    LV_Tmax: number;
    LV_tau: number;
    LV_AV_delay: number;

    // Left Atrium
    LA_Ees: number;
    LA_V0: number;
    LA_alpha: number;
    LA_beta: number;
    LA_Tmax: number;
    LA_tau: number;
    LA_AV_delay: number;

    // Right Ventricle
    RV_Ees: number;
    RV_V0: number;
    RV_alpha: number;
    RV_beta: number;
    RV_Tmax: number;
    RV_tau: number;
    RV_AV_delay: number;

    // Right Atrium
    RA_Ees: number;
    RA_V0: number;
    RA_alpha: number;
    RA_beta: number;
    RA_Tmax: number;
    RA_tau: number;
    RA_AV_delay: number;

    // General
    HR: number;

    // Valve Regurgitation (Resistance backward)
    Ravr: number;
    Ravs: number;
    Rmvr: number;
    Rmvs: number;
    Rpvr: number;
    Rpvs: number;
    Rtvr: number;
    Rtvs: number;
}

export interface SimulationState {
    Qvs: number;
    Qas: number;
    Qap: number;
    Qvp: number;
    Qlv: number;
    Qla: number;
    Qrv: number;
    Qra: number;
    Qas_prox: number;
    Qda: number;
    Qap_prox: number;
    Qtube: number;
}

export interface SimulationOutput {
    t: number;
    y: SimulationState;
    aux: {
      Plv: number;
      Pla: number;
      Prv: number;
      Pra: number;
      AoP: number;
      PAP: number;
    };
}

export type StateVector = number[];

export type ChamberId = 'LV' | 'LA' | 'RV' | 'RA';

// Instance management
export interface SimInstance {
    id: string;
    name: string;
    color: string;
    params: SimulationParams;
    isVisible: boolean;
}

// Internal Physics State (Mutable Ref Object)
export interface PhysicsRefState {
    t: number;
    y: StateVector;
    buffer: SimulationOutput[]; // For PV Loop (recent history)
    lastRenderX: number; // For Sweep Chart
}

export type SignalType = 'Plv' | 'Pla' | 'Prv' | 'Pra' | 'AoP' | 'PAP';

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { SimulationOutput, SimInstance, PhysicsRefState, ChamberId, SignalType } from '../types';

interface PVLoopChartProps {
  physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
  instances: SimInstance[];
  visibleChambers: Set<ChamberId>;
  showGuides: boolean;
}

interface WaveformMonitorProps {
    physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
    instances: SimInstance[];
    timeWindow: number; // in ms
    enabledSignals: Set<SignalType>;
}

// --------------------------------------------------------
// 1. D3 Canvas PV Loop (Multi-Instance + Auto-Scaling)
// --------------------------------------------------------
export const PVLoopChart: React.FC<PVLoopChartProps> = ({ physicsRefs, instances, visibleChambers, showGuides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // High DPI setup
    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    // Initial Scales (will be updated every frame)
    const xScale = d3.scaleLinear().domain([0, 300]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 200]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // --- Auto-Scaling Logic ---
      let globalMinV = Infinity;
      let globalMaxV = -Infinity;
      let globalMinP = Infinity;
      let globalMaxP = -Infinity;
      let hasData = false;

      // Scan all visible instances and chambers to determine bounding box
      instances.forEach(inst => {
          if (!inst.isVisible) return;
          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          // Use recent buffer for scaling (e.g. last 2 beats approx 2000 points)
          const data = physState.buffer; 

          // Sample data to avoid iterating too many points every frame if buffer is huge
          // Step 10 is enough for bounding box
          for (let i = 0; i < data.length; i += 10) {
              const d = data[i];
              visibleChambers.forEach(chamber => {
                  let v = 0, p = 0;
                  switch(chamber) {
                      case 'LV': v = d.y.Qlv; p = d.aux.Plv; break;
                      case 'LA': v = d.y.Qla; p = d.aux.Pla; break;
                      case 'RV': v = d.y.Qrv; p = d.aux.Prv; break;
                      case 'RA': v = d.y.Qra; p = d.aux.Pra; break;
                  }
                  if (v < globalMinV) globalMinV = v;
                  if (v > globalMaxV) globalMaxV = v;
                  if (p < globalMinP) globalMinP = p;
                  if (p > globalMaxP) globalMaxP = p;
                  hasData = true;
              });
          }
      });

      // Default fallback
      if (!hasData) {
          globalMinV = 0; globalMaxV = 150;
          globalMinP = 0; globalMaxP = 120;
      } else {
          // Add padding (10%)
          const rangeV = globalMaxV - globalMinV;
          const rangeP = globalMaxP - globalMinP;
          // Ensure min range to avoid div by zero or flat lines
          const padV = Math.max(rangeV * 0.1, 10); 
          const padP = Math.max(rangeP * 0.1, 10);

          globalMinV = Math.max(0, globalMinV - padV);
          globalMaxV = globalMaxV + padV;
          globalMinP = Math.max(0, globalMinP - padP);
          globalMaxP = globalMaxP + padP;
      }

      // Update D3 Scales
      xScale.domain([globalMinV, globalMaxV]).range([50, width - 20]);
      yScale.domain([globalMinP, globalMaxP]).range([height - 40, 20]);


      // --- Grid & Axes ---
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();

      const xTicks = xScale.ticks(6);
      const yTicks = yScale.ticks(6);

      xTicks.forEach(t => {
        ctx.moveTo(xScale(t), height - 40);
        ctx.lineTo(xScale(t), 20);
      });
      yTicks.forEach(t => {
        ctx.moveTo(50, yScale(t));
        ctx.lineTo(width - 20, yScale(t));
      });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xTicks.forEach(t => {
        ctx.fillText(t.toString(), xScale(t), height - 25);
      });
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yTicks.forEach(t => {
        ctx.fillText(t.toString(), 45, yScale(t));
      });

      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // --- Draw Loops for each Instance ---
      instances.forEach(inst => {
          if (!inst.isVisible) return;
          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          // Draw last ~1.5 sec of data for clean loop
          const loopData = physState.buffer.slice(-1000); 

          // ESPVR/EDPVR Guides (LV only)
          if (showGuides && visibleChambers.has('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;

              // ESPVR
              ctx.beginPath();
              const vMax = globalMaxV;
              const pesMax = inst.params.LV_Ees * (vMax - inst.params.LV_V0);
              const vIntercept = inst.params.LV_V0;

              // Draw line from V0 to edge of graph
              ctx.moveTo(xScale(vIntercept), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(pesMax));
              ctx.stroke();

              // EDPVR
              ctx.beginPath();
              // Plot curve points
              const startV = Math.max(globalMinV, inst.params.LV_V0);
              let firstPt = true;
              for (let v = startV; v <= globalMaxV; v += (globalMaxV - startV)/50) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > globalMaxP) break;
                  const px = xScale(v);
                  const py = yScale(ped);
                  if (firstPt) { ctx.moveTo(px, py); firstPt = false; }
                  else ctx.lineTo(px, py);
              }
              ctx.stroke();
              ctx.restore();
          }

          // Draw Loops
          const drawChamberLoop = (chamber: ChamberId) => {
              ctx.beginPath();
              ctx.strokeStyle = inst.color;
              ctx.lineWidth = 2;

              const getPt = (idx: number) => {
                  const d = loopData[idx];
                  switch(chamber) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              }

              if(loopData.length === 0) return;

              const [startV, startP] = getPt(0);
              ctx.moveTo(xScale(startV), yScale(startP));

              for(let i=1; i<loopData.length; i++) {
                  const [v, p] = getPt(i);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();

              // Head Dot
              const [endV, endP] = getPt(loopData.length-1);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(endV), yScale(endP), 3, 0, 2 * Math.PI);
              ctx.fill();
          };

          visibleChambers.forEach(c => drawChamberLoop(c));
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(containerRef.current);

    return () => {
        cancelAnimationFrame(animationFrameId);
        resizeObserver.disconnect();
    }
  }, [instances, visibleChambers, showGuides]);

  return (
    <div ref={containerRef} className="w-full h-full relative">
      <canvas ref={canvasRef} className="block" />
    </div>
  );
};

// --------------------------------------------------------
// 2. Sweep Waveform Monitor (Eraser Bar Strategy)
// --------------------------------------------------------
export const WaveformMonitor: React.FC<WaveformMonitorProps> = ({ physicsRefs, instances, timeWindow, enabledSignals }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        // Fixed Scale for Pressure (can be auto-scaled too if needed, but usually fixed for monitors)
        // Let's stick to fixed 0-160 for now or slight auto. 
        // User didn't explicitly ask for auto-scale on waveform Y-axis, but auto-scale is generally good.
        // Let's keep 0-160 as base but maybe extend if values go higher.
        // For now, fixed 0-180 to cover normal range.
        const yMin = 0;
        const yMax = 180;
        const yScale = (p: number) => height - ((p - yMin) / (yMax - yMin)) * height;

        let animationFrameId: number;

        const render = () => {
            ctx.clearRect(0, 0, width, height);

            // Determine latest global time to sync the sweep
            let maxT = 0;
            instances.forEach(inst => {
                if(!inst.isVisible) return;
                const p = physicsRefs.current.get(inst.id);
                if(p && p.t > maxT) maxT = p.t;
            });

            if (maxT === 0) {
                 animationFrameId = requestAnimationFrame(render);
                 return;
            }

            // Draw each instance
            instances.forEach(inst => {
                if (!inst.isVisible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 2) return;

                // 1. Filter data to ONLY include points within [maxT - timeWindow, maxT]
                // This prevents overlapping "old" data from previous loops if buffer is large.
                // We assume physics steps are small enough that we don't miss data.
                const validData = phys.buffer.filter(p => p.t > maxT - timeWindow);

                const drawSignal = (sig: SignalType, dash: number[]) => {
                    ctx.beginPath();
                    ctx.strokeStyle = inst.color;
                    ctx.lineWidth = 2;
                    ctx.setLineDash(dash);

                    let first = true;
                    let prevX = -1;

                    // Downsample for rendering
                    const step = 2; 

                    for(let i=0; i<validData.length; i+=step) {
                        const pt = validData[i];
                        const t = pt.t;

                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }

                        // Map time to X [0, width]
                        // We use maxT to define the phase, but here we just map t % window
                        const x = (t % timeWindow) / timeWindow * width;
                        const y = yScale(val);

                        if (first) {
                            ctx.moveTo(x, y);
                            first = false;
                        } else {
                            // Detect wrap around: if current x is significantly smaller than prevX
                            if (x < prevX) {
                                ctx.moveTo(x, y);
                            } else {
                                ctx.lineTo(x, y);
                            }
                        }
                        prevX = x;
                    }
                    ctx.stroke();
                    ctx.setLineDash([]);
                };

                if (enabledSignals.has('Plv')) drawSignal('Plv', []);
                if (enabledSignals.has('AoP')) drawSignal('AoP', [2, 2]);
                if (enabledSignals.has('Pla')) drawSignal('Pla', [5, 5]);
                if (enabledSignals.has('Prv')) drawSignal('Prv', []); 
                if (enabledSignals.has('Pra')) drawSignal('Pra', [5, 5]);
                if (enabledSignals.has('PAP')) drawSignal('PAP', [2, 2]);
            });

            // 2. Draw "Eraser" Bar
            // The cursor is at (maxT % timeWindow).
            // We want to clear a small segment AHEAD of the cursor to simulate the "scan" rewrite.
            const cursorX = (maxT % timeWindow) / timeWindow * width;
            const eraseMs = 200; // 200ms gap
            const eraseWidth = (eraseMs / timeWindow) * width;

            // We clearRect. This will show the transparent background (CSS grid).
            // Handle wrap around of the eraser
            ctx.clearRect(cursorX, 0, eraseWidth, height);
            if (cursorX + eraseWidth > width) {
                ctx.clearRect(0, 0, (cursorX + eraseWidth) % width, height);
            }

            // 3. Draw Head Circles (Latest Point)
            // Drawn AFTER erasing so they aren't cut off if eraser is tight.
            instances.forEach(inst => {
                if (!inst.isVisible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length === 0) return;

                // Get the very last computed point (head)
                const pt = phys.buffer[phys.buffer.length - 1];
                const x = (pt.t % timeWindow) / timeWindow * width;

                // If x is inside the eraser region (it shouldn't be effectively, as eraser is ahead),
                // but just in case, we draw it on top.

                const drawHead = (sig: SignalType) => {
                     let val = 0;
                     switch(sig) {
                        case 'Plv': val = pt.aux.Plv; break;
                        case 'Pla': val = pt.aux.Pla; break;
                        case 'Prv': val = pt.aux.Prv; break;
                        case 'Pra': val = pt.aux.Pra; break;
                        case 'AoP': val = pt.aux.AoP; break;
                        case 'PAP': val = pt.aux.PAP; break;
                    }
                    const y = yScale(val);
                    ctx.beginPath();
                    ctx.fillStyle = inst.color;
                    ctx.arc(x, y, 3, 0, 2 * Math.PI);
                    ctx.fill();
                    // White border for visibility
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.stroke();
                };

                if (enabledSignals.has('Plv')) drawHead('Plv');
                if (enabledSignals.has('AoP')) drawHead('AoP');
                if (enabledSignals.has('Pla')) drawHead('Pla');
                if (enabledSignals.has('Prv')) drawHead('Prv'); 
                if (enabledSignals.has('Pra')) drawHead('Pra');
                if (enabledSignals.has('PAP')) drawHead('PAP');
            });

            animationFrameId = requestAnimationFrame(render);
        };

        render();

        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);

        return () => {
            cancelAnimationFrame(animationFrameId);
            resizeObserver.disconnect();
        }
    }, [instances, timeWindow, enabledSignals]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            {/* CSS Grid Background */}
            <div className="absolute inset-0 pointer-events-none" 
                 style={{ 
                     backgroundImage: 'linear-gradient(#334155 1px, transparent 1px), linear-gradient(90deg, #334155 1px, transparent 1px)', 
                     backgroundSize: '40px 40px',
                     opacity: 0.3
                 }} 
            />
            <canvas ref={canvasRef} className="block relative z-10" />

            {/* Legend / Info */}
            <div className="absolute top-2 right-2 flex flex-col items-end pointer-events-none">
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded">Window: {timeWindow/1000}s</span>
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded mt-1">Scale: 0-180 mmHg</span>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, StateVector, SimInstance, ChamberId, PhysicsRefState, SignalType } from './types';
import { stepRK4 } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopChart, WaveformMonitor } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [visibleChambers, setVisibleChambers] = useState<Set<ChamberId>>(new Set(['LV']));
  const [showGuides, setShowGuides] = useState<boolean>(true);
  const [waveformWindow, setWaveformWindow] = useState<number>(10000); // 10s default

  // Signals (Scale is now auto, so state removed)
  const [enabledSignals, setEnabledSignals] = useState<Set<SignalType>>(new Set(['Plv', 'AoP']));

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], params: { ...DEFAULT_PARAMS }, isVisible: true }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Physics Refs ---
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());

  // Init physics refs for new instances
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              physicsRefs.current.set(inst.id, {
                  t: INITIAL_TIME,
                  y: [...INITIAL_STATE_VECTOR],
                  buffer: [],
                  lastRenderX: 0
              });
          }
      });
      // Cleanup deleted instances
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) {
              physicsRefs.current.delete(id);
          }
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; // ms
    const baseStepsPerFrame = 8; 

    const loop = () => {
      const stepsToRun = Math.round(baseStepsPerFrame * timeScale);

      for (let i = 0; i < stepsToRun; i++) {
         instances.forEach(inst => {
             const phys = physicsRefs.current.get(inst.id);
             if (!phys) return;

             // Step Physics
             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, inst.params);

             // Update Ref
             phys.t = tNext;
             phys.y = yNext;

             // Add to Buffer
             // We need to keep enough data for the waveform window + a bit extra to be safe
             const bufferRequiredMs = Math.max(waveformWindow + 1000, 5000);
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };

            phys.buffer.push(output);

            // Prune Buffer
            const cutoffTime = tNext - bufferRequiredMs;
            if (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }

      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => cancelAnimationFrame(animationFrameId);
  }, [instances, timeScale, waveformWindow]);

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];
      const newInst: SimInstance = {
          id: newId,
          name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color: color,
          params: { ...DEFAULT_PARAMS }, // Copy default
          isVisible: true
      };
      setInstances(prev => [...prev, newInst]);
      setActiveInstanceId(newId);
  };

  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) {
          setActiveInstanceId(instances[0]?.id || '');
      }
  };

  const toggleInstanceVisibility = (id: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, isVisible: !inst.isVisible } : inst
    ));
  };

  const toggleChamber = (c: ChamberId) => {
    setVisibleChambers(prev => {
        const next = new Set(prev);
        if (next.has(c)) next.delete(c);
        else next.add(c);
        return next;
    });
  };

  const toggleSignal = (s: SignalType) => {
      setEnabledSignals(prev => {
          const next = new Set(prev);
          if (next.has(s)) next.delete(s);
          else next.add(s);
          return next;
      });
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      {/* Sidebar Controls */}
      <aside className="w-80 h-full bg-slate-900 border-r border-slate-800 overflow-y-auto flex-shrink-0 z-20 shadow-xl">
        <div className="p-5">
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
            HemoSim 0D
          </h1>
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            toggleInstanceVisibility={toggleInstanceVisibility}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            visibleChambers={visibleChambers} toggleChamber={toggleChamber}
            showGuides={showGuides} setShowGuides={setShowGuides}
            waveformWindow={waveformWindow} setWaveformWindow={setWaveformWindow}
          />
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative bg-slate-950">

        {/* Top: PV Loop Panel */}
        <div className="h-1/2 p-4 min-h-0">
          <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner overflow-hidden relative group">
            {/* Header */}
            <div className="absolute top-4 left-4 z-10 flex gap-2 pointer-events-auto">
                <div className="bg-slate-950/80 px-3 py-1 rounded-full border border-slate-800 backdrop-blur-sm">
                    <span className="text-sm font-semibold text-slate-200">PV Loop (Auto-Scale)</span>
                </div>
            </div>

            <div className="flex-1 w-full h-full p-2">
                <PVLoopChart 
                    physicsRefs={physicsRefs}
                    instances={instances}
                    visibleChambers={visibleChambers}
                    showGuides={showGuides}
                />
            </div>
          </div>
        </div>

        {/* Bottom: Waveform Monitor */}
        <div className="h-1/2 p-4 pt-0 min-h-[200px]">
            <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner relative overflow-hidden">
                {/* Header */}
                <div className="absolute top-2 left-4 z-10 flex gap-2 items-center pointer-events-auto max-w-full overflow-x-auto p-1">
                    <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide mr-2">Monitor</span>
                    {(['Plv', 'AoP', 'Pla', 'Prv', 'PAP', 'Pra'] as SignalType[]).map(sig => (
                        <button
                            key={sig}
                            onClick={() => toggleSignal(sig)}
                            className={`px-2 py-0.5 text-[10px] font-bold rounded border ${enabledSignals.has(sig) ? 'bg-slate-700 text-slate-200 border-slate-600' : 'bg-transparent text-slate-500 border-slate-800 hover:border-slate-700'}`}
                        >
                            {sig}
                        </button>
                    ))}
                </div>

                <div className="flex-1 w-full h-full p-2 mt-6">
                    <WaveformMonitor 
                        physicsRefs={physicsRefs}
                        instances={instances}
                        timeWindow={waveformWindow}
                        enabledSignals={enabledSignals}
                    />
                </div>
            </div>
        </div>
      </main>
    </div>
  );
}

export default App;

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { SimulationOutput, SimInstance, PhysicsRefState, ChamberId, SignalType } from '../types';

interface PVLoopChartProps {
  physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
  instances: SimInstance[];
  visibleChambers: Set<ChamberId>;
  showGuides: boolean;
}

interface WaveformMonitorProps {
    physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
    instances: SimInstance[];
    timeWindow: number; // in ms
    enabledSignals: Set<SignalType>;
}

// Helper to generate variations of the instance color for different signals
const getSignalColor = (baseColor: string, signal: SignalType): string => {
    const c = d3.color(baseColor);
    if (!c) return baseColor;

    switch (signal) {
        case 'Plv': 
        case 'Prv':
            // Ventricles: Base Color (Solid, Strong)
            return c.formatHex();
        case 'AoP': 
        case 'PAP':
            // Arteries: Brighter/Lighter (Distinct from Ventricle)
            return c.brighter(1.2).formatHex();
        case 'Pla': 
        case 'Pra':
            // Atria: Darker/Desaturated (Background context)
            return c.darker(1.0).formatHex();
        default:
            return c.formatHex();
    }
};

// --------------------------------------------------------
// 1. D3 Canvas PV Loop (Multi-Instance + Hysteresis Auto-Scaling)
// --------------------------------------------------------
export const PVLoopChart: React.FC<PVLoopChartProps> = ({ physicsRefs, instances, visibleChambers, showGuides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // State for scaling hysteresis to prevent jitter
  const scaleRef = useRef({ maxV: 300, maxP: 200 });

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // High DPI setup
    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    // D3 Scales
    const xScale = d3.scaleLinear().domain([0, 300]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 200]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // --- 1. Determine Data Bounds ---
      let currentFrameMaxV = 0;
      let currentFrameMaxP = 0;
      let hasData = false;

      instances.forEach(inst => {
          if (!inst.isVisible) return;
          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          // Sample data (last 1000 points is enough for detecting current loop bounds)
          // Using a larger step to keep performance high
          const data = physState.buffer.slice(-1000); 
          for (let i = 0; i < data.length; i += 5) {
              const d = data[i];
              visibleChambers.forEach(chamber => {
                  let v = 0, p = 0;
                  switch(chamber) {
                      case 'LV': v = d.y.Qlv; p = d.aux.Plv; break;
                      case 'LA': v = d.y.Qla; p = d.aux.Pla; break;
                      case 'RV': v = d.y.Qrv; p = d.aux.Prv; break;
                      case 'RA': v = d.y.Qra; p = d.aux.Pra; break;
                  }
                  if (v > currentFrameMaxV) currentFrameMaxV = v;
                  if (p > currentFrameMaxP) currentFrameMaxP = p;
                  hasData = true;
              });
          }
      });

      // --- 2. Hysteresis Scaling Logic ---
      if (hasData) {
          const PADDING = 1.1; // 10% padding
          const SHRINK_THRESHOLD = 0.8; // Only shrink if data is < 80% of current scale

          // Target scale based on current frame
          const targetMaxV = Math.max(150, currentFrameMaxV * PADDING);
          const targetMaxP = Math.max(120, currentFrameMaxP * PADDING);

          // Update Volume Scale
          if (targetMaxV > scaleRef.current.maxV) {
              // Expand immediately to prevent clipping
              scaleRef.current.maxV = targetMaxV;
          } else if (targetMaxV < scaleRef.current.maxV * SHRINK_THRESHOLD) {
              // Shrink slowly or snap if significantly smaller (snap for now to be responsive but stable)
              scaleRef.current.maxV = targetMaxV;
          }

          // Update Pressure Scale
          if (targetMaxP > scaleRef.current.maxP) {
              scaleRef.current.maxP = targetMaxP;
          } else if (targetMaxP < scaleRef.current.maxP * SHRINK_THRESHOLD) {
              scaleRef.current.maxP = targetMaxP;
          }
      }

      // Apply Scales
      // Volume starts at 0
      xScale.domain([0, scaleRef.current.maxV]).range([50, width - 20]);
      yScale.domain([0, scaleRef.current.maxP]).range([height - 40, 20]);


      // --- 3. Draw Grid & Axes ---
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();

      const xTicks = xScale.ticks(6);
      const yTicks = yScale.ticks(6);

      xTicks.forEach(t => {
        ctx.moveTo(xScale(t), height - 40);
        ctx.lineTo(xScale(t), 20);
      });
      yTicks.forEach(t => {
        ctx.moveTo(50, yScale(t));
        ctx.lineTo(width - 20, yScale(t));
      });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xTicks.forEach(t => {
        ctx.fillText(t.toString(), xScale(t), height - 25);
      });
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yTicks.forEach(t => {
        ctx.fillText(t.toString(), 45, yScale(t));
      });

      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // --- 4. Draw Loops ---
      instances.forEach(inst => {
          if (!inst.isVisible) return;
          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          const loopData = physState.buffer.slice(-1000); 

          // ESPVR/EDPVR Guides (LV only)
          if (showGuides && visibleChambers.has('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;

              const vMax = scaleRef.current.maxV;

              // ESPVR
              ctx.beginPath();
              const pesMax = inst.params.LV_Ees * (vMax - inst.params.LV_V0);
              const vIntercept = inst.params.LV_V0;

              ctx.moveTo(xScale(vIntercept), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(pesMax));
              ctx.stroke();

              // EDPVR
              ctx.beginPath();
              const startV = Math.max(0, inst.params.LV_V0);
              let firstPt = true;
              // Plot with fewer points for performance
              const stepV = (vMax - startV) / 50;
              for (let v = startV; v <= vMax; v += stepV) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > scaleRef.current.maxP) break;
                  const px = xScale(v);
                  const py = yScale(ped);
                  if (firstPt) { ctx.moveTo(px, py); firstPt = false; }
                  else ctx.lineTo(px, py);
              }
              ctx.stroke();
              ctx.restore();
          }

          const drawChamberLoop = (chamber: ChamberId) => {
              ctx.beginPath();
              ctx.strokeStyle = inst.color;
              ctx.lineWidth = 2;

              const getPt = (idx: number) => {
                  const d = loopData[idx];
                  switch(chamber) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              }

              if(loopData.length === 0) return;

              const [startV, startP] = getPt(0);
              ctx.moveTo(xScale(startV), yScale(startP));

              for(let i=1; i<loopData.length; i++) {
                  const [v, p] = getPt(i);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();

              // Head Dot
              const [endV, endP] = getPt(loopData.length-1);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(endV), yScale(endP), 3, 0, 2 * Math.PI);
              ctx.fill();
          };

          visibleChambers.forEach(c => drawChamberLoop(c));
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(containerRef.current);

    return () => {
        cancelAnimationFrame(animationFrameId);
        resizeObserver.disconnect();
    }
  }, [instances, visibleChambers, showGuides]);

  return (
    <div ref={containerRef} className="w-full h-full relative">
      <canvas ref={canvasRef} className="block" />
    </div>
  );
};

// --------------------------------------------------------
// 2. Waveform Monitor (Improved Colors & Multi-plot)
// --------------------------------------------------------
export const WaveformMonitor: React.FC<WaveformMonitorProps> = ({ physicsRefs, instances, timeWindow, enabledSignals }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        // Fixed Scale for Pressure Monitor
        const yMin = 0;
        const yMax = 160; 
        const yScale = (p: number) => height - ((p - yMin) / (yMax - yMin)) * height;

        let animationFrameId: number;

        const render = () => {
            ctx.clearRect(0, 0, width, height);

            // Determine sync time (latest time across all instances)
            let maxT = 0;
            instances.forEach(inst => {
                if(!inst.isVisible) return;
                const p = physicsRefs.current.get(inst.id);
                if(p && p.t > maxT) maxT = p.t;
            });

            if (maxT === 0) {
                 animationFrameId = requestAnimationFrame(render);
                 return;
            }

            // 1. Draw "Eraser" Bar FIRST (to create the clear gap)
            // The cursor is at (maxT % timeWindow).
            const cursorX = (maxT % timeWindow) / timeWindow * width;
            const eraseMs = 300; // 300ms gap for clearer separation
            const eraseWidth = (eraseMs / timeWindow) * width;

            ctx.clearRect(cursorX, 0, eraseWidth, height);
            if (cursorX + eraseWidth > width) {
                ctx.clearRect(0, 0, (cursorX + eraseWidth) % width, height);
            }

            // 2. Draw Signals for ALL instances
            instances.forEach(inst => {
                if (!inst.isVisible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 2) return;

                // Only draw data within the current window to avoid ghosting
                // We add a small buffer to 'maxT' filtering to ensure we don't lose the connecting line at the edge
                const validData = phys.buffer.filter(p => p.t > maxT - timeWindow - 100);

                const drawSignal = (sig: SignalType) => {
                    ctx.beginPath();
                    // Generate color based on instance color + signal type
                    ctx.strokeStyle = getSignalColor(inst.color, sig);
                    ctx.lineWidth = 2;
                    // Remove dash logic, use solid lines with distinct colors
                    ctx.setLineDash([]);

                    let first = true;
                    let prevX = -1;
                    const step = 2; // Downsample

                    for(let i=0; i<validData.length; i+=step) {
                        const pt = validData[i];
                        const t = pt.t;

                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }

                        const x = (t % timeWindow) / timeWindow * width;
                        const y = yScale(val);

                        // If x is currently inside the "eraser" zone, don't draw it 
                        // (Visual polish to ensure clean cut)
                        // This logic is complex with wrapping, so we rely on clearRect above.
                        // However, since we draw AFTER clearRect, we might draw INTO the cleared zone if validData includes it.
                        // Filter validData to exclude the future gap? 
                        // t % window > maxT % window && t % window < maxT % window + gap
                        // Simplified: The data filter (p.t > maxT - timeWindow) mostly handles history.
                        // The future gap is naturally empty because we haven't simulated it yet.
                        // The only overlap is the old history wrapping around.

                        if (first) {
                            ctx.moveTo(x, y);
                            first = false;
                        } else {
                            // Detect wrap
                            if (x < prevX) {
                                ctx.moveTo(x, y);
                            } else {
                                ctx.lineTo(x, y);
                            }
                        }
                        prevX = x;
                    }
                    ctx.stroke();
                };

                if (enabledSignals.has('Plv')) drawSignal('Plv');
                if (enabledSignals.has('AoP')) drawSignal('AoP');
                if (enabledSignals.has('Pla')) drawSignal('Pla');
                if (enabledSignals.has('Prv')) drawSignal('Prv'); 
                if (enabledSignals.has('Pra')) drawSignal('Pra');
                if (enabledSignals.has('PAP')) drawSignal('PAP');
            });

            // 3. Draw Head Circles (Latest Point)
            instances.forEach(inst => {
                if (!inst.isVisible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length === 0) return;

                const pt = phys.buffer[phys.buffer.length - 1];
                const x = (pt.t % timeWindow) / timeWindow * width;

                const drawHead = (sig: SignalType) => {
                     let val = 0;
                     switch(sig) {
                        case 'Plv': val = pt.aux.Plv; break;
                        case 'Pla': val = pt.aux.Pla; break;
                        case 'Prv': val = pt.aux.Prv; break;
                        case 'Pra': val = pt.aux.Pra; break;
                        case 'AoP': val = pt.aux.AoP; break;
                        case 'PAP': val = pt.aux.PAP; break;
                    }
                    const y = yScale(val);
                    ctx.beginPath();
                    ctx.fillStyle = getSignalColor(inst.color, sig);
                    ctx.arc(x, y, 4, 0, 2 * Math.PI);
                    ctx.fill();
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.stroke();
                };

                if (enabledSignals.has('Plv')) drawHead('Plv');
                if (enabledSignals.has('AoP')) drawHead('AoP');
                if (enabledSignals.has('Pla')) drawHead('Pla');
                if (enabledSignals.has('Prv')) drawHead('Prv'); 
                if (enabledSignals.has('Pra')) drawHead('Pra');
                if (enabledSignals.has('PAP')) drawHead('PAP');
            });

            animationFrameId = requestAnimationFrame(render);
        };

        render();

        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);

        return () => {
            cancelAnimationFrame(animationFrameId);
            resizeObserver.disconnect();
        }
    }, [instances, timeWindow, enabledSignals]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            {/* CSS Grid Background */}
            <div className="absolute inset-0 pointer-events-none" 
                 style={{ 
                     backgroundImage: 'linear-gradient(#334155 1px, transparent 1px), linear-gradient(90deg, #334155 1px, transparent 1px)', 
                     backgroundSize: '40px 40px',
                     opacity: 0.3
                 }} 
            />
            <canvas ref={canvasRef} className="block relative z-10" />

            {/* Legend / Info */}
            <div className="absolute top-2 right-2 flex flex-col items-end pointer-events-none z-20">
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded">Window: {timeWindow/1000}s</span>
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded mt-1">Scale: 0-160 mmHg</span>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, StateVector, SimInstance, ChamberId, PhysicsRefState, SignalType } from './types';
import { stepRK4 } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopChart, WaveformMonitor } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [visibleChambers, setVisibleChambers] = useState<Set<ChamberId>>(new Set(['LV']));
  const [showGuides, setShowGuides] = useState<boolean>(true);
  const [waveformWindow, setWaveformWindow] = useState<number>(10000); // 10s default

  // Signals (Scale is now auto, so state removed)
  const [enabledSignals, setEnabledSignals] = useState<Set<SignalType>>(new Set(['Plv', 'AoP']));

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], params: { ...DEFAULT_PARAMS }, isVisible: true }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Physics Refs ---
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());

  // Init physics refs for new instances
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              // SYNCHRONIZATION FIX:
              // Find the current maximum simulation time from existing instances.
              // If we start at INITIAL_TIME while others are at t=20000, the new one won't show up on the monitor.
              let syncTime = INITIAL_TIME;
              if (physicsRefs.current.size > 0) {
                  for (const p of physicsRefs.current.values()) {
                      if (p.t > syncTime) syncTime = p.t;
                  }
              }

              physicsRefs.current.set(inst.id, {
                  t: syncTime, 
                  y: [...INITIAL_STATE_VECTOR],
                  buffer: [],
                  lastRenderX: 0
              });
          }
      });
      // Cleanup deleted instances
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) {
              physicsRefs.current.delete(id);
          }
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; // ms
    const baseStepsPerFrame = 8; 

    const loop = () => {
      const stepsToRun = Math.round(baseStepsPerFrame * timeScale);

      for (let i = 0; i < stepsToRun; i++) {
         instances.forEach(inst => {
             const phys = physicsRefs.current.get(inst.id);
             if (!phys) return;

             // Step Physics
             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, inst.params);

             // Update Ref
             phys.t = tNext;
             phys.y = yNext;

             // Add to Buffer
             // We need to keep enough data for the waveform window + a bit extra to be safe
             const bufferRequiredMs = Math.max(waveformWindow + 1000, 5000);
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };

            phys.buffer.push(output);

            // Prune Buffer
            const cutoffTime = tNext - bufferRequiredMs;
            if (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }

      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => cancelAnimationFrame(animationFrameId);
  }, [instances, timeScale, waveformWindow]);

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];
      const newInst: SimInstance = {
          id: newId,
          name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color: color,
          params: { ...DEFAULT_PARAMS }, // Copy default
          isVisible: true
      };
      setInstances(prev => [...prev, newInst]);
      setActiveInstanceId(newId);
  };

  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) {
          setActiveInstanceId(instances[0]?.id || '');
      }
  };

  const toggleInstanceVisibility = (id: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, isVisible: !inst.isVisible } : inst
    ));
  };

  const toggleChamber = (c: ChamberId) => {
    setVisibleChambers(prev => {
        const next = new Set(prev);
        if (next.has(c)) next.delete(c);
        else next.add(c);
        return next;
    });
  };

  const toggleSignal = (s: SignalType) => {
      setEnabledSignals(prev => {
          const next = new Set(prev);
          if (next.has(s)) next.delete(s);
          else next.add(s);
          return next;
      });
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      {/* Sidebar Controls */}
      <aside className="w-80 h-full bg-slate-900 border-r border-slate-800 overflow-y-auto flex-shrink-0 z-20 shadow-xl">
        <div className="p-5">
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
            HemoSim 0D
          </h1>
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            toggleInstanceVisibility={toggleInstanceVisibility}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            visibleChambers={visibleChambers} toggleChamber={toggleChamber}
            showGuides={showGuides} setShowGuides={setShowGuides}
            waveformWindow={waveformWindow} setWaveformWindow={setWaveformWindow}
          />
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative bg-slate-950">

        {/* Top: PV Loop Panel */}
        <div className="h-1/2 p-4 min-h-0">
          <div className="h-full w-full bg-slate-900/50 rounded-2xl border border-slate-800 flex flex-col shadow-inner overflow-hidden relative group">
