                    <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide mr-2">Monitor</span>
                    {(['Plv', 'AoP', 'Pla', 'Prv', 'PAP', 'Pra'] as SignalType[]).map(sig => (
