export default App;

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { SimInstance, PhysicsRefState, ChamberId, SignalType } from '../types';

interface PVLoopChartProps {
  physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
  instances: SimInstance[];
  visibleChambers: Set<ChamberId>;
  showGuides: boolean;
}

interface WaveformMonitorProps {
    physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
    instances: SimInstance[];
    timeWindow: number; // in ms
    enabledSignals: Set<SignalType>;
}

// Helper to generate distinct colors for different signals based on instance color
const getSignalColor = (baseColor: string, signal: SignalType): string => {
    const c = d3.color(baseColor);
    if (!c) return baseColor;

    switch (signal) {
        case 'Plv': 
        case 'Prv':
            // Ventricles: Base Color (Solid, Strong)
            return c.formatHex();
        case 'AoP': 
        case 'PAP':
            // Arteries: Much Lighter / Pastel
            return c.brighter(1.5).formatHex();
        case 'Pla': 
        case 'Pra':
            // Atria: Darker / Muted
            return c.darker(0.8).formatHex();
        default:
            return c.formatHex();
    }
};

// --------------------------------------------------------
// 1. D3 Canvas PV Loop (Multi-Instance + Discrete Step Auto-Scaling)
// --------------------------------------------------------
export const PVLoopChart: React.FC<PVLoopChartProps> = ({ physicsRefs, instances, visibleChambers, showGuides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // State for scaling hysteresis (discrete steps)
  const scaleRef = useRef({ maxV: 300, maxP: 200 });

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // High DPI setup
    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    // D3 Scales
    const xScale = d3.scaleLinear().domain([0, 300]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 200]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // --- 1. Determine Data Bounds ---
      let currentFrameMaxV = 0;
      let currentFrameMaxP = 0;
      let hasData = false;

      instances.forEach(inst => {
          if (!inst.isVisible) return;
          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          const data = physState.buffer.slice(-1000); 
          for (let i = 0; i < data.length; i += 10) {
              const d = data[i];
              visibleChambers.forEach(chamber => {
                  let v = 0, p = 0;
                  switch(chamber) {
                      case 'LV': v = d.y.Qlv; p = d.aux.Plv; break;
                      case 'LA': v = d.y.Qla; p = d.aux.Pla; break;
                      case 'RV': v = d.y.Qrv; p = d.aux.Prv; break;
                      case 'RA': v = d.y.Qra; p = d.aux.Pra; break;
                  }
                  if (v > currentFrameMaxV) currentFrameMaxV = v;
                  if (p > currentFrameMaxP) currentFrameMaxP = p;
                  hasData = true;
              });
          }
      });

      // --- 2. Discrete Scaling Logic ---
      if (hasData) {
          // Add margin
          currentFrameMaxV *= 1.1; 
          currentFrameMaxP *= 1.1;

          // Expand logic: If data exceeds current view, jump up.
          if (currentFrameMaxV > scaleRef.current.maxV) {
               scaleRef.current.maxV = Math.ceil(currentFrameMaxV / 50) * 50;
          }
          if (currentFrameMaxP > scaleRef.current.maxP) {
               scaleRef.current.maxP = Math.ceil(currentFrameMaxP / 50) * 50;
          }

          // Shrink logic: If data is significantly smaller (e.g., < 70%), step down.
          // This creates the "discrete" feel and prevents jitter.
          if (currentFrameMaxV < scaleRef.current.maxV * 0.7 && scaleRef.current.maxV > 150) {
              // Smoothly step down to match data (with padding)
              const newMax = Math.ceil(currentFrameMaxV / 50) * 50;
              scaleRef.current.maxV = Math.max(150, newMax);
          }
          if (currentFrameMaxP < scaleRef.current.maxP * 0.7 && scaleRef.current.maxP > 100) {
              const newMax = Math.ceil(currentFrameMaxP / 50) * 50;
              scaleRef.current.maxP = Math.max(120, newMax);
          }
      }

      // Apply Scales (Fixed 0 start)
      xScale.domain([0, scaleRef.current.maxV]).range([50, width - 20]);
      yScale.domain([0, scaleRef.current.maxP]).range([height - 40, 20]);

      // --- 3. Draw Grid & Axes ---
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();

      const xTicks = xScale.ticks(6);
      const yTicks = yScale.ticks(6);

      xTicks.forEach(t => {
        ctx.moveTo(xScale(t), height - 40);
        ctx.lineTo(xScale(t), 20);
      });
      yTicks.forEach(t => {
        ctx.moveTo(50, yScale(t));
        ctx.lineTo(width - 20, yScale(t));
      });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xTicks.forEach(t => {
        ctx.fillText(t.toString(), xScale(t), height - 25);
      });
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yTicks.forEach(t => {
        ctx.fillText(t.toString(), 45, yScale(t));
      });

      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // --- 4. Draw Loops ---
      instances.forEach(inst => {
          if (!inst.isVisible) return;
          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          const loopData = physState.buffer.slice(-1200); 

          // ESPVR/EDPVR Guides (LV only)
          if (showGuides && visibleChambers.has('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;

              const vMax = scaleRef.current.maxV;

              // ESPVR
              ctx.beginPath();
              const pesMax = inst.params.LV_Ees * (vMax - inst.params.LV_V0);
              const vIntercept = inst.params.LV_V0;

              ctx.moveTo(xScale(vIntercept), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(pesMax));
              ctx.stroke();

              // EDPVR
              ctx.beginPath();
              const startV = Math.max(0, inst.params.LV_V0);
              let firstPt = true;
              const stepV = (vMax - startV) / 50;
              for (let v = startV; v <= vMax; v += Math.max(1, stepV)) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > scaleRef.current.maxP) break;
                  const px = xScale(v);
                  const py = yScale(ped);
                  if (firstPt) { ctx.moveTo(px, py); firstPt = false; }
                  else ctx.lineTo(px, py);
              }
              ctx.stroke();
              ctx.restore();
          }

          const drawChamberLoop = (chamber: ChamberId) => {
              ctx.beginPath();
              ctx.strokeStyle = inst.color;
              ctx.lineWidth = 2;

              const getPt = (idx: number) => {
                  const d = loopData[idx];
                  switch(chamber) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              }

              if(loopData.length === 0) return;

              const [startV, startP] = getPt(0);
              ctx.moveTo(xScale(startV), yScale(startP));

              for(let i=1; i<loopData.length; i++) {
                  const [v, p] = getPt(i);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();

              // Head Dot
              const [endV, endP] = getPt(loopData.length-1);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(endV), yScale(endP), 3, 0, 2 * Math.PI);
              ctx.fill();
          };

          visibleChambers.forEach(c => drawChamberLoop(c));
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(containerRef.current);

    return () => {
        cancelAnimationFrame(animationFrameId);
        resizeObserver.disconnect();
    }
  }, [instances, visibleChambers, showGuides]);

  return (
    <div ref={containerRef} className="w-full h-full relative">
      <canvas ref={canvasRef} className="block" />
    </div>
  );
};

// --------------------------------------------------------
// 2. Waveform Monitor (Synced Rendering)
// --------------------------------------------------------
export const WaveformMonitor: React.FC<WaveformMonitorProps> = ({ physicsRefs, instances, timeWindow, enabledSignals }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        // Fixed Scale
        const yMin = 0;
        const yMax = 160; 
        const yScale = (p: number) => height - ((p - yMin) / (yMax - yMin)) * height;

        let animationFrameId: number;

        const render = () => {
            ctx.clearRect(0, 0, width, height);

            // Determine global sync time (the leading edge)
            let maxT = 0;
            instances.forEach(inst => {
                if(!inst.isVisible) return;
                const p = physicsRefs.current.get(inst.id);
                if(p && p.t > maxT) maxT = p.t;
            });

            if (maxT === 0) {
                 animationFrameId = requestAnimationFrame(render);
                 return;
            }

            // 1. Draw "Eraser" Bar (Global Scanline)
            const cursorX = (maxT % timeWindow) / timeWindow * width;
            const eraseMs = 250; 
            const eraseWidth = (eraseMs / timeWindow) * width;

            ctx.clearRect(cursorX, 0, eraseWidth, height);
            if (cursorX + eraseWidth > width) {
                ctx.clearRect(0, 0, (cursorX + eraseWidth) % width, height);
            }

            // 2. Draw Signals for ALL instances
            instances.forEach(inst => {
                if (!inst.isVisible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 2) return;

                // CRITICAL FIX: Filter based on THIS instance's time, not global maxT.
                // Even if synced, slight float drift can occur. 
                // Using phys.t ensures we draw the tail of THIS instance relative to itself.
                const headT = phys.t;
                const validData = phys.buffer.filter(p => p.t > headT - timeWindow - 100);

                const drawSignal = (sig: SignalType) => {
                    ctx.beginPath();
                    // Use calculated solid colors (no dashes)
                    ctx.strokeStyle = getSignalColor(inst.color, sig);
                    ctx.lineWidth = 2;
                    ctx.setLineDash([]);

                    let first = true;
                    let prevX = -1;
                    const step = 2;

                    for(let i=0; i<validData.length; i+=step) {
                        const pt = validData[i];
                        const t = pt.t;

                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }

                        const x = (t % timeWindow) / timeWindow * width;
                        const y = yScale(val);

                        // Avoid drawing into the "future" erase gap (approx check)
                        // This handles the wrap-around gap visual
                        if (first) {
                            ctx.moveTo(x, y);
                            first = false;
                        } else {
                            if (x < prevX) {
                                ctx.moveTo(x, y);
                            } else {
                                ctx.lineTo(x, y);
                            }
                        }
                        prevX = x;
                    }
                    ctx.stroke();
                };

                if (enabledSignals.has('Plv')) drawSignal('Plv');
                if (enabledSignals.has('AoP')) drawSignal('AoP');
                if (enabledSignals.has('Pla')) drawSignal('Pla');
                if (enabledSignals.has('Prv')) drawSignal('Prv'); 
                if (enabledSignals.has('Pra')) drawSignal('Pra');
                if (enabledSignals.has('PAP')) drawSignal('PAP');
            });

            // 3. Draw Head Circles
            instances.forEach(inst => {
                if (!inst.isVisible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length === 0) return;

                const pt = phys.buffer[phys.buffer.length - 1];
                const x = (pt.t % timeWindow) / timeWindow * width;

                const drawHead = (sig: SignalType) => {
                     let val = 0;
                     switch(sig) {
                        case 'Plv': val = pt.aux.Plv; break;
                        case 'Pla': val = pt.aux.Pla; break;
                        case 'Prv': val = pt.aux.Prv; break;
                        case 'Pra': val = pt.aux.Pra; break;
                        case 'AoP': val = pt.aux.AoP; break;
                        case 'PAP': val = pt.aux.PAP; break;
                    }
                    const y = yScale(val);
                    ctx.beginPath();
                    ctx.fillStyle = getSignalColor(inst.color, sig);
                    ctx.arc(x, y, 4, 0, 2 * Math.PI);
                    ctx.fill();
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.stroke();
                };

                if (enabledSignals.has('Plv')) drawHead('Plv');
                if (enabledSignals.has('AoP')) drawHead('AoP');
                if (enabledSignals.has('Pla')) drawHead('Pla');
                if (enabledSignals.has('Prv')) drawHead('Prv'); 
                if (enabledSignals.has('Pra')) drawHead('Pra');
                if (enabledSignals.has('PAP')) drawHead('PAP');
            });

            animationFrameId = requestAnimationFrame(render);
        };

        render();

        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);

        return () => {
            cancelAnimationFrame(animationFrameId);
            resizeObserver.disconnect();
        }
    }, [instances, timeWindow, enabledSignals]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            {/* CSS Grid Background */}
            <div className="absolute inset-0 pointer-events-none" 
                 style={{ 
                     backgroundImage: 'linear-gradient(#334155 1px, transparent 1px), linear-gradient(90deg, #334155 1px, transparent 1px)', 
                     backgroundSize: '40px 40px',
                     opacity: 0.3
                 }} 
            />
            <canvas ref={canvasRef} className="block relative z-10" />

            {/* Legend / Info */}
            <div className="absolute top-2 right-2 flex flex-col items-end pointer-events-none z-20">
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded">Window: {timeWindow/1000}s</span>
                <span className="text-[10px] text-slate-500 bg-slate-900/80 px-1 rounded mt-1">Scale: 0-160 mmHg</span>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, StateVector, SimInstance, ChamberId, PhysicsRefState, SignalType } from './types';
import { stepRK4 } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopChart, WaveformMonitor } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [visibleChambers, setVisibleChambers] = useState<Set<ChamberId>>(new Set(['LV']));
  const [showGuides, setShowGuides] = useState<boolean>(true);
  const [waveformWindow, setWaveformWindow] = useState<number>(10000); // 10s default

  // Signals (Scale is now auto, so state removed)
  const [enabledSignals, setEnabledSignals] = useState<Set<SignalType>>(new Set(['Plv', 'AoP']));

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], params: { ...DEFAULT_PARAMS }, isVisible: true }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Refs for values used inside animation loop to prevent restarts ---
  const timeScaleRef = useRef(timeScale);
  const waveformWindowRef = useRef(waveformWindow);
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());

  // Update refs when state changes
  useEffect(() => { timeScaleRef.current = timeScale; }, [timeScale]);
  useEffect(() => { waveformWindowRef.current = waveformWindow; }, [waveformWindow]);

  // Init physics refs for new instances
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              // SYNCHRONIZATION FIX:
              // Find the current maximum simulation time from existing instances.
              let syncTime = INITIAL_TIME;
              if (physicsRefs.current.size > 0) {
                  for (const p of physicsRefs.current.values()) {
                      if (p.t > syncTime) syncTime = p.t;
                  }
              }

              physicsRefs.current.set(inst.id, {
                  t: syncTime, 
                  y: [...INITIAL_STATE_VECTOR],
                  buffer: [],
                  lastRenderX: 0
              });
          }
      });
      // Cleanup deleted instances
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) {
              physicsRefs.current.delete(id);
          }
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; // ms
    const baseStepsPerFrame = 8; 

    const loop = () => {
      // Use Refs here to avoid dependency on state causing loop restart
      const currentScale = timeScaleRef.current;
      const currentWindow = waveformWindowRef.current;

      const stepsToRun = Math.round(baseStepsPerFrame * currentScale);

      for (let i = 0; i < stepsToRun; i++) {
         instances.forEach(inst => {
             const phys = physicsRefs.current.get(inst.id);
             if (!phys) return;

             // Step Physics
             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, inst.params);

             // Update Ref
             phys.t = tNext;
             phys.y = yNext;

             // Add to Buffer
             const bufferRequiredMs = Math.max(currentWindow + 1000, 5000);
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };

            phys.buffer.push(output);

            // Prune Buffer
            const cutoffTime = tNext - bufferRequiredMs;
            if (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }

      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => cancelAnimationFrame(animationFrameId);
  }, [instances]); // Only restart if instances structure changes (add/remove/params update)

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];
      const newInst: SimInstance = {
          id: newId,
          name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color: color,
          params: { ...DEFAULT_PARAMS }, // Copy default
          isVisible: true
      };
      setInstances(prev => [...prev, newInst]);
      setActiveInstanceId(newId);
  };

  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) {
          setActiveInstanceId(instances[0]?.id || '');
      }
  };

  const toggleInstanceVisibility = (id: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, isVisible: !inst.isVisible } : inst
    ));
  };

  const toggleChamber = (c: ChamberId) => {
    setVisibleChambers(prev => {
        const next = new Set(prev);
        if (next.has(c)) next.delete(c);
        else next.add(c);
        return next;
    });
  };

  const toggleSignal = (s: SignalType) => {
      setEnabledSignals(prev => {
          const next = new Set(prev);
          if (next.has(s)) next.delete(s);
          else next.add(s);
          return next;
      });
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      {/* Sidebar Controls */}
