    Ras: number;
    Rcs: number;
    Rvs: number;
    Ras_prox: number;
    Rcp: number;
    Rap: number;
    Rvp: number;
    Rap_prox: number;
    Rmv: number;
    Rtv: number;
    Rda: number;

    // Compliances
    Cas: number;
    Cvs: number;
    Cas_prox: number;
    Cap: number;
    Cvp: number;
    Cap_prox: number;
    Cda: number;

    // Left Ventricle
    LV_Ees: number;
    LV_V0: number;
    LV_alpha: number;
    LV_beta: number;
    LV_Tmax: number;
    LV_tau: number;
    LV_AV_delay: number;

    // Left Atrium
    LA_Ees: number;
    LA_V0: number;
