import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { SimInstance, PhysicsRefState, ChamberId, SignalType, PanelInstanceConfig, MetricType, PanelType } from '../types';

interface ChartPanelProps {
  physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
  instances: SimInstance[];
  config: PanelInstanceConfig;
  showGuides?: boolean;
}

interface WaveformProps extends ChartPanelProps {
    timeWindow: number; 
}

interface GuytonProps extends ChartPanelProps {
    type: 'GUYTON_RIGHT' | 'GUYTON_LEFT';
}

// Helper: Color logic
const getColor = (baseColor: string, signal: string, customColors?: { [key: string]: string }): string => {
    if (customColors && customColors[signal]) {
        return customColors[signal];
    }
    const c = d3.color(baseColor);
    if (!c) return baseColor;

    switch (signal) {
        // Waveform Signals
        case 'AoP': case 'PAP': case 'ABP':
            return c.brighter(1.5).formatHex(); 
        case 'Pla': case 'Pra': case 'CVP': case 'PCWP':
            return c.darker(1.2).formatHex();
        // PV Loop Chambers
        case 'LA': case 'RA':
             return c.darker(1.2).formatHex();
        default: return c.formatHex();
    }
};

// --------------------------------------------------------
// PV Loop Panel
// --------------------------------------------------------
export const PVLoopPanel: React.FC<ChartPanelProps> = ({ physicsRefs, instances, config, showGuides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const scaleRef = useRef({ maxV: 300, maxP: 200 });

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    const xScale = d3.scaleLinear().domain([0, 300]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 200]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // 1. Auto-scale calc
      let currentFrameMaxV = 0;
      let currentFrameMaxP = 0;
      let hasData = false;

      instances.forEach(inst => {
          const cfg = config[inst.id];
          if (!cfg || !cfg.visible || cfg.selectedSignals.length === 0) return;

          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          const data = physState.buffer.slice(-500); 
          for (let i = 0; i < data.length; i += 10) {
              const d = data[i];
              cfg.selectedSignals.forEach(chamber => {
                  let v = 0, p = 0;
                  switch(chamber) {
                      case 'LV': v = d.y.Qlv; p = d.aux.Plv; break;
                      case 'LA': v = d.y.Qla; p = d.aux.Pla; break;
                      case 'RV': v = d.y.Qrv; p = d.aux.Prv; break;
                      case 'RA': v = d.y.Qra; p = d.aux.Pra; break;
                  }
                  if (v > currentFrameMaxV) currentFrameMaxV = v;
                  if (p > currentFrameMaxP) currentFrameMaxP = p;
                  hasData = true;
              });
          }
      });

      if (hasData) {
          currentFrameMaxV *= 1.1; 
          currentFrameMaxP *= 1.1;
          // Smooth Lerp
          scaleRef.current.maxV = scaleRef.current.maxV * 0.9 + Math.max(150, Math.ceil(currentFrameMaxV / 50) * 50) * 0.1;
          scaleRef.current.maxP = scaleRef.current.maxP * 0.9 + Math.max(100, Math.ceil(currentFrameMaxP / 50) * 50) * 0.1;
      }

      xScale.domain([0, scaleRef.current.maxV]).range([50, width - 20]);
      yScale.domain([0, scaleRef.current.maxP]).range([height - 40, 20]);

      // 2. Draw Grid
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      xScale.ticks(6).forEach(t => { ctx.moveTo(xScale(t), height-40); ctx.lineTo(xScale(t), 20); });
      yScale.ticks(6).forEach(t => { ctx.moveTo(50, yScale(t)); ctx.lineTo(width-20, yScale(t)); });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xScale.ticks(6).forEach(t => ctx.fillText(t.toString(), xScale(t), height - 25));
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yScale.ticks(6).forEach(t => ctx.fillText(t.toString(), 45, yScale(t)));

      // Titles
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // 3. Draw Data
      instances.forEach(inst => {
          const cfg = config[inst.id];
          if (!cfg || !cfg.visible) return;

          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;
          const loopData = physState.buffer.slice(-1200); 

          if (showGuides && cfg.selectedSignals.includes('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;
              const vMax = scaleRef.current.maxV;
              // ESPVR
              ctx.beginPath();
              ctx.moveTo(xScale(inst.params.LV_V0), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(inst.params.LV_Ees * (vMax - inst.params.LV_V0)));
              ctx.stroke();
              // EDPVR
              ctx.beginPath();
              let firstPt = true;
              for (let v = Math.max(0, inst.params.LV_V0); v <= vMax; v += (vMax/50)) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > scaleRef.current.maxP) break;
                  const px = xScale(v), py = yScale(ped);
                  if(firstPt) { ctx.moveTo(px,py); firstPt=false;} else ctx.lineTo(px,py);
              }
              ctx.stroke();
              ctx.restore();
          }

          const drawLoop = (c: string) => {
              ctx.beginPath();
              ctx.strokeStyle = getColor(inst.color, c, cfg.customColors);
              ctx.lineWidth = 2;
              const getPt = (d: any) => {
                  switch(c) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              };
              if(loopData.length === 0) return;
              const [sV, sP] = getPt(loopData[0]);
              ctx.moveTo(xScale(sV), yScale(sP));
              for(let i=1; i<loopData.length; i++) {
                  const [v, p] = getPt(loopData[i]);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();
              const [eV, eP] = getPt(loopData[loopData.length-1]);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(eV), yScale(eP), 3, 0, 2*Math.PI);
              ctx.fill();
          }
          cfg.selectedSignals.forEach(c => drawLoop(c));
      });
      animationFrameId = requestAnimationFrame(render);
    };
    render();
    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(containerRef.current);
    return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
  }, [instances, config, showGuides]);

  return (
      <div ref={containerRef} className="w-full h-full relative">
         <canvas ref={canvasRef} className="block" />
      </div>
  );
};

// --------------------------------------------------------
// Waveform Panel (With Auto-Scaling)
// --------------------------------------------------------
export const WaveformPanel: React.FC<WaveformProps> = ({ physicsRefs, instances, timeWindow, config }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const scaleRef = useRef({ yMin: 0, yMax: 160 });

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        const margin = { top: 10, right: 10, bottom: 20, left: 40 };

        let animationFrameId: number;
        const render = () => {
            const innerWidth = width - margin.left - margin.right;
            const innerHeight = height - margin.top - margin.bottom;
            const yScale = d3.scaleLinear().range([margin.top + innerHeight, margin.top]);

            ctx.clearRect(0, 0, width, height);

            let localMin = 1000;
            let localMax = -1000;
            let hasData = false;
            let maxT = 0;

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys) return;
                if(phys.t > maxT) maxT = phys.t;

                if (phys.buffer.length < 2) return;
                const startTime = phys.t - timeWindow;
                const visibleData = phys.buffer.filter(p => p.t > startTime);

                if (visibleData.length === 0) return;
                const step = Math.max(1, Math.floor(visibleData.length / 200));

                for (let i = 0; i < visibleData.length; i += step) {
                     const pt = visibleData[i];
                     cfg.selectedSignals.forEach(sig => {
                         let val = 0;
                         switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                         }
                         if (val < localMin) localMin = val;
                         if (val > localMax) localMax = val;
                         hasData = true;
                     });
                }
            });

            if (hasData) {
                const range = localMax - localMin;
                const pad = Math.max(10, range * 0.1);
                const targetMin = Math.max(0, localMin - pad);
                const targetMax = localMax + pad;
                scaleRef.current.yMin = scaleRef.current.yMin * 0.9 + targetMin * 0.1;
                scaleRef.current.yMax = scaleRef.current.yMax * 0.9 + targetMax * 0.1;
            } else {
                scaleRef.current.yMin = scaleRef.current.yMin * 0.95;
                scaleRef.current.yMax = scaleRef.current.yMax * 0.95 + 160 * 0.05;
            }

            yScale.domain([scaleRef.current.yMin, scaleRef.current.yMax]);

            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(margin.left, margin.top);
            ctx.lineTo(margin.left, margin.top + innerHeight);
            ctx.stroke();

            ctx.fillStyle = '#94a3b8';
            ctx.font = '10px sans-serif';
            ctx.textAlign = 'right';
            ctx.textBaseline = 'middle';
            yScale.ticks(5).forEach(t => {
                const y = yScale(t);
                ctx.beginPath();
                ctx.moveTo(margin.left, y);
                ctx.lineTo(margin.left - 5, y);
                ctx.stroke();
                ctx.fillText(t.toString(), margin.left - 8, y);

                ctx.save();
                ctx.strokeStyle = '#334155';
                ctx.globalAlpha = 0.2;
                ctx.beginPath();
                ctx.moveTo(margin.left, y);
                ctx.lineTo(width - margin.right, y);
                ctx.stroke();
                ctx.restore();
            });

            if (maxT === 0) { animationFrameId = requestAnimationFrame(render); return; }

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;

                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 2) return;
                const validData = phys.buffer.filter(p => p.t > phys.t - timeWindow - 100);

                const drawSig = (sig: SignalType) => {
                    ctx.beginPath();
                    ctx.strokeStyle = getColor(inst.color, sig, cfg.customColors);
                    ctx.lineWidth = 2;
                    let first = true; let prevX = -1;

                    ctx.save();
                    ctx.beginPath();
                    ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
                    ctx.clip();
                    ctx.beginPath();

                    for(let i=0; i<validData.length; i+=2) {
                        const pt = validData[i];
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }
                        const xRel = (pt.t % timeWindow) / timeWindow;
                        const x = margin.left + xRel * innerWidth;
                        const y = yScale(val);

                        if(first) { ctx.moveTo(x,y); first=false; }
                        else { 
                            if(x < prevX) { ctx.stroke(); ctx.beginPath(); ctx.moveTo(x,y); }
                            else ctx.lineTo(x,y); 
                        }
                        prevX = x;
                    }
                    ctx.stroke();
                    ctx.restore();
                };
                cfg.selectedSignals.forEach(s => drawSig(s as SignalType));

                if(phys.buffer.length>0) {
                    const pt = phys.buffer[phys.buffer.length-1];
                    const xRel = (pt.t % timeWindow) / timeWindow;
                    const x = margin.left + xRel * innerWidth;

                    const drawHead = (sig: SignalType) => {
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }
                        ctx.beginPath();
                        ctx.fillStyle = getColor(inst.color, sig, cfg.customColors);
                        ctx.arc(x, yScale(val), 4, 0, 2*Math.PI);
                        ctx.fill();
                        ctx.strokeStyle='#fff'; ctx.lineWidth=1; ctx.stroke();
                    };
                    cfg.selectedSignals.forEach(s => drawHead(s as SignalType));
                }
            });

            const xRelCursor = (maxT % timeWindow) / timeWindow;
            const cursorX = margin.left + xRelCursor * innerWidth;
            const eraseWidth = (300 / timeWindow) * innerWidth; 

            ctx.save();
            ctx.beginPath();
            ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
            ctx.clip();
            ctx.clearRect(cursorX, margin.top, eraseWidth, innerHeight);
            if (cursorX + eraseWidth > width) {
                const remainder = (cursorX + eraseWidth) - (margin.left + innerWidth);
                if (remainder > 0) ctx.clearRect(margin.left, margin.top, remainder, innerHeight);
            }
            ctx.restore();

            animationFrameId = requestAnimationFrame(render);
        };
        render();
        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);
        return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
    }, [instances, timeWindow, config]);

    return (
        <div className="flex flex-col h-full w-full relative group">
            <div ref={containerRef} className="flex-1 w-full min-h-0 relative">
                <canvas ref={canvasRef} className="block relative z-10" />
            </div>
            <div className="absolute top-2 right-2 pointer-events-none z-20 opacity-50 text-[10px] text-slate-400">
                Window: {timeWindow/1000}s
            </div>
        </div>
    );
};

// --------------------------------------------------------
// Metrics Panel
// --------------------------------------------------------
export const MetricsPanel: React.FC<ChartPanelProps> = ({ physicsRefs, instances, config }) => {
    // We update metrics every 500ms to avoid UI flickering
    const [metricsData, setMetricsData] = useState<{[key:string]: {[key:string]: string}}>({});

    useEffect(() => {
        const interval = setInterval(() => {
            const nextData: any = {};

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible || cfg.selectedSignals.length === 0) return;

                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 100) return;

                const activeHR = phys.activeParams.HR;
                const cycleMs = 60000 / activeHR;

                // Get data for last cardiac cycle + buffer
                const endTime = phys.t;
                const startTime = endTime - cycleMs;
                const cycleData = phys.buffer.filter(d => d.t >= startTime);

                if (cycleData.length < 10) return;

                const calcMetrics: {[key:string]: string} = {};

                // Helpers
                const getArr = (fn: (d:any)=>number) => cycleData.map(fn);
                const max = (arr: number[]) => Math.max(...arr);
                const min = (arr: number[]) => Math.min(...arr);
                const mean = (arr: number[]) => arr.reduce((a,b)=>a+b,0)/arr.length;

                // 1. AoP (Sys/Dia)
                if (cfg.selectedSignals.includes('ABP')) {
                    const vals = getArr(d => d.aux.AoP);
                    calcMetrics['ABP'] = `${max(vals).toFixed(0)} / ${min(vals).toFixed(0)} mmHg`;
                }
                // 2. PAP (Sys/Dia)
                if (cfg.selectedSignals.includes('PAP')) {
                    const vals = getArr(d => d.aux.PAP);
                    calcMetrics['PAP'] = `${max(vals).toFixed(0)} / ${min(vals).toFixed(0)} mmHg`;
                }
                // 3. CVP (Mean Pra)
                if (cfg.selectedSignals.includes('CVP')) {
                    const vals = getArr(d => d.aux.Pra);
                    calcMetrics['CVP'] = `${mean(vals).toFixed(1)} mmHg`;
                }
                // 4. PCWP (Mean Pla)
                if (cfg.selectedSignals.includes('PCWP')) {
                    const vals = getArr(d => d.aux.Pla);
                    calcMetrics['PCWP'] = `${mean(vals).toFixed(1)} mmHg`;
                }
                // 5. SV (Max - Min LV Volume)
                const lvVols = getArr(d => d.y.Qlv);
                const sv = max(lvVols) - min(lvVols);
                if (cfg.selectedSignals.includes('SV')) {
                    calcMetrics['SV'] = `${sv.toFixed(1)} mL`;
                }
                // 6. CO
                if (cfg.selectedSignals.includes('CO')) {
                    const co = (sv * activeHR) / 1000;
                    calcMetrics['CO'] = `${co.toFixed(2)} L/min`;
                }
                // 7. Ea (Effective Arterial Elastance) approx ESP/SV
                // ESP approx max Plv.
                if (cfg.selectedSignals.includes('Ea_LV')) {
                   const plvVals = getArr(d => d.aux.Plv);
                   const esp = max(plvVals);
                   const ea = sv > 0 ? esp / sv : 0;
                   calcMetrics['Ea_LV'] = `${ea.toFixed(2)} mmHg/mL`;
                }

                nextData[inst.id] = calcMetrics;
            });
            setMetricsData(nextData);

        }, 200);
        return () => clearInterval(interval);
    }, [instances, config]);

    return (
        <div className="w-full h-full p-2 overflow-y-auto custom-scrollbar">
            {instances.map(inst => {
                const cfg = config[inst.id];
                const data = metricsData[inst.id];
                if (!cfg || !cfg.visible || !data) return null;

                return (
                    <div key={inst.id} className="mb-4 bg-slate-900/50 rounded border border-slate-800 p-2">
                         <div className="flex items-center gap-2 mb-2 border-b border-slate-700 pb-1">
                            <span className="w-2 h-2 rounded-full" style={{backgroundColor: inst.color}}></span>
                            <span className="text-xs font-bold text-slate-300">{inst.name}</span>
                         </div>
                         <div className="grid grid-cols-2 gap-2">
                             {cfg.selectedSignals.map(sig => (
                                 data[sig] ? (
                                     <div key={sig} className="flex flex-col bg-slate-950/50 p-1.5 rounded">
                                         <span className="text-[10px] text-slate-500 uppercase font-bold">{sig}</span>
                                         <span className="text-sm font-mono text-slate-200">{data[sig]}</span>
                                     </div>
                                 ) : null
                             ))}
                         </div>
                    </div>
                )
            })}
        </div>
    );
}

// --------------------------------------------------------
// Guyton & Starling Panel
// --------------------------------------------------------
export const GuytonPanel: React.FC<GuytonProps> = ({ physicsRefs, instances, config, type }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        const margin = { top: 20, right: 20, bottom: 30, left: 40 };

        let animationFrameId: number;

        const render = () => {
            const innerWidth = width - margin.left - margin.right;
            const innerHeight = height - margin.top - margin.bottom;

            ctx.clearRect(0, 0, width, height);

            // X-Axis: Preload (Pra for Right/Systemic, Pla for Left/Pulm)
            const xScale = d3.scaleLinear().domain([0, 20]).range([margin.left, margin.left + innerWidth]);
            // Y-Axis: CO (L/min)
            const yScale = d3.scaleLinear().domain([0, 15]).range([margin.top + innerHeight, margin.top]);

            // Draw Grid
            ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;
            ctx.beginPath();
            xScale.ticks(6).forEach(t => { ctx.moveTo(xScale(t), margin.top + innerHeight); ctx.lineTo(xScale(t), margin.top); });
            yScale.ticks(6).forEach(t => { ctx.moveTo(margin.left, yScale(t)); ctx.lineTo(margin.left + innerWidth, yScale(t)); });
            ctx.stroke();

            // Labels
            ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif';
            ctx.textAlign = 'center';
            xScale.ticks(6).forEach(t => ctx.fillText(t.toString(), xScale(t), margin.top + innerHeight + 15));
            ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
            yScale.ticks(6).forEach(t => ctx.fillText(t.toString(), margin.left - 5, yScale(t)));

            // Axis Titles
            ctx.textAlign = 'center';
            ctx.fillText(type === 'GUYTON_RIGHT' ? "RA Pressure (mmHg)" : "LA Pressure (mmHg)", margin.left + innerWidth / 2, height - 5);
            ctx.save();
            ctx.translate(15, margin.top + innerHeight / 2);
            ctx.rotate(-Math.PI / 2);
            ctx.fillText("CO (L/min)", 0, 0);
            ctx.restore();

            // Plot Curves per Instance
            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys) return;
                const p = phys.activeParams;
                const y = phys.y;

                // 1. Calculate Guyton Parameters based on type
                // Formula: CO = (Vol - P_pre * C_sum) / W_sum
                let vol_sys = 0, C_sum = 0, W_sum = 0;
                let P_pre_current = 0;

                if (type === 'GUYTON_RIGHT') {
                    // Systemic Circuit & Right Heart Analysis
                    // Vol = Qas_prox + Qda + Qas + Qvs
                    vol_sys = y[8] + y[9] + y[1] + y[0];
                    // C_sum = Cas_prox + Cda + Cas + Cvs
                    C_sum = p.Cas_prox + p.Cda + p.Cas + p.Cvs;
                    // W_sum = Cda*Rda + Cas*(Rda+Ras) + Cvs*(Rda+Ras+Rcs)
                    // Note: Rda is between as_prox and da. Ras is between da and as. Rcs between as and vs.
                    W_sum = p.Cda*p.Rda + p.Cas*(p.Rda + p.Ras) + p.Cvs*(p.Rda + p.Ras + p.Rcs);

                    P_pre_current = phys.buffer.length > 0 ? phys.buffer[phys.buffer.length-1].aux.Pra : 0;

                } else {
                    // Pulmonary Circuit & Left Heart Analysis
                    // Vol = Qap_prox + Qap + Qvp
                    vol_sys = y[10] + y[2] + y[3];
                    // C_sum = Cap_prox + Cap + Cvp
                    C_sum = p.Cap_prox + p.Cap + p.Cvp;
                    // W_sum = Cap*Rcp + Cvp*(Rcp+Rap)
                    // Note: Rcp is between ap_prox and ap. Rap between ap and vp.
                    W_sum = p.Cap*p.Rcp + p.Cvp*(p.Rcp + p.Rap);

                    P_pre_current = phys.buffer.length > 0 ? phys.buffer[phys.buffer.length-1].aux.Pla : 0;
                }

                // Draw Guyton Curve (Venous Return)
                ctx.beginPath();
                ctx.strokeStyle = inst.color;
                ctx.setLineDash([5, 5]);
                ctx.lineWidth = 1.5;

                // Plot from P=0 to P=MeanCirculatoryFill
                // VR = 0 when P_pre = Vol / C_sum (Mean Systemic Filling Pressure)
                const msfp = vol_sys / C_sum;

                // We plot P_pre on X, CO on Y
                // CO = (Vol - P * C) / W
                // Points: (0, Vol/W) -> (MSFP, 0)
                const co_intercept = vol_sys / W_sum; // L/min if W in min? 
                // Wait, W units. R is mmHg*min/mL ? No usually mmHg*s/mL in 0D code but HR is bpm.
                // Sim uses: dQ = P/R. If Q is mL/s, R is mmHg*s/mL. 
                // But in this code time step dt=2ms. Sim uses ms.
                // Let's check R units. R~20. P~100. Q~5. 100/20 = 5 mL/ms = 5000 mL/s = 300 L/min? No way.
                // Let's check output. CO is ~5 L/min. SV~80ml. HR~60. 
                // Typical Q in code: ~100-200 mL? No, Q is Volume in chamber.
                // dQ (flow) = P/R. dVol = flow * dt.
                // If R=1.0, P=10. Flow = 10. If this is mL/ms, that's huge.
                // Actually in this code, 'y' vector are VOLUMES (mL). 
                // 'dy' are FLOWS (mL/ms).
                // So R is mmHg / (mL/ms).
                // W = C * R = (mL/mmHg) * (mmHg*ms/mL) = ms.
                // So CO calculated = mL / ms.
                // We need to convert to L/min.
                // mL/ms * 60000 ms/min * 1L/1000mL = * 60.

                const toLMin = 60.0; 

                const pStart = 0;
                const coStart = (vol_sys - pStart * C_sum) / W_sum * toLMin;
                const pEnd = msfp;

                // Clamping for display
                const x1 = xScale(pStart);
                const y1 = yScale(coStart);
                const x2 = xScale(pEnd);
                const y2 = yScale(0);

                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.stroke();


                // 2. Draw Starling Curve (Cardiac Function)
                // CO = HR * SV
                // SV approx formula from prompt:
                // SV = Ees/(Ees+Ea) * 1/alpha * ln((P_pre + beta)/beta) - V_offset

                let Ees = 0, alpha = 0, beta = 0, V0 = 0, Ea = 0;
                let R_total = 0;

                if (type === 'GUYTON_RIGHT') {
                    // RV Output vs Pra
                    Ees = p.RV_Ees; alpha = p.RV_alpha; beta = p.RV_beta; V0 = p.RV_V0;
                    // Ea approx for RV = Resistance of Pulm / CycleTime
                    // R_pulm = Rap_prox + Rcp + Rap + Rvp
                    R_total = p.Rap_prox + p.Rcp + p.Rap + p.Rvp;
                } else {
                    // LV Output vs Pla
                    Ees = p.LV_Ees; alpha = p.LV_alpha; beta = p.LV_beta; V0 = p.LV_V0;
                    // R_sys = Ras_prox + Rda + Ras + Rcs + Rvs
                    R_total = p.Ras_prox + p.Rda + p.Ras + p.Rcs + p.Rvs;
                }

                // Ea in mmHg / mL (Volume).
                // Ea = R_total (mmHg*ms/mL) / CycleTime (ms) ?
                // No, Ea = Pes / SV approx R * Rate.
                // R units: mmHg / (mL/ms). Rate units: 1/ms.
                // R * Rate = mmHg/mL. Correct.
                const T = 60000 / p.HR; // ms
                Ea = R_total / T;

                ctx.beginPath();
                ctx.strokeStyle = inst.color;
                ctx.setLineDash([]);
                ctx.lineWidth = 2;

                let first = true;
                for (let px = 0; px <= 25; px += 0.5) {
                    // Using formula from prompt (with V0 correction assumption)
                    // CO = HR * [ ... ]
                    // Term inside: Ees/(Ees+Ea) * 1/alpha * ln((P+b)/b) - V0
                    // Note: V0 should be roughly unstressed vol. 
                    // Prompt says: CO = HR [ gamma ( ... ) + omega ]
                    // We assume gamma=1, omega = -V0.

                    const term = (Ees / (Ees + Ea)) * (1.0 / alpha) * Math.log((px + beta) / beta);
                    const sv_est = Math.max(0, term - V0);
                    const co_est = (sv_est * p.HR) / 1000.0; // L/min

                    const cx = xScale(px);
                    const cy = yScale(co_est);

                    if (cy < margin.top + innerHeight && cy > margin.top) {
                        if (first) { ctx.moveTo(cx, cy); first = false; }
                        else ctx.lineTo(cx, cy);
                    }
                }
                ctx.stroke();

                // 3. Operating Point
                // Get current average CO and Preload from metrics logic
                if (phys.buffer.length > 100) {
                     const lastCycle = phys.buffer.slice(-Math.floor(T/2.0)); // sample last bit
                     const avgP = lastCycle.reduce((a, b) => a + (type === 'GUYTON_RIGHT' ? b.aux.Pra : b.aux.Pla), 0) / lastCycle.length;
                     // Calculate CO from Q flows. 
                     // LV Flow out = dQlv (filling) - dQlv (ejection). Complex.
                     // Easier: CO approx sum(Iasp)/time or just use Starling estimate at P_current?
                     // Better: use the actual average flow.
                     // Iasp (LV out), Iapp (RV out).
                     const flowKey = type === 'GUYTON_RIGHT' ? 'Iapp' : 'Iasp'; // Iapp is RV ejection
                     // Wait, aux has 'Imv' and 'Iasp'. RV flow 'Iapp' is not in aux by default in stepRK4 but calculated in rhs.
                     // rhs returns aux with specific fields. 'Iapp' is missing in physics.ts aux!
                     // We will approximate CO from SV * HR.
                     // SV = max(V) - min(V).
                     const vols = lastCycle.map(z => type === 'GUYTON_RIGHT' ? z.y.Qrv : z.y.Qlv);
                     const sv_real = Math.max(...vols) - Math.min(...vols);
                     const co_real = (sv_real * p.HR) / 1000.0;

                     ctx.beginPath();
                     ctx.fillStyle = inst.color;
                     ctx.arc(xScale(avgP), yScale(co_real), 5, 0, 2*Math.PI);
                     ctx.fill();
                     ctx.stroke();
                }

            });

            animationFrameId = requestAnimationFrame(render);
        };
        render();
        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);
        return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
    }, [instances, config, type]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            <canvas ref={canvasRef} className="block" />
        </div>
    );
};

import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { SimInstance, PhysicsRefState, ChamberId, SignalType, PanelInstanceConfig, MetricType, PanelType } from '../types';

interface ChartPanelProps {
  physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
  instances: SimInstance[];
  config: PanelInstanceConfig;
  showGuides?: boolean;
}

interface WaveformProps extends ChartPanelProps {
    timeWindow: number; 
}

interface GuytonProps extends ChartPanelProps {
    type: 'GUYTON_RIGHT' | 'GUYTON_LEFT';
}

// Helper: Color logic
const getColor = (baseColor: string, signal: string, customColors?: { [key: string]: string }): string => {
    if (customColors && customColors[signal]) {
        return customColors[signal];
    }
    const c = d3.color(baseColor);
    if (!c) return baseColor;

    switch (signal) {
        // Waveform Signals
        case 'AoP': case 'PAP': case 'ABP':
            return c.brighter(1.5).formatHex(); 
        case 'Pla': case 'Pra': case 'CVP': case 'PCWP':
            return c.darker(1.2).formatHex();
        // PV Loop Chambers
        case 'LA': case 'RA':
             return c.darker(1.2).formatHex();
        default: return c.formatHex();
    }
};

// --------------------------------------------------------
// PV Loop Panel
// --------------------------------------------------------
export const PVLoopPanel: React.FC<ChartPanelProps> = ({ physicsRefs, instances, config, showGuides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const scaleRef = useRef({ maxV: 300, maxP: 200 });

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    const xScale = d3.scaleLinear().domain([0, 300]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 200]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // 1. Auto-scale calc
      let currentFrameMaxV = 0;
      let currentFrameMaxP = 0;
      let hasData = false;

      instances.forEach(inst => {
          const cfg = config[inst.id];
          if (!cfg || !cfg.visible || cfg.selectedSignals.length === 0) return;

          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          const data = physState.buffer.slice(-500); 
          for (let i = 0; i < data.length; i += 10) {
              const d = data[i];
              cfg.selectedSignals.forEach(chamber => {
                  let v = 0, p = 0;
                  switch(chamber) {
                      case 'LV': v = d.y.Qlv; p = d.aux.Plv; break;
                      case 'LA': v = d.y.Qla; p = d.aux.Pla; break;
                      case 'RV': v = d.y.Qrv; p = d.aux.Prv; break;
                      case 'RA': v = d.y.Qra; p = d.aux.Pra; break;
                  }
                  if (v > currentFrameMaxV) currentFrameMaxV = v;
                  if (p > currentFrameMaxP) currentFrameMaxP = p;
                  hasData = true;
              });
          }
      });

      if (hasData) {
          currentFrameMaxV *= 1.1; 
          currentFrameMaxP *= 1.1;
          // Smooth Lerp
          scaleRef.current.maxV = scaleRef.current.maxV * 0.9 + Math.max(150, Math.ceil(currentFrameMaxV / 50) * 50) * 0.1;
          scaleRef.current.maxP = scaleRef.current.maxP * 0.9 + Math.max(100, Math.ceil(currentFrameMaxP / 50) * 50) * 0.1;
      }

      xScale.domain([0, scaleRef.current.maxV]).range([50, width - 20]);
      yScale.domain([0, scaleRef.current.maxP]).range([height - 40, 20]);

      // 2. Draw Grid
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      xScale.ticks(6).forEach(t => { ctx.moveTo(xScale(t), height-40); ctx.lineTo(xScale(t), 20); });
      yScale.ticks(6).forEach(t => { ctx.moveTo(50, yScale(t)); ctx.lineTo(width-20, yScale(t)); });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xScale.ticks(6).forEach(t => ctx.fillText(t.toString(), xScale(t), height - 25));
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yScale.ticks(6).forEach(t => ctx.fillText(t.toString(), 45, yScale(t)));

      // Titles
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // 3. Draw Data
      instances.forEach(inst => {
          const cfg = config[inst.id];
          if (!cfg || !cfg.visible) return;

          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;
          const loopData = physState.buffer.slice(-1200); 

          if (showGuides && cfg.selectedSignals.includes('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;
              const vMax = scaleRef.current.maxV;
              // ESPVR
              ctx.beginPath();
              ctx.moveTo(xScale(inst.params.LV_V0), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(inst.params.LV_Ees * (vMax - inst.params.LV_V0)));
              ctx.stroke();
              // EDPVR
              ctx.beginPath();
              let firstPt = true;
              for (let v = Math.max(0, inst.params.LV_V0); v <= vMax; v += (vMax/50)) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > scaleRef.current.maxP) break;
                  const px = xScale(v), py = yScale(ped);
                  if(firstPt) { ctx.moveTo(px,py); firstPt=false;} else ctx.lineTo(px,py);
              }
              ctx.stroke();
              ctx.restore();
          }

          const drawLoop = (c: string) => {
              ctx.beginPath();
              ctx.strokeStyle = getColor(inst.color, c, cfg.customColors);
              ctx.lineWidth = 2;
              const getPt = (d: any) => {
                  switch(c) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              };
              if(loopData.length === 0) return;
              const [sV, sP] = getPt(loopData[0]);
              ctx.moveTo(xScale(sV), yScale(sP));
              for(let i=1; i<loopData.length; i++) {
                  const [v, p] = getPt(loopData[i]);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();
              const [eV, eP] = getPt(loopData[loopData.length-1]);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(eV), yScale(eP), 3, 0, 2*Math.PI);
              ctx.fill();
          }
          cfg.selectedSignals.forEach(c => drawLoop(c));
      });
      animationFrameId = requestAnimationFrame(render);
    };
    render();
    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(containerRef.current);
    return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
  }, [instances, config, showGuides]);

  return (
      <div ref={containerRef} className="w-full h-full relative">
         <canvas ref={canvasRef} className="block" />
      </div>
  );
};

// --------------------------------------------------------
// Waveform Panel (With Auto-Scaling)
// --------------------------------------------------------
export const WaveformPanel: React.FC<WaveformProps> = ({ physicsRefs, instances, timeWindow, config }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const scaleRef = useRef({ yMin: 0, yMax: 160 });

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        const margin = { top: 10, right: 10, bottom: 20, left: 40 };

        let animationFrameId: number;
        const render = () => {
            const innerWidth = width - margin.left - margin.right;
            const innerHeight = height - margin.top - margin.bottom;
            const yScale = d3.scaleLinear().range([margin.top + innerHeight, margin.top]);

            ctx.clearRect(0, 0, width, height);

            let localMin = 1000;
            let localMax = -1000;
            let hasData = false;
            let maxT = 0;

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys) return;
                if(phys.t > maxT) maxT = phys.t;

                if (phys.buffer.length < 2) return;
                const startTime = phys.t - timeWindow;
                const visibleData = phys.buffer.filter(p => p.t > startTime);

                if (visibleData.length === 0) return;
                const step = Math.max(1, Math.floor(visibleData.length / 200));

                for (let i = 0; i < visibleData.length; i += step) {
                     const pt = visibleData[i];
                     cfg.selectedSignals.forEach(sig => {
                         let val = 0;
                         switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                         }
                         if (val < localMin) localMin = val;
                         if (val > localMax) localMax = val;
                         hasData = true;
                     });
                }
            });

            if (hasData) {
                const range = localMax - localMin;
                const pad = Math.max(10, range * 0.1);
                const targetMin = Math.max(0, localMin - pad);
                const targetMax = localMax + pad;
                scaleRef.current.yMin = scaleRef.current.yMin * 0.9 + targetMin * 0.1;
                scaleRef.current.yMax = scaleRef.current.yMax * 0.9 + targetMax * 0.1;
            } else {
                scaleRef.current.yMin = scaleRef.current.yMin * 0.95;
                scaleRef.current.yMax = scaleRef.current.yMax * 0.95 + 160 * 0.05;
            }

            yScale.domain([scaleRef.current.yMin, scaleRef.current.yMax]);

            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(margin.left, margin.top);
            ctx.lineTo(margin.left, margin.top + innerHeight);
            ctx.stroke();

            ctx.fillStyle = '#94a3b8';
            ctx.font = '10px sans-serif';
            ctx.textAlign = 'right';
            ctx.textBaseline = 'middle';
            yScale.ticks(5).forEach(t => {
                const y = yScale(t);
                ctx.beginPath();
                ctx.moveTo(margin.left, y);
                ctx.lineTo(margin.left - 5, y);
                ctx.stroke();
                ctx.fillText(t.toString(), margin.left - 8, y);

                ctx.save();
                ctx.strokeStyle = '#334155';
                ctx.globalAlpha = 0.2;
                ctx.beginPath();
                ctx.moveTo(margin.left, y);
                ctx.lineTo(width - margin.right, y);
                ctx.stroke();
                ctx.restore();
            });

            if (maxT === 0) { animationFrameId = requestAnimationFrame(render); return; }

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;

                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 2) return;
                const validData = phys.buffer.filter(p => p.t > phys.t - timeWindow - 100);

                const drawSig = (sig: SignalType) => {
                    ctx.beginPath();
                    ctx.strokeStyle = getColor(inst.color, sig, cfg.customColors);
                    ctx.lineWidth = 2;
                    let first = true; let prevX = -1;

                    ctx.save();
                    ctx.beginPath();
                    ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
                    ctx.clip();
                    ctx.beginPath();

                    for(let i=0; i<validData.length; i+=2) {
                        const pt = validData[i];
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }
                        const xRel = (pt.t % timeWindow) / timeWindow;
                        const x = margin.left + xRel * innerWidth;
                        const y = yScale(val);

                        if(first) { ctx.moveTo(x,y); first=false; }
                        else { 
                            if(x < prevX) { ctx.stroke(); ctx.beginPath(); ctx.moveTo(x,y); }
                            else ctx.lineTo(x,y); 
                        }
                        prevX = x;
                    }
                    ctx.stroke();
                    ctx.restore();
                };
                cfg.selectedSignals.forEach(s => drawSig(s as SignalType));

                if(phys.buffer.length>0) {
                    const pt = phys.buffer[phys.buffer.length-1];
                    const xRel = (pt.t % timeWindow) / timeWindow;
                    const x = margin.left + xRel * innerWidth;

                    const drawHead = (sig: SignalType) => {
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }
                        ctx.beginPath();
                        ctx.fillStyle = getColor(inst.color, sig, cfg.customColors);
                        ctx.arc(x, yScale(val), 4, 0, 2*Math.PI);
                        ctx.fill();
                        ctx.strokeStyle='#fff'; ctx.lineWidth=1; ctx.stroke();
                    };
                    cfg.selectedSignals.forEach(s => drawHead(s as SignalType));
                }
            });

            const xRelCursor = (maxT % timeWindow) / timeWindow;
            const cursorX = margin.left + xRelCursor * innerWidth;
            const eraseWidth = (300 / timeWindow) * innerWidth; 

            ctx.save();
            ctx.beginPath();
            ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
            ctx.clip();
            ctx.clearRect(cursorX, margin.top, eraseWidth, innerHeight);
            if (cursorX + eraseWidth > width) {
                const remainder = (cursorX + eraseWidth) - (margin.left + innerWidth);
                if (remainder > 0) ctx.clearRect(margin.left, margin.top, remainder, innerHeight);
            }
            ctx.restore();

            animationFrameId = requestAnimationFrame(render);
        };
        render();
        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);
        return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
    }, [instances, timeWindow, config]);

    return (
        <div className="flex flex-col h-full w-full relative group">
            <div ref={containerRef} className="flex-1 w-full min-h-0 relative">
                <canvas ref={canvasRef} className="block relative z-10" />
            </div>
            <div className="absolute top-2 right-2 pointer-events-none z-20 opacity-50 text-[10px] text-slate-400">
                Window: {timeWindow/1000}s
            </div>
        </div>
    );
};

// --------------------------------------------------------
// Metrics Panel
// --------------------------------------------------------
export const MetricsPanel: React.FC<ChartPanelProps> = ({ physicsRefs, instances, config }) => {
    // We update metrics every 500ms to avoid UI flickering
    const [metricsData, setMetricsData] = useState<{[key:string]: {[key:string]: string}}>({});

    useEffect(() => {
        const interval = setInterval(() => {
            const nextData: any = {};

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible || cfg.selectedSignals.length === 0) return;

                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 100) return;

                const activeHR = phys.activeParams.HR;
                const cycleMs = 60000 / activeHR;

                // Get data for last cardiac cycle + buffer
                const endTime = phys.t;
                const startTime = endTime - cycleMs;
                const cycleData = phys.buffer.filter(d => d.t >= startTime);

                if (cycleData.length < 10) return;

                const calcMetrics: {[key:string]: string} = {};

                // Helpers
                const getArr = (fn: (d:any)=>number) => cycleData.map(fn);
                const max = (arr: number[]) => Math.max(...arr);
                const min = (arr: number[]) => Math.min(...arr);
                const mean = (arr: number[]) => arr.reduce((a,b)=>a+b,0)/arr.length;

                // 1. AoP (Sys/Dia)
                if (cfg.selectedSignals.includes('ABP')) {
                    const vals = getArr(d => d.aux.AoP);
                    calcMetrics['ABP'] = `${max(vals).toFixed(0)} / ${min(vals).toFixed(0)} mmHg`;
                }
                // 2. PAP (Sys/Dia)
                if (cfg.selectedSignals.includes('PAP')) {
                    const vals = getArr(d => d.aux.PAP);
                    calcMetrics['PAP'] = `${max(vals).toFixed(0)} / ${min(vals).toFixed(0)} mmHg`;
                }
                // 3. CVP (Mean Pra)
                if (cfg.selectedSignals.includes('CVP')) {
                    const vals = getArr(d => d.aux.Pra);
                    calcMetrics['CVP'] = `${mean(vals).toFixed(1)} mmHg`;
                }
                // 4. PCWP (Mean Pla)
                if (cfg.selectedSignals.includes('PCWP')) {
                    const vals = getArr(d => d.aux.Pla);
                    calcMetrics['PCWP'] = `${mean(vals).toFixed(1)} mmHg`;
                }
                // 5. SV (Max - Min LV Volume)
                const lvVols = getArr(d => d.y.Qlv);
                const sv = max(lvVols) - min(lvVols);
                if (cfg.selectedSignals.includes('SV')) {
                    calcMetrics['SV'] = `${sv.toFixed(1)} mL`;
                }
                // 6. CO
                if (cfg.selectedSignals.includes('CO')) {
                    const co = (sv * activeHR) / 1000;
                    calcMetrics['CO'] = `${co.toFixed(2)} L/min`;
                }
                // 7. Ea (Effective Arterial Elastance) approx ESP/SV
                // ESP approx max Plv.
                if (cfg.selectedSignals.includes('Ea_LV')) {
                   const plvVals = getArr(d => d.aux.Plv);
                   const esp = max(plvVals);
                   const ea = sv > 0 ? esp / sv : 0;
                   calcMetrics['Ea_LV'] = `${ea.toFixed(2)} mmHg/mL`;
                }

                nextData[inst.id] = calcMetrics;
            });
            setMetricsData(nextData);

        }, 200);
        return () => clearInterval(interval);
    }, [instances, config]);

    return (
        <div className="w-full h-full p-2 overflow-y-auto custom-scrollbar">
            {instances.map(inst => {
                const cfg = config[inst.id];
                const data = metricsData[inst.id];
                if (!cfg || !cfg.visible || !data) return null;

                return (
                    <div key={inst.id} className="mb-4 bg-slate-900/50 rounded border border-slate-800 p-2">
                         <div className="flex items-center gap-2 mb-2 border-b border-slate-700 pb-1">
                            <span className="w-2 h-2 rounded-full" style={{backgroundColor: inst.color}}></span>
                            <span className="text-xs font-bold text-slate-300">{inst.name}</span>
                         </div>
                         <div className="grid grid-cols-2 gap-2">
                             {cfg.selectedSignals.map(sig => (
                                 data[sig] ? (
                                     <div key={sig} className="flex flex-col bg-slate-950/50 p-1.5 rounded">
                                         <span className="text-[10px] text-slate-500 uppercase font-bold">{sig}</span>
                                         <span className="text-sm font-mono text-slate-200">{data[sig]}</span>
                                     </div>
                                 ) : null
                             ))}
                         </div>
                    </div>
                )
            })}
        </div>
    );
}

// --------------------------------------------------------
// Guyton & Starling Panel
// --------------------------------------------------------
export const GuytonPanel: React.FC<GuytonProps> = ({ physicsRefs, instances, config, type }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        const margin = { top: 20, right: 20, bottom: 30, left: 40 };

        let animationFrameId: number;

        const render = () => {
            const innerWidth = width - margin.left - margin.right;
            const innerHeight = height - margin.top - margin.bottom;

            ctx.clearRect(0, 0, width, height);

            // X-Axis: Preload (Pra for Right/Systemic, Pla for Left/Pulm)
            const xScale = d3.scaleLinear().domain([0, 20]).range([margin.left, margin.left + innerWidth]);
            // Y-Axis: CO (L/min)
            const yScale = d3.scaleLinear().domain([0, 15]).range([margin.top + innerHeight, margin.top]);

            // Draw Grid
            ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;
            ctx.beginPath();
            xScale.ticks(6).forEach(t => { ctx.moveTo(xScale(t), margin.top + innerHeight); ctx.lineTo(xScale(t), margin.top); });
            yScale.ticks(6).forEach(t => { ctx.moveTo(margin.left, yScale(t)); ctx.lineTo(margin.left + innerWidth, yScale(t)); });
            ctx.stroke();

            // Labels
            ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif';
            ctx.textAlign = 'center';
            xScale.ticks(6).forEach(t => ctx.fillText(t.toString(), xScale(t), margin.top + innerHeight + 15));
            ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
            yScale.ticks(6).forEach(t => ctx.fillText(t.toString(), margin.left - 5, yScale(t)));

            // Axis Titles
            ctx.textAlign = 'center';
            ctx.fillText(type === 'GUYTON_RIGHT' ? "RA Pressure (mmHg)" : "LA Pressure (mmHg)", margin.left + innerWidth / 2, height - 5);
            ctx.save();
            ctx.translate(15, margin.top + innerHeight / 2);
            ctx.rotate(-Math.PI / 2);
            ctx.fillText("CO (L/min)", 0, 0);
            ctx.restore();

            // Plot Curves per Instance
            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys) return;
                const p = phys.activeParams;
                const y = phys.y;

                // 1. Calculate Guyton Parameters based on type
                // Formula: CO = (Vol - P_pre * C_sum) / W_sum
                let vol_sys = 0, C_sum = 0, W_sum = 0;
                let P_pre_current = 0;

                if (type === 'GUYTON_RIGHT') {
                    // Systemic Circuit & Right Heart Analysis
                    // Vol = Qas_prox + Qda + Qas + Qvs
                    vol_sys = y[8] + y[9] + y[1] + y[0];
                    // C_sum = Cas_prox + Cda + Cas + Cvs
                    C_sum = p.Cas_prox + p.Cda + p.Cas + p.Cvs;
                    // W_sum = Cda*Rda + Cas*(Rda+Ras) + Cvs*(Rda+Ras+Rcs)
                    // Note: Rda is between as_prox and da. Ras is between da and as. Rcs between as and vs.
                    W_sum = p.Cda*p.Rda + p.Cas*(p.Rda + p.Ras) + p.Cvs*(p.Rda + p.Ras + p.Rcs);

                    P_pre_current = phys.buffer.length > 0 ? phys.buffer[phys.buffer.length-1].aux.Pra : 0;

                } else {
                    // Pulmonary Circuit & Left Heart Analysis
                    // Vol = Qap_prox + Qap + Qvp
                    vol_sys = y[10] + y[2] + y[3];
                    // C_sum = Cap_prox + Cap + Cvp
                    C_sum = p.Cap_prox + p.Cap + p.Cvp;
                    // W_sum = Cap*Rcp + Cvp*(Rcp+Rap)
                    // Note: Rcp is between ap_prox and ap. Rap between ap and vp.
                    W_sum = p.Cap*p.Rcp + p.Cvp*(p.Rcp + p.Rap);

                    P_pre_current = phys.buffer.length > 0 ? phys.buffer[phys.buffer.length-1].aux.Pla : 0;
                }

                // Draw Guyton Curve (Venous Return)
                ctx.beginPath();
                ctx.strokeStyle = inst.color;
                ctx.setLineDash([5, 5]);
                ctx.lineWidth = 1.5;

                // Plot from P=0 to P=MeanCirculatoryFill
                // VR = 0 when P_pre = Vol / C_sum (Mean Systemic Filling Pressure)
                const msfp = vol_sys / C_sum;

                // We plot P_pre on X, CO on Y
                // CO = (Vol - P * C) / W
                // Points: (0, Vol/W) -> (MSFP, 0)
                const toLMin = 60.0; // Conversion from mL/ms to L/min (x1000/x1000/60? No. mL/ms * 60000 ms/min * 1/1000 L/mL = 60)

                const pStart = 0;
                const coStart = (vol_sys - pStart * C_sum) / W_sum * toLMin;
                const pEnd = msfp;

                // Clamping for display
                const x1 = xScale(pStart);
                const y1 = yScale(coStart);
                const x2 = xScale(pEnd);
                const y2 = yScale(0);

                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.stroke();


                // 2. Draw Starling Curve (Cardiac Function)
                // CO = HR * SV
                // SV approx formula: SV = Ees/(Ees+Ea) * 1/alpha * ln((P_pre + beta)/beta) - V_offset

                let Ees = 0, alpha = 0, beta = 0, V0 = 0, Ea = 0;
                let R_total = 0;

                if (type === 'GUYTON_RIGHT') {
                    // RV Output vs Pra
                    Ees = p.RV_Ees; alpha = p.RV_alpha; beta = p.RV_beta; V0 = p.RV_V0;
                    // Ea approx for RV = Resistance of Pulm / CycleTime
                    // R_pulm = Rap_prox + Rcp + Rap + Rvp
                    R_total = p.Rap_prox + p.Rcp + p.Rap + p.Rvp;
                } else {
                    // LV Output vs Pla
                    Ees = p.LV_Ees; alpha = p.LV_alpha; beta = p.LV_beta; V0 = p.LV_V0;
                    // R_sys = Ras_prox + Rda + Ras + Rcs + Rvs
                    R_total = p.Ras_prox + p.Rda + p.Ras + p.Rcs + p.Rvs;
                }

                const T = 60000 / p.HR; // ms
                Ea = R_total / T;

                ctx.beginPath();
                ctx.strokeStyle = inst.color;
                ctx.setLineDash([]);
                ctx.lineWidth = 2;

                let first = true;
                for (let px = 0; px <= 25; px += 0.5) {
                    const term = (Ees / (Ees + Ea)) * (1.0 / alpha) * Math.log((px + beta) / beta);
                    const sv_est = Math.max(0, term); // Assuming Voffset is roughly handled or 0 for now based on prompt
                    const co_est = (sv_est * p.HR) / 1000.0; // L/min

                    const cx = xScale(px);
                    const cy = yScale(co_est);

                    if (cy < margin.top + innerHeight && cy > margin.top) {
                        if (first) { ctx.moveTo(cx, cy); first = false; }
                        else ctx.lineTo(cx, cy);
                    }
                }
                ctx.stroke();

                // 3. Operating Point
                if (phys.buffer.length > 100) {
                     const lastCycle = phys.buffer.slice(-Math.floor(T/2.0)); // sample last bit
                     const avgP = lastCycle.reduce((a, b) => a + (type === 'GUYTON_RIGHT' ? b.aux.Pra : b.aux.Pla), 0) / lastCycle.length;

                     // Approximate actual CO from SV real
                     const vols = lastCycle.map(z => type === 'GUYTON_RIGHT' ? z.y.Qrv : z.y.Qlv);
                     const sv_real = Math.max(...vols) - Math.min(...vols);
                     const co_real = (sv_real * p.HR) / 1000.0;

                     ctx.beginPath();
                     ctx.fillStyle = inst.color;
                     ctx.arc(xScale(avgP), yScale(co_real), 5, 0, 2*Math.PI);
                     ctx.fill();
                     ctx.stroke();
                }

            });

            animationFrameId = requestAnimationFrame(render);
        };
        render();
        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);
        return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
    }, [instances, config, type]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            <canvas ref={canvasRef} className="block" />
        </div>
    );
};

import React, { useState } from 'react';
import { SimulationParams, SimInstance, PanelType } from '../types';

interface ControlsProps {
  instances: SimInstance[];
  activeInstanceId: string;
  setActiveInstanceId: (id: string) => void;
  updateInstanceParams: (id: string, params: Partial<SimulationParams>) => void;
  updateInstanceVolume: (id: string, vol: number) => void;
  updateInstanceColor: (id: string, color: string) => void;
  addInstance: () => void;
  removeInstance: (id: string) => void;

  timeScale: number;
  setTimeScale: (v: number) => void;
  isPlaying: boolean;
  togglePlay: () => void;

  addPanel: (type: PanelType) => void;
}

const Slider = ({ label, value, min, max, step, onChange, unit }: { label: string, value: number, min: number, max: number, step: number, onChange: (val: number) => void, unit?: string }) => (
  <div className="mb-3">
    <div className="flex justify-between text-xs text-slate-400 mb-1">
      <span>{label}</span>
      <span>{value.toFixed(2)} {unit}</span>
    </div>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={(e) => onChange(parseFloat(e.target.value))}
      className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500 hover:accent-blue-400"
    />
  </div>
);

const GroupHeader = ({ title, isOpen, toggle }: { title: string, isOpen: boolean, toggle: () => void }) => (
    <div 
        onClick={toggle}
        className="flex justify-between items-center cursor-pointer bg-slate-800 p-2 rounded mt-2 hover:bg-slate-700 transition-colors"
    >
        <span className="text-xs font-bold text-slate-200 uppercase">{title}</span>
        <span className="text-xs text-slate-400">{isOpen ? '▼' : '▶'}</span>
    </div>
);

export const Controls: React.FC<ControlsProps> = ({ 
    instances, activeInstanceId, setActiveInstanceId, updateInstanceParams, updateInstanceVolume, updateInstanceColor, addInstance, removeInstance,
    timeScale, setTimeScale, isPlaying, togglePlay,
    addPanel
}) => {

  const activeInstance = instances.find(i => i.id === activeInstanceId) || instances[0];
  const params = activeInstance?.params;

  // Tab State
  const [openGroups, setOpenGroups] = useState<{ [key: string]: boolean }>({
      general: true,
      lv: true,
      sys: false,
      rv: false,
      pulm: false,
      la: false,
      ra: false
  });

  const toggleGroup = (key: string) => setOpenGroups(prev => ({ ...prev, [key]: !prev[key] }));

  const update = (key: keyof SimulationParams, val: number) => {
      if (activeInstance) {
        updateInstanceParams(activeInstance.id, { [key]: val });
      }
  };

  // Helper for Macro Sliders
  // Systemic R components: Ras, Rcs, Rvs, Ras_prox, Rda
  const getSystemicR = () => params.Ras + params.Rcs + params.Rvs + params.Ras_prox + params.Rda;
  const setSystemicR = (newTotal: number) => {
      const currentTotal = getSystemicR();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Ras: params.Ras * ratio,
          Rcs: params.Rcs * ratio,
          Rvs: params.Rvs * ratio,
          Ras_prox: params.Ras_prox * ratio,
          Rda: params.Rda * ratio
      });
  };

  // Systemic C components: Cas, Cvs, Cas_prox, Cda
  const getSystemicC = () => params.Cas + params.Cvs + params.Cas_prox + params.Cda;
  const setSystemicC = (newTotal: number) => {
      const currentTotal = getSystemicC();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Cas: params.Cas * ratio,
          Cvs: params.Cvs * ratio,
          Cas_prox: params.Cas_prox * ratio,
          Cda: params.Cda * ratio
      });
  };

  // Pulmonary R: Rap, Rvp, Rap_prox, Rcp
  const getPulmR = () => params.Rap + params.Rvp + params.Rap_prox + params.Rcp;
  const setPulmR = (newTotal: number) => {
      const currentTotal = getPulmR();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Rap: params.Rap * ratio,
          Rvp: params.Rvp * ratio,
          Rap_prox: params.Rap_prox * ratio,
          Rcp: params.Rcp * ratio
      });
  };

  // Pulmonary C: Cap, Cvp, Cap_prox
  const getPulmC = () => params.Cap + params.Cvp + params.Cap_prox;
  const setPulmC = (newTotal: number) => {
      const currentTotal = getPulmC();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Cap: params.Cap * ratio,
          Cvp: params.Cvp * ratio,
          Cap_prox: params.Cap_prox * ratio
      });
  };


  return (
    <div className="space-y-6 pb-20">

      {/* Simulation Control */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
        <h3 className="text-sm font-bold text-slate-100 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Global Physics</h3>

        <div className="mb-4 flex items-center gap-2">
            <button 
                onClick={togglePlay}
                className={`flex-1 py-2 rounded font-bold text-sm transition-colors ${isPlaying ? 'bg-amber-600 hover:bg-amber-500 text-white' : 'bg-emerald-600 hover:bg-emerald-500 text-white'}`}
            >
                {isPlaying ? 'PAUSE' : 'PLAY'}
            </button>
        </div>

        <div className="mb-4">
             <div className="flex justify-between text-xs text-slate-400 mb-1">
                <span>Sim Speed</span>
                <span>{timeScale.toFixed(1)}x</span>
            </div>
            <input
                type="range"
                min={0.1}
                max={2.0}
                step={0.1}
                value={timeScale}
                onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
            />
        </div>
      </div>

      {/* Dashboard Layout */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
         <h3 className="text-sm font-bold text-slate-100 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Layout</h3>
         <div className="grid grid-cols-2 gap-2">
            <button onClick={() => addPanel('PVLOOP')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + PV Loop
            </button>
            <button onClick={() => addPanel('WAVEFORM')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + Waveform
            </button>
            <button onClick={() => addPanel('GUYTON_RIGHT')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + Guyton (Right)
            </button>
            <button onClick={() => addPanel('GUYTON_LEFT')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + Guyton (Left)
            </button>
            <button onClick={() => addPanel('METRICS')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center col-span-2">
               + Hemodynamic Metrics
            </button>
         </div>
      </div>

      {/* Instances Management */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
          <div className="flex justify-between items-center mb-2 border-b border-slate-800 pb-2">
            <h3 className="text-sm font-bold text-white uppercase tracking-wider">Models</h3>
            <button onClick={addInstance} className="text-xs bg-indigo-600 hover:bg-indigo-500 px-2 py-1 rounded text-white">+ Add</button>
          </div>
          <div className="space-y-2">
              {instances.map(inst => (
                  <div 
                    key={inst.id} 
                    className={`flex items-center justify-between p-2 rounded cursor-pointer border ${activeInstanceId === inst.id ? 'bg-slate-800 border-indigo-500/50' : 'bg-slate-950 border-slate-800 hover:border-slate-700'}`}
                    onClick={() => setActiveInstanceId(inst.id)}
                  >
                      <div className="flex items-center gap-2">
                          <input 
                            type="color" 
                            value={inst.color}
                            onChange={(e) => updateInstanceColor(inst.id, e.target.value)}
                            className="w-4 h-4 rounded overflow-hidden border-none p-0 cursor-pointer"
                          />
                          <span className="text-xs font-semibold text-slate-200">{inst.name}</span>
                      </div>
                      <div className="flex items-center gap-2">
                          {instances.length > 1 && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); removeInstance(inst.id); }}
                                className="text-slate-500 hover:text-red-400 px-1"
                            >
                                ✕
                            </button>
                          )}
                      </div>
                  </div>
              ))}
          </div>
      </div>

      {/* Params for Active Instance */}
      {params && (
          <div className="p-4 bg-slate-900 rounded-xl border border-slate-800 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-1 h-full" style={{ backgroundColor: activeInstance.color }}></div>
                <h3 className="text-sm font-bold text-white uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">
                    {activeInstance.name} Config
                </h3>

                {/* General Group */}
                <GroupHeader title="General" isOpen={openGroups.general} toggle={() => toggleGroup('general')} />
                {openGroups.general && (
                    <div className="mt-3 pl-1 border-l-2 border-slate-700">
                        <Slider label="Heart Rate" value={params.HR} min={30} max={200} step={1} onChange={(v) => update('HR', v)} unit="bpm" />
                        <Slider label="Total Volume" value={activeInstance.targetVolume} min={1000} max={8000} step={50} onChange={(v) => updateInstanceVolume(activeInstance.id, v)} unit="mL" />
                    </div>
                )}

                {/* Left Ventricle */}
                <GroupHeader title="Left Ventricle" isOpen={openGroups.lv} toggle={() => toggleGroup('lv')} />
                {openGroups.lv && (
                    <div className="mt-3 pl-1 border-l-2 border-purple-500/30">
                        <Slider label="Ees (Contractility)" value={params.LV_Ees} min={0.5} max={10.0} step={0.1} onChange={(v) => update('LV_Ees', v)} unit="mmHg/mL" />
                        <Slider label="V0 (Unstressed Vol)" value={params.LV_V0} min={-50} max={100} step={5} onChange={(v) => update('LV_V0', v)} unit="mL" />
                        <Slider label="Alpha (Stiffness)" value={params.LV_alpha} min={0.01} max={0.1} step={0.001} onChange={(v) => update('LV_alpha', v)} unit="/mL" />
                        <Slider label="Beta (EDP Scale)" value={params.LV_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('LV_beta', v)} unit="mmHg" />
                        <Slider label="Tau (Relaxation)" value={params.LV_tau} min={10} max={100} step={1} onChange={(v) => update('LV_tau', v)} unit="ms" />
                    </div>
                )}

                {/* Systemic */}
                <GroupHeader title="Systemic Circulation" isOpen={openGroups.sys} toggle={() => toggleGroup('sys')} />
                {openGroups.sys && (
                    <div className="mt-3 pl-1 border-l-2 border-blue-500/30">
                        <Slider label="Total Resistance" value={getSystemicR()} min={500} max={4000} step={50} onChange={setSystemicR} unit="R" />
                        <Slider label="Total Compliance" value={getSystemicC()} min={0.5} max={10} step={0.1} onChange={setSystemicC} unit="mL/mmHg" />
                    </div>
                )}

                 {/* Right Ventricle */}
                <GroupHeader title="Right Ventricle" isOpen={openGroups.rv} toggle={() => toggleGroup('rv')} />
                {openGroups.rv && (
                    <div className="mt-3 pl-1 border-l-2 border-teal-500/30">
                        <Slider label="Ees (Contractility)" value={params.RV_Ees} min={0.1} max={5.0} step={0.1} onChange={(v) => update('RV_Ees', v)} unit="mmHg/mL" />
                        <Slider label="V0 (Unstressed Vol)" value={params.RV_V0} min={-50} max={100} step={5} onChange={(v) => update('RV_V0', v)} unit="mL" />
                        <Slider label="Alpha (Stiffness)" value={params.RV_alpha} min={0.01} max={0.1} step={0.001} onChange={(v) => update('RV_alpha', v)} unit="/mL" />
                        <Slider label="Beta (EDP Scale)" value={params.RV_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('RV_beta', v)} unit="mmHg" />
                        <Slider label="Tau (Relaxation)" value={params.RV_tau} min={10} max={100} step={1} onChange={(v) => update('RV_tau', v)} unit="ms" />
                    </div>
                )}

                {/* Pulmonary */}
                <GroupHeader title="Pulmonary Circulation" isOpen={openGroups.pulm} toggle={() => toggleGroup('pulm')} />
                {openGroups.pulm && (
                    <div className="mt-3 pl-1 border-l-2 border-cyan-500/30">
                        <Slider label="Total Resistance" value={getPulmR()} min={50} max={1000} step={10} onChange={setPulmR} unit="R" />
                        <Slider label="Total Compliance" value={getPulmC()} min={1} max={20} step={0.5} onChange={setPulmC} unit="mL/mmHg" />
                    </div>
                )}

                 {/* Left Atrium */}
                <GroupHeader title="Left Atrium" isOpen={openGroups.la} toggle={() => toggleGroup('la')} />
                {openGroups.la && (
                    <div className="mt-3 pl-1 border-l-2 border-slate-700">
                        <Slider label="Ees" value={params.LA_Ees} min={0.1} max={2.0} step={0.05} onChange={(v) => update('LA_Ees', v)} unit="mmHg/mL" />
                        <Slider label="Beta" value={params.LA_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('LA_beta', v)} unit="mmHg" />
                    </div>
                )}

                 {/* Right Atrium */}
                <GroupHeader title="Right Atrium" isOpen={openGroups.ra} toggle={() => toggleGroup('ra')} />
                {openGroups.ra && (
                    <div className="mt-3 pl-1 border-l-2 border-slate-700">
                         <Slider label="Ees" value={params.RA_Ees} min={0.1} max={2.0} step={0.05} onChange={(v) => update('RA_Ees', v)} unit="mmHg/mL" />
                         <Slider label="Beta" value={params.RA_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('RA_beta', v)} unit="mmHg" />
                    </div>
                )}

          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, SimInstance, PhysicsRefState, PanelDef, PanelType, PanelInstanceConfig, ChamberId, SignalType, MetricType } from './types';
import { stepRK4, getTotalVolume } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopPanel, WaveformPanel, MetricsPanel, GuytonPanel } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

const ALL_CHAMBERS: ChamberId[] = ['LV', 'LA', 'RV', 'RA'];
const ALL_SIGNALS: SignalType[] = ['Plv', 'AoP', 'Pla', 'Prv', 'PAP', 'Pra'];
const ALL_METRICS: MetricType[] = ['ABP', 'CVP', 'PAP', 'PCWP', 'SV', 'CO', 'Ea_LV'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { 
          id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], 
          params: { ...DEFAULT_PARAMS }, 
          targetVolume: getTotalVolume(INITIAL_STATE_VECTOR), 
          isVisible: true 
      }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Panel Management State ---
  const [panels, setPanels] = useState<PanelDef[]>([
      { 
          id: 'p1', type: 'PVLOOP', title: 'LV PV Loop', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['LV'] } },
          showGuides: true, isSettingsOpen: false
      },
      { 
          id: 'p2', type: 'WAVEFORM', title: 'Monitor', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['Plv', 'AoP'] } },
          timeWindow: 10000,
          isSettingsOpen: false
      }
  ]);

  // --- Refs for Physics Loop ---
  const timeScaleRef = useRef(timeScale);
  const isPlayingRef = useRef(isPlaying);
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());
  const instanceRefs = useRef<SimInstance[]>(instances);

  useEffect(() => { timeScaleRef.current = timeScale; }, [timeScale]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { instanceRefs.current = instances; }, [instances]);

  // Init physics refs
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              let syncTime = INITIAL_TIME;
              if (physicsRefs.current.size > 0) {
                  for (const p of physicsRefs.current.values()) {
                      if (p.t > syncTime) syncTime = p.t;
                  }
              }
              physicsRefs.current.set(inst.id, {
                  t: syncTime, 
                  y: [...INITIAL_STATE_VECTOR], 
                  buffer: [], 
                  lastRenderX: 0,
                  activeParams: { ...inst.params } 
              });

              setPanels(prev => prev.map(p => {
                 if (p.config[inst.id]) return p;
                 const newConfig = { ...p.config };

                 // Default config for new instance based on panel type
                 let defaultSigs: string[] = [];
                 if (p.type === 'PVLOOP') defaultSigs = ['LV'];
                 else if (p.type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
                 else if (p.type === 'METRICS') defaultSigs = ['ABP', 'CO'];
                 else if (p.type === 'GUYTON_RIGHT' || p.type === 'GUYTON_LEFT') defaultSigs = ['default'];

                 newConfig[inst.id] = { 
                     visible: true, 
                     selectedSignals: defaultSigs
                 };
                 return { ...p, config: newConfig };
              }));
          }
      });
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) physicsRefs.current.delete(id);
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; 
    const baseStepsPerFrame = 8; 

    const loop = () => {
      if (!isPlayingRef.current) {
          animationFrameId = requestAnimationFrame(loop);
          return;
      }

      const currentScale = timeScaleRef.current;
      const stepsToRun = Math.round(baseStepsPerFrame * currentScale);

      for (let i = 0; i < stepsToRun; i++) {
         instanceRefs.current.forEach(uiInst => {
             const phys = physicsRefs.current.get(uiInst.id);
             if (!phys) return;

             const T = 60000.0 / phys.activeParams.HR; 
             const prevPhase = (phys.t - dt) % T;
             const currPhase = phys.t % T;

             const isEndDiastole = currPhase < prevPhase;
             const tMax = phys.activeParams.LV_Tmax;
             const isEndSystole = prevPhase < tMax && currPhase >= tMax;

             if (isEndDiastole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.HR = p.HR;

                 ap.Ras = p.Ras; ap.Rcs = p.Rcs; ap.Rvs = p.Rvs; ap.Ras_prox = p.Ras_prox; ap.Rda = p.Rda;
                 ap.Rap = p.Rap; ap.Rvp = p.Rvp; ap.Rap_prox = p.Rap_prox; ap.Rcp = p.Rcp;
                 ap.Rmv = p.Rmv; ap.Rtv = p.Rtv;

                 ap.Cas = p.Cas; ap.Cvs = p.Cvs; ap.Cas_prox = p.Cas_prox; ap.Cda = p.Cda;
                 ap.Cap = p.Cap; ap.Cvp = p.Cvp; ap.Cap_prox = p.Cap_prox;

                 ap.LV_Ees = p.LV_Ees; ap.LV_V0 = p.LV_V0;
                 ap.RV_Ees = p.RV_Ees; ap.RV_V0 = p.RV_V0;
                 ap.LA_Ees = p.LA_Ees; ap.LA_V0 = p.LA_V0;
                 ap.RA_Ees = p.RA_Ees; ap.RA_V0 = p.RA_V0;

                 const currentTotal = getTotalVolume(phys.y);
                 const targetTotal = uiInst.targetVolume;
                 const diff = targetTotal - currentTotal;
                 const maxDelta = 500; 
                 const delta = Math.max(-maxDelta, Math.min(maxDelta, diff));

                 if (Math.abs(delta) > 1.0) {
                     phys.y[0] += delta;
                 }
             }

             if (isEndSystole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.LV_alpha = p.LV_alpha; ap.LV_beta = p.LV_beta; ap.LV_tau = p.LV_tau; ap.LV_Tmax = p.LV_Tmax;
                 ap.RV_alpha = p.RV_alpha; ap.RV_beta = p.RV_beta; ap.RV_tau = p.RV_tau; ap.RV_Tmax = p.RV_Tmax;
                 ap.LA_alpha = p.LA_alpha; ap.LA_beta = p.LA_beta; ap.LA_tau = p.LA_tau;
                 ap.RA_alpha = p.RA_alpha; ap.RA_beta = p.RA_beta; ap.RA_tau = p.RA_tau;
             }

             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, phys.activeParams);
             phys.t = tNext;
             phys.y = yNext;

             const bufferRequiredMs = 21000;
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };
            phys.buffer.push(output);
            const cutoffTime = tNext - bufferRequiredMs;
            if (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }
      animationFrameId = requestAnimationFrame(loop);
    };
    animationFrameId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const updateInstanceVolume = (id: string, vol: number) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, targetVolume: vol } : inst
      ));
  }

  const updateInstanceColor = (id: string, color: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, color: color } : inst
    ));
  }
  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];
      setInstances(prev => [...prev, {
          id: newId, name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color, 
          params: { ...DEFAULT_PARAMS }, 
          targetVolume: getTotalVolume(INITIAL_STATE_VECTOR),
          isVisible: true
      }]);
      setActiveInstanceId(newId);
  };
  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) setActiveInstanceId(instances[0]?.id || '');
  };

  // --- Panel Handlers ---
  const addPanel = (type: PanelType) => {
      const newConfig: PanelInstanceConfig = {};
      instances.forEach(i => {
          let defaultSigs: string[] = [];
          if (type === 'PVLOOP') defaultSigs = ['LV'];
          else if (type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
          else if (type === 'METRICS') defaultSigs = ['ABP', 'CO'];
          else if (type === 'GUYTON_RIGHT' || type === 'GUYTON_LEFT') defaultSigs = ['Default'];

          newConfig[i.id] = {
              visible: true,
              selectedSignals: defaultSigs
          };
      });

      let title = 'Panel';
      if (type === 'PVLOOP') title = 'PV Loop';
      else if (type === 'WAVEFORM') title = 'Waveforms';
      else if (type === 'METRICS') title = 'Metrics';
      else if (type === 'GUYTON_RIGHT') title = 'Guyton (Systemic/RV)';
      else if (type === 'GUYTON_LEFT') title = 'Guyton (Pulmonary/LV)';

      const newPanel: PanelDef = {
          id: Date.now().toString(),
          type,
          title,
          w: type === 'METRICS' ? 4 : 6, 
          h: type === 'METRICS' ? 6 : 8,
          config: newConfig,
          showGuides: type === 'PVLOOP',
          timeWindow: type === 'WAVEFORM' ? 10000 : undefined,
          isSettingsOpen: false
      };
      setPanels(prev => [...prev, newPanel]);
  };

  const removePanel = (id: string) => {
      setPanels(prev => prev.filter(p => p.id !== id));
  };

  const resizeState = useRef<{ panelId: string, startX: number, startY: number, startW: number, startH: number } | null>(null);

  const startResize = (e: React.MouseEvent, panel: PanelDef) => {
      e.stopPropagation();
      e.preventDefault();
      resizeState.current = {
          panelId: panel.id,
          startX: e.clientX,
          startY: e.clientY,
          startW: panel.w,
          startH: panel.h
      };
      document.addEventListener('mousemove', onResizeMove);
      document.addEventListener('mouseup', onResizeEnd);
  };

  const onResizeMove = (e: MouseEvent) => {
      if (!resizeState.current) return;
      const { panelId, startX, startY, startW, startH } = resizeState.current;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      const wDelta = Math.round(dx / 50);
      const hDelta = Math.round(dy / 50);
      const newW = Math.max(2, Math.min(12, startW + wDelta)); 
      const newH = Math.max(4, Math.min(20, startH + hDelta)); 

      setPanels(prev => prev.map(p => 
          p.id === panelId ? { ...p, w: newW, h: newH } : p
      ));
  };

  const onResizeEnd = () => {
      resizeState.current = null;
      document.removeEventListener('mousemove', onResizeMove);
      document.removeEventListener('mouseup', onResizeEnd);
  };


  // --- Config Logic ---
  const toggleSettings = (panelId: string) => {
      setPanels(prev => prev.map(p => 
        p.id === panelId ? { ...p, isSettingsOpen: !p.isSettingsOpen } : { ...p, isSettingsOpen: false }
      ));
  };

  const toggleInstanceVisibility = (panelId: string, instId: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, visible: !prevCfg.visible }
              }
          };
      }));
  };

  const updateInstanceSignals = (panelId: string, instId: string, signal: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          const currentSigs = new Set(prevCfg.selectedSignals);
          if (currentSigs.has(signal)) currentSigs.delete(signal); else currentSigs.add(signal);

          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, selectedSignals: Array.from(currentSigs) }
              }
          };
      }));
  };

  const updateCustomColor = (panelId: string, instId: string, signal: string, color: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { 
                      ...prevCfg, 
                      customColors: { ...prevCfg.customColors, [signal]: color } 
                  }
              }
          };
      }));
  }

  const toggleGuides = (panelId: string) => {
     setPanels(prev => prev.map(p => p.id === panelId ? { ...p, showGuides: !p.showGuides } : p));
  }

  const updateTimeWindow = (panelId: string, val: number) => {
      setPanels(prev => prev.map(p => p.id === panelId ? { ...p, timeWindow: val } : p));
  }

  // --- Drag & Drop ---
  const dragItemRef = useRef<number | null>(null);
  const dragOverItemRef = useRef<number | null>(null);

  const onDragStart = (e: React.DragEvent, index: number) => {
    dragItemRef.current = index;
    e.dataTransfer.effectAllowed = "move";
  };
  const onDragEnter = (e: React.DragEvent, index: number) => {
    dragOverItemRef.current = index;
  };
  const onDragEnd = () => {
    const srcIdx = dragItemRef.current;
    const dstIdx = dragOverItemRef.current;
    if (srcIdx !== null && dstIdx !== null && srcIdx !== dstIdx) {
       setPanels(prev => {
           const next = [...prev];
           const [removed] = next.splice(srcIdx, 1);
           next.splice(dstIdx, 0, removed);
           return next;
       });
    }
    dragItemRef.current = null;
    dragOverItemRef.current = null;
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      <aside className="w-80 h-full bg-slate-900 border-r border-slate-800 overflow-y-auto flex-shrink-0 z-20 shadow-xl">
        <div className="p-5">
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
            HemoSim 0D
          </h1>
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            updateInstanceVolume={updateInstanceVolume}
            updateInstanceColor={updateInstanceColor}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}

            addPanel={addPanel}
          />
        </div>
      </aside>

      <main className="flex-1 h-full overflow-y-auto overflow-x-hidden bg-slate-950 p-2">
          {/* 12 Column Grid for Fine control */}
          <div className="grid grid-cols-12 gap-2 auto-rows-[50px] grid-flow-dense pb-20">
              {panels.map((panel, index) => {
                  return (
                  <div 
                    key={panel.id} 
                    draggable
                    onDragStart={(e) => onDragStart(e, index)}
                    onDragEnter={(e) => onDragEnter(e, index)}
                    onDragEnd={onDragEnd}
                    onDragOver={(e) => e.preventDefault()}
                    style={{ gridColumn: `span ${panel.w}`, gridRow: `span ${panel.h}` }}
                    className="relative bg-slate-900/50 rounded-lg border border-slate-800 shadow-inner flex flex-col overflow-visible group hover:border-slate-600 transition-colors"
                  >
                      {/* Panel Header */}
                      <div className="absolute top-2 left-2 z-30 flex gap-2 items-center pointer-events-auto">
                           <div className="bg-slate-950/90 px-2 py-1 rounded border border-slate-700 backdrop-blur-sm shadow-sm flex items-center gap-2 cursor-move">
                                <span className="text-xs font-bold text-slate-300 select-none">⋮⋮ {panel.title}</span>
                                <div className="h-3 w-[1px] bg-slate-700 mx-1"></div>

                                {/* Settings Toggle (Click-based) */}
                                <div className="relative">
                                    <button 
                                        onClick={() => toggleSettings(panel.id)}
                                        className={`text-[10px] px-1 flex items-center gap-1 rounded hover:bg-slate-800 ${panel.isSettingsOpen ? 'text-blue-400 bg-slate-800' : 'text-slate-400'}`}
                                    >
                                        <span className="w-3 h-3 border border-current rounded-sm flex items-center justify-center">
                                            <span className="text-[8px]">⚙</span>
                                        </span>
                                    </button>

                                    {/* Dropdown Content */}
                                    {panel.isSettingsOpen && (
                                        <div className="absolute top-full left-0 mt-2 w-56 bg-slate-900 border border-slate-700 rounded shadow-2xl p-3 z-50">
                                            <div className="flex justify-between items-center mb-2 pb-2 border-b border-slate-800">
                                                <span className="text-[10px] font-bold text-slate-500 uppercase">Configuration</span>
                                                <button onClick={() => toggleSettings(panel.id)} className="text-xs text-slate-400 hover:text-white">✕</button>
                                            </div>

                                            {/* Panel Specific Settings */}
                                            {panel.type === 'PVLOOP' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800 flex items-center gap-2">
                                                    <input type="checkbox" checked={panel.showGuides} onChange={() => toggleGuides(panel.id)} />
                                                    <span className="text-xs text-slate-300">Show Guides</span>
                                                </div>
                                            )}
                                            {panel.type === 'WAVEFORM' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800">
                                                    <div className="flex justify-between text-[10px] text-slate-400 mb-1">
                                                        <span>Window</span>
                                                        <span>{(panel.timeWindow || 10000) / 1000}s</span>
                                                    </div>
                                                    <input 
                                                        type="range" min={2000} max={20000} step={1000} 
                                                        value={panel.timeWindow || 10000}
                                                        onChange={(e) => updateTimeWindow(panel.id, parseFloat(e.target.value))}
                                                        className="w-full h-1 bg-slate-700 rounded appearance-none cursor-pointer accent-blue-500"
                                                    />
                                                </div>
                                            )}

                                            <div className="max-h-64 overflow-y-auto space-y-3 custom-scrollbar">
                                                {instances.map(inst => (
                                                    <div key={inst.id}>
                                                        <div className="flex items-center gap-2 mb-1">
                                                            <input 
                                                                type="checkbox" 
                                                                checked={panel.config[inst.id]?.visible || false}
                                                                onChange={() => toggleInstanceVisibility(panel.id, inst.id)}
                                                            />
                                                            <span className="w-2 h-2 rounded-full" style={{backgroundColor: inst.color}}></span>
                                                            <span className="text-xs font-bold text-slate-300 truncate flex-1">{inst.name}</span>
                                                        </div>
                                                        {/* Sub Signals & Colors */}
                                                        {panel.config[inst.id]?.visible && (panel.type !== 'GUYTON_RIGHT' && panel.type !== 'GUYTON_LEFT') && (
                                                            <div className="pl-5 grid grid-cols-1 gap-1">
                                                                {((panel.type === 'PVLOOP' ? ALL_CHAMBERS : (panel.type === 'WAVEFORM' ? ALL_SIGNALS : ALL_METRICS))).map(sig => {
                                                                    const isSelected = panel.config[inst.id].selectedSignals.includes(sig);
                                                                    const customColor = panel.config[inst.id].customColors?.[sig];

                                                                    return (
                                                                    <div key={sig} className="flex items-center justify-between text-[10px] bg-slate-950/50 rounded px-1 py-0.5">
                                                                        <button 
                                                                            onClick={() => updateInstanceSignals(panel.id, inst.id, sig)}
                                                                            className={`flex-1 text-left ${isSelected ? 'text-slate-200' : 'text-slate-600'}`}
                                                                        >
                                                                            {sig}
                                                                        </button>
                                                                        {isSelected && panel.type !== 'METRICS' && (
                                                                            <input 
                                                                                type="color" 
                                                                                className="w-3 h-3 border-none p-0 bg-transparent cursor-pointer"
                                                                                value={customColor || inst.color} 
                                                                                onChange={(e) => updateCustomColor(panel.id, inst.id, sig, e.target.value)}
                                                                            />
                                                                        )}
                                                                    </div>
                                                                )})}
                                                            </div>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <button onClick={() => removePanel(panel.id)} className="text-slate-500 hover:text-red-400 ml-1">✕</button>
                           </div>
                      </div>

                      {/* Content */}
                      <div className="flex-1 min-h-0 w-full p-1 pt-2">
                          {panel.type === 'PVLOOP' && (
                              <PVLoopPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                config={panel.config}
                                showGuides={panel.showGuides}
                              />
                          )}
                          {panel.type === 'WAVEFORM' && (
                              <WaveformPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                timeWindow={panel.timeWindow || 10000}
                                config={panel.config}
                              />
                          )}
                          {panel.type === 'METRICS' && (
                               <MetricsPanel 
                                  physicsRefs={physicsRefs}
                                  instances={instances}
                                  config={panel.config}
                               />
                          )}
                          {(panel.type === 'GUYTON_RIGHT' || panel.type === 'GUYTON_LEFT') && (
                                <GuytonPanel 
                                    physicsRefs={physicsRefs}
                                    instances={instances}
                                    config={panel.config}
                                    type={panel.type}
                                />
                          )}
                      </div>

                      {/* Resize Handle */}
                      <div 
                        onMouseDown={(e) => startResize(e, panel)}
                        className="absolute bottom-0 right-0 w-4 h-4 cursor-se-resize flex items-end justify-end p-0.5 z-40 group/handle"
                      >
                          <div className="w-0 h-0 border-l-[8px] border-l-transparent border-b-[8px] border-b-slate-600 group-hover/handle:border-b-blue-500"></div>
                      </div>
                  </div>
              )})}
          </div>
      </main>
    </div>
  );
}

export default App;

export interface SimulationParams {
    // Resistances
    Ras: number;
    Rcs: number;
    Rvs: number;
    Ras_prox: number;
    Rcp: number;
    Rap: number;
    Rvp: number;
    Rap_prox: number;
    Rmv: number;
    Rtv: number;
    Rda: number;

    // Compliances
    Cas: number;
    Cvs: number;
    Cas_prox: number;
    Cap: number;
    Cvp: number;
    Cap_prox: number;
    Cda: number;

    // Left Ventricle
    LV_Ees: number;
    LV_V0: number;
    LV_alpha: number;
    LV_beta: number;
    LV_Tmax: number;
    LV_tau: number;
    LV_AV_delay: number;

    // Left Atrium
    LA_Ees: number;
    LA_V0: number;
    LA_alpha: number;
    LA_beta: number;
    LA_Tmax: number;
    LA_tau: number;
    LA_AV_delay: number;

    // Right Ventricle
    RV_Ees: number;
    RV_V0: number;
    RV_alpha: number;
    RV_beta: number;
    RV_Tmax: number;
    RV_tau: number;
    RV_AV_delay: number;

    // Right Atrium
    RA_Ees: number;
    RA_V0: number;
    RA_alpha: number;
    RA_beta: number;
    RA_Tmax: number;
    RA_tau: number;
    RA_AV_delay: number;

    // General
    HR: number;

    // Valve Regurgitation (Resistance backward)
    Ravr: number;
    Ravs: number;
    Rmvr: number;
    Rmvs: number;
    Rpvr: number;
    Rpvs: number;
    Rtvr: number;
    Rtvs: number;
}

export interface SimulationState {
    Qvs: number;
    Qas: number;
    Qap: number;
    Qvp: number;
    Qlv: number;
    Qla: number;
    Qrv: number;
    Qra: number;
    Qas_prox: number;
    Qda: number;
    Qap_prox: number;
    Qtube: number;
}

export interface SimulationOutput {
    t: number;
    y: SimulationState;
    aux: {
      Plv: number;
      Pla: number;
      Prv: number;
      Pra: number;
      AoP: number;
      PAP: number;
    };
}

export type StateVector = number[];

export type ChamberId = 'LV' | 'LA' | 'RV' | 'RA';

// Instance management
export interface SimInstance {
    id: string;
    name: string;
    color: string;
    params: SimulationParams;
    targetVolume: number; // New: Target Total Volume
    isVisible: boolean; 
}

// Internal Physics State (Mutable Ref Object)
export interface PhysicsRefState {
    t: number;
    y: StateVector;
    buffer: SimulationOutput[]; 
    lastRenderX: number;

    // The parameters currently being used by the physics engine.
    // These are updated from the instance.params at specific cardiac phases.
    activeParams: SimulationParams; 
}

export type SignalType = 'Plv' | 'Pla' | 'Prv' | 'Pra' | 'AoP' | 'PAP';
export type MetricType = 'ABP' | 'CVP' | 'PAP' | 'PCWP' | 'SV' | 'CO' | 'Ea_LV';

export type PanelType = 'PVLOOP' | 'WAVEFORM' | 'METRICS' | 'GUYTON_RIGHT' | 'GUYTON_LEFT' | 'GUYTON_3D';

export interface PanelInstanceConfig {
    [instanceId: string]: {
        visible: boolean;
        selectedSignals: string[]; 
        customColors?: { [key: string]: string }; 
    }
}

export interface PanelDef {
    id: string;
    type: PanelType;
    title: string;
    w: number; 
    h: number; 
    config: PanelInstanceConfig;
    isSettingsOpen?: boolean;
    showGuides?: boolean; 
    timeWindow?: number; 
}

import React, { useState } from 'react';
import { SimulationParams, SimInstance, PanelType } from '../types';

interface ControlsProps {
  instances: SimInstance[];
  activeInstanceId: string;
  setActiveInstanceId: (id: string) => void;
  updateInstanceParams: (id: string, params: Partial<SimulationParams>) => void;
  updateInstanceVolume: (id: string, vol: number) => void;
  updateInstanceColor: (id: string, color: string) => void;
  addInstance: () => void;
  removeInstance: (id: string) => void;

  timeScale: number;
  setTimeScale: (v: number) => void;
  isPlaying: boolean;
  togglePlay: () => void;

  addPanel: (type: PanelType) => void;
}

const Slider = ({ label, value, min, max, step, onChange, unit }: { label: string, value: number, min: number, max: number, step: number, onChange: (val: number) => void, unit?: string }) => (
  <div className="mb-3">
    <div className="flex justify-between text-xs text-slate-400 mb-1">
      <span>{label}</span>
      <span>{value.toFixed(2)} {unit}</span>
    </div>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={(e) => onChange(parseFloat(e.target.value))}
      className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500 hover:accent-blue-400"
    />
  </div>
);

const GroupHeader = ({ title, isOpen, toggle }: { title: string, isOpen: boolean, toggle: () => void }) => (
    <div 
        onClick={toggle}
        className="flex justify-between items-center cursor-pointer bg-slate-800 p-2 rounded mt-2 hover:bg-slate-700 transition-colors"
    >
        <span className="text-xs font-bold text-slate-200 uppercase">{title}</span>
        <span className="text-xs text-slate-400">{isOpen ? '▼' : '▶'}</span>
    </div>
);

export const Controls: React.FC<ControlsProps> = ({ 
    instances, activeInstanceId, setActiveInstanceId, updateInstanceParams, updateInstanceVolume, updateInstanceColor, addInstance, removeInstance,
    timeScale, setTimeScale, isPlaying, togglePlay,
    addPanel
}) => {

  const activeInstance = instances.find(i => i.id === activeInstanceId) || instances[0];
  const params = activeInstance?.params;

  // Tab State
  const [openGroups, setOpenGroups] = useState<{ [key: string]: boolean }>({
      general: true,
      lv: true,
      sys: false,
      rv: false,
      pulm: false,
      la: false,
      ra: false
  });

  const toggleGroup = (key: string) => setOpenGroups(prev => ({ ...prev, [key]: !prev[key] }));

  const update = (key: keyof SimulationParams, val: number) => {
      if (activeInstance) {
        updateInstanceParams(activeInstance.id, { [key]: val });
      }
  };

  // Helper for Macro Sliders
  // Systemic R components: Ras, Rcs, Rvs, Ras_prox, Rda
  const getSystemicR = () => params.Ras + params.Rcs + params.Rvs + params.Ras_prox + params.Rda;
  const setSystemicR = (newTotal: number) => {
      const currentTotal = getSystemicR();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Ras: params.Ras * ratio,
          Rcs: params.Rcs * ratio,
          Rvs: params.Rvs * ratio,
          Ras_prox: params.Ras_prox * ratio,
          Rda: params.Rda * ratio
      });
  };

  // Systemic C components: Cas, Cvs, Cas_prox, Cda
  const getSystemicC = () => params.Cas + params.Cvs + params.Cas_prox + params.Cda;
  const setSystemicC = (newTotal: number) => {
      const currentTotal = getSystemicC();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Cas: params.Cas * ratio,
          Cvs: params.Cvs * ratio,
          Cas_prox: params.Cas_prox * ratio,
          Cda: params.Cda * ratio
      });
  };

  // Pulmonary R: Rap, Rvp, Rap_prox, Rcp
  const getPulmR = () => params.Rap + params.Rvp + params.Rap_prox + params.Rcp;
  const setPulmR = (newTotal: number) => {
      const currentTotal = getPulmR();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Rap: params.Rap * ratio,
          Rvp: params.Rvp * ratio,
          Rap_prox: params.Rap_prox * ratio,
          Rcp: params.Rcp * ratio
      });
  };

  // Pulmonary C: Cap, Cvp, Cap_prox
  const getPulmC = () => params.Cap + params.Cvp + params.Cap_prox;
  const setPulmC = (newTotal: number) => {
      const currentTotal = getPulmC();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Cap: params.Cap * ratio,
          Cvp: params.Cvp * ratio,
          Cap_prox: params.Cap_prox * ratio
      });
  };


  return (
    <div className="space-y-6 pb-20">

      {/* Simulation Control */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
        <h3 className="text-sm font-bold text-slate-100 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Global Physics</h3>

        <div className="mb-4 flex items-center gap-2">
            <button 
                onClick={togglePlay}
                className={`flex-1 py-2 rounded font-bold text-sm transition-colors ${isPlaying ? 'bg-amber-600 hover:bg-amber-500 text-white' : 'bg-emerald-600 hover:bg-emerald-500 text-white'}`}
            >
                {isPlaying ? 'PAUSE' : 'PLAY'}
            </button>
        </div>

        <div className="mb-4">
             <div className="flex justify-between text-xs text-slate-400 mb-1">
                <span>Sim Speed</span>
                <span>{timeScale.toFixed(1)}x</span>
            </div>
            <input
                type="range"
                min={0.1}
                max={2.0}
                step={0.1}
                value={timeScale}
                onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
            />
        </div>
      </div>

      {/* Dashboard Layout */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
         <h3 className="text-sm font-bold text-slate-100 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Layout</h3>
         <div className="grid grid-cols-2 gap-2">
            <button onClick={() => addPanel('PVLOOP')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + PV Loop
            </button>
            <button onClick={() => addPanel('WAVEFORM')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + Waveform
            </button>
            <button onClick={() => addPanel('GUYTON_RIGHT')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + Guyton (Right)
            </button>
            <button onClick={() => addPanel('GUYTON_LEFT')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + Guyton (Left)
            </button>
            <button onClick={() => addPanel('GUYTON_3D')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center col-span-2">
               + Guyton 3D (Bi-V)
            </button>
            <button onClick={() => addPanel('METRICS')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center col-span-2">
               + Metrics
            </button>
         </div>
      </div>

      {/* Instances Management */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
          <div className="flex justify-between items-center mb-2 border-b border-slate-800 pb-2">
            <h3 className="text-sm font-bold text-white uppercase tracking-wider">Models</h3>
            <button onClick={addInstance} className="text-xs bg-indigo-600 hover:bg-indigo-500 px-2 py-1 rounded text-white">+ Add</button>
          </div>
          <div className="space-y-2">
              {instances.map(inst => (
                  <div 
                    key={inst.id} 
                    className={`flex items-center justify-between p-2 rounded cursor-pointer border ${activeInstanceId === inst.id ? 'bg-slate-800 border-indigo-500/50' : 'bg-slate-950 border-slate-800 hover:border-slate-700'}`}
                    onClick={() => setActiveInstanceId(inst.id)}
                  >
                      <div className="flex items-center gap-2">
                          <input 
                            type="color" 
                            value={inst.color}
                            onChange={(e) => updateInstanceColor(inst.id, e.target.value)}
                            className="w-4 h-4 rounded overflow-hidden border-none p-0 cursor-pointer"
                          />
                          <span className="text-xs font-semibold text-slate-200">{inst.name}</span>
                      </div>
                      <div className="flex items-center gap-2">
                          {instances.length > 1 && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); removeInstance(inst.id); }}
                                className="text-slate-500 hover:text-red-400 px-1"
                            >
                                ✕
                            </button>
                          )}
                      </div>
                  </div>
              ))}
          </div>
      </div>

      {/* Params for Active Instance */}
      {params && (
          <div className="p-4 bg-slate-900 rounded-xl border border-slate-800 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-1 h-full" style={{ backgroundColor: activeInstance.color }}></div>
                <h3 className="text-sm font-bold text-white uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">
                    {activeInstance.name} Config
                </h3>

                {/* General Group */}
                <GroupHeader title="General" isOpen={openGroups.general} toggle={() => toggleGroup('general')} />
                {openGroups.general && (
                    <div className="mt-3 pl-1 border-l-2 border-slate-700">
                        <Slider label="Heart Rate" value={params.HR} min={30} max={200} step={1} onChange={(v) => update('HR', v)} unit="bpm" />
                        <Slider label="Total Volume" value={activeInstance.targetVolume} min={1000} max={8000} step={50} onChange={(v) => updateInstanceVolume(activeInstance.id, v)} unit="mL" />
                    </div>
                )}

                {/* Left Ventricle */}
                <GroupHeader title="Left Ventricle" isOpen={openGroups.lv} toggle={() => toggleGroup('lv')} />
                {openGroups.lv && (
                    <div className="mt-3 pl-1 border-l-2 border-purple-500/30">
                        <Slider label="Ees (Contractility)" value={params.LV_Ees} min={0.5} max={10.0} step={0.1} onChange={(v) => update('LV_Ees', v)} unit="mmHg/mL" />
                        <Slider label="V0 (Unstressed Vol)" value={params.LV_V0} min={-50} max={100} step={5} onChange={(v) => update('LV_V0', v)} unit="mL" />
                        <Slider label="Alpha (Stiffness)" value={params.LV_alpha} min={0.01} max={0.1} step={0.001} onChange={(v) => update('LV_alpha', v)} unit="/mL" />
                        <Slider label="Beta (EDP Scale)" value={params.LV_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('LV_beta', v)} unit="mmHg" />
                        <Slider label="Tau (Relaxation)" value={params.LV_tau} min={10} max={100} step={1} onChange={(v) => update('LV_tau', v)} unit="ms" />
                    </div>
                )}

                {/* Systemic */}
                <GroupHeader title="Systemic Circulation" isOpen={openGroups.sys} toggle={() => toggleGroup('sys')} />
                {openGroups.sys && (
                    <div className="mt-3 pl-1 border-l-2 border-blue-500/30">
                        <Slider label="Total Resistance" value={getSystemicR()} min={500} max={4000} step={50} onChange={setSystemicR} unit="R" />
                        <Slider label="Total Compliance" value={getSystemicC()} min={0.5} max={10} step={0.1} onChange={setSystemicC} unit="mL/mmHg" />
                    </div>
                )}

                 {/* Right Ventricle */}
                <GroupHeader title="Right Ventricle" isOpen={openGroups.rv} toggle={() => toggleGroup('rv')} />
                {openGroups.rv && (
                    <div className="mt-3 pl-1 border-l-2 border-teal-500/30">
                        <Slider label="Ees (Contractility)" value={params.RV_Ees} min={0.1} max={5.0} step={0.1} onChange={(v) => update('RV_Ees', v)} unit="mmHg/mL" />
                        <Slider label="V0 (Unstressed Vol)" value={params.RV_V0} min={-50} max={100} step={5} onChange={(v) => update('RV_V0', v)} unit="mL" />
                        <Slider label="Alpha (Stiffness)" value={params.RV_alpha} min={0.01} max={0.1} step={0.001} onChange={(v) => update('RV_alpha', v)} unit="/mL" />
                        <Slider label="Beta (EDP Scale)" value={params.RV_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('RV_beta', v)} unit="mmHg" />
                        <Slider label="Tau (Relaxation)" value={params.RV_tau} min={10} max={100} step={1} onChange={(v) => update('RV_tau', v)} unit="ms" />
                    </div>
                )}

                {/* Pulmonary */}
                <GroupHeader title="Pulmonary Circulation" isOpen={openGroups.pulm} toggle={() => toggleGroup('pulm')} />
                {openGroups.pulm && (
                    <div className="mt-3 pl-1 border-l-2 border-cyan-500/30">
                        <Slider label="Total Resistance" value={getPulmR()} min={50} max={1000} step={10} onChange={setPulmR} unit="R" />
                        <Slider label="Total Compliance" value={getPulmC()} min={1} max={20} step={0.5} onChange={setPulmC} unit="mL/mmHg" />
                    </div>
                )}

                 {/* Left Atrium */}
                <GroupHeader title="Left Atrium" isOpen={openGroups.la} toggle={() => toggleGroup('la')} />
                {openGroups.la && (
                    <div className="mt-3 pl-1 border-l-2 border-slate-700">
                        <Slider label="Ees" value={params.LA_Ees} min={0.1} max={2.0} step={0.05} onChange={(v) => update('LA_Ees', v)} unit="mmHg/mL" />
                        <Slider label="Beta" value={params.LA_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('LA_beta', v)} unit="mmHg" />
                    </div>
                )}

                 {/* Right Atrium */}
                <GroupHeader title="Right Atrium" isOpen={openGroups.ra} toggle={() => toggleGroup('ra')} />
                {openGroups.ra && (
                    <div className="mt-3 pl-1 border-l-2 border-slate-700">
                         <Slider label="Ees" value={params.RA_Ees} min={0.1} max={2.0} step={0.05} onChange={(v) => update('RA_Ees', v)} unit="mmHg/mL" />
                         <Slider label="Beta" value={params.RA_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('RA_beta', v)} unit="mmHg" />
                    </div>
                )}

          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, SimInstance, PhysicsRefState, PanelDef, PanelType, PanelInstanceConfig, ChamberId, SignalType, MetricType } from './types';
import { stepRK4, getTotalVolume } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopPanel, WaveformPanel, MetricsPanel, GuytonPanel } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

const ALL_CHAMBERS: ChamberId[] = ['LV', 'LA', 'RV', 'RA'];
const ALL_SIGNALS: SignalType[] = ['Plv', 'AoP', 'Pla', 'Prv', 'PAP', 'Pra'];
const ALL_METRICS: MetricType[] = ['ABP', 'CVP', 'PAP', 'PCWP', 'SV', 'CO', 'Ea_LV'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { 
          id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], 
          params: { ...DEFAULT_PARAMS }, 
          targetVolume: getTotalVolume(INITIAL_STATE_VECTOR), 
          isVisible: true 
      }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Panel Management State ---
  const [panels, setPanels] = useState<PanelDef[]>([
      { 
          id: 'p1', type: 'PVLOOP', title: 'LV PV Loop', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['LV'] } },
          showGuides: true, isSettingsOpen: false
      },
      { 
          id: 'p2', type: 'WAVEFORM', title: 'Monitor', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['Plv', 'AoP'] } },
          timeWindow: 10000,
          isSettingsOpen: false
      }
  ]);

  // --- Refs for Physics Loop ---
  const timeScaleRef = useRef(timeScale);
  const isPlayingRef = useRef(isPlaying);
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());
  const instanceRefs = useRef<SimInstance[]>(instances);

  useEffect(() => { timeScaleRef.current = timeScale; }, [timeScale]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { instanceRefs.current = instances; }, [instances]);

  // Init physics refs
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              let syncTime = INITIAL_TIME;
              if (physicsRefs.current.size > 0) {
                  for (const p of physicsRefs.current.values()) {
                      if (p.t > syncTime) syncTime = p.t;
                  }
              }
              physicsRefs.current.set(inst.id, {
                  t: syncTime, 
                  y: [...INITIAL_STATE_VECTOR], 
                  buffer: [], 
                  lastRenderX: 0,
                  activeParams: { ...inst.params } 
              });

              setPanels(prev => prev.map(p => {
                 if (p.config[inst.id]) return p;
                 const newConfig = { ...p.config };

                 // Default config for new instance based on panel type
                 let defaultSigs: string[] = [];
                 if (p.type === 'PVLOOP') defaultSigs = ['LV'];
                 else if (p.type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
                 else if (p.type === 'METRICS') defaultSigs = ['ABP', 'CO'];
                 else if (p.type === 'GUYTON_RIGHT' || p.type === 'GUYTON_LEFT' || p.type === 'GUYTON_3D') defaultSigs = ['default'];

                 newConfig[inst.id] = { 
                     visible: true, 
                     selectedSignals: defaultSigs
                 };
                 return { ...p, config: newConfig };
              }));
          }
      });
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) physicsRefs.current.delete(id);
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; 
    const baseStepsPerFrame = 8; 

    const loop = () => {
      if (!isPlayingRef.current) {
          animationFrameId = requestAnimationFrame(loop);
          return;
      }

      const currentScale = timeScaleRef.current;
      const stepsToRun = Math.round(baseStepsPerFrame * currentScale);

      for (let i = 0; i < stepsToRun; i++) {
         instanceRefs.current.forEach(uiInst => {
             const phys = physicsRefs.current.get(uiInst.id);
             if (!phys) return;

             const T = 60000.0 / phys.activeParams.HR; 
             const prevPhase = (phys.t - dt) % T;
             const currPhase = phys.t % T;

             const isEndDiastole = currPhase < prevPhase;
             const tMax = phys.activeParams.LV_Tmax;
             const isEndSystole = prevPhase < tMax && currPhase >= tMax;

             if (isEndDiastole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.HR = p.HR;

                 ap.Ras = p.Ras; ap.Rcs = p.Rcs; ap.Rvs = p.Rvs; ap.Ras_prox = p.Ras_prox; ap.Rda = p.Rda;
                 ap.Rap = p.Rap; ap.Rvp = p.Rvp; ap.Rap_prox = p.Rap_prox; ap.Rcp = p.Rcp;
                 ap.Rmv = p.Rmv; ap.Rtv = p.Rtv;

                 ap.Cas = p.Cas; ap.Cvs = p.Cvs; ap.Cas_prox = p.Cas_prox; ap.Cda = p.Cda;
                 ap.Cap = p.Cap; ap.Cvp = p.Cvp; ap.Cap_prox = p.Cap_prox;

                 ap.LV_Ees = p.LV_Ees; ap.LV_V0 = p.LV_V0;
                 ap.RV_Ees = p.RV_Ees; ap.RV_V0 = p.RV_V0;
                 ap.LA_Ees = p.LA_Ees; ap.LA_V0 = p.LA_V0;
                 ap.RA_Ees = p.RA_Ees; ap.RA_V0 = p.RA_V0;

                 const currentTotal = getTotalVolume(phys.y);
                 const targetTotal = uiInst.targetVolume;
                 const diff = targetTotal - currentTotal;
                 const maxDelta = 500; 
                 const delta = Math.max(-maxDelta, Math.min(maxDelta, diff));

                 if (Math.abs(delta) > 1.0) {
                     phys.y[0] += delta;
                 }
             }

             if (isEndSystole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.LV_alpha = p.LV_alpha; ap.LV_beta = p.LV_beta; ap.LV_tau = p.LV_tau; ap.LV_Tmax = p.LV_Tmax;
                 ap.RV_alpha = p.RV_alpha; ap.RV_beta = p.RV_beta; ap.RV_tau = p.RV_tau; ap.RV_Tmax = p.RV_Tmax;
                 ap.LA_alpha = p.LA_alpha; ap.LA_beta = p.LA_beta; ap.LA_tau = p.LA_tau;
                 ap.RA_alpha = p.RA_alpha; ap.RA_beta = p.RA_beta; ap.RA_tau = p.RA_tau;
             }

             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, phys.activeParams);
             phys.t = tNext;
             phys.y = yNext;

             const bufferRequiredMs = 21000;
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };
            phys.buffer.push(output);
            const cutoffTime = tNext - bufferRequiredMs;
            if (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }
      animationFrameId = requestAnimationFrame(loop);
    };
    animationFrameId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const updateInstanceVolume = (id: string, vol: number) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, targetVolume: vol } : inst
      ));
  }

  const updateInstanceColor = (id: string, color: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, color: color } : inst
    ));
  }
  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];
      setInstances(prev => [...prev, {
          id: newId, name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color, 
          params: { ...DEFAULT_PARAMS }, 
          targetVolume: getTotalVolume(INITIAL_STATE_VECTOR),
          isVisible: true
      }]);
      setActiveInstanceId(newId);
  };
  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) setActiveInstanceId(instances[0]?.id || '');
  };

  // --- Panel Handlers ---
  const addPanel = (type: PanelType) => {
      const newConfig: PanelInstanceConfig = {};
      instances.forEach(i => {
          let defaultSigs: string[] = [];
          if (type === 'PVLOOP') defaultSigs = ['LV'];
          else if (type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
          else if (type === 'METRICS') defaultSigs = ['ABP', 'CO'];
          else if (type === 'GUYTON_RIGHT' || type === 'GUYTON_LEFT' || type === 'GUYTON_3D') defaultSigs = ['Default'];

          newConfig[i.id] = {
              visible: true,
              selectedSignals: defaultSigs
          };
      });

      let title = 'Panel';
      if (type === 'PVLOOP') title = 'PV Loop';
      else if (type === 'WAVEFORM') title = 'Waveforms';
      else if (type === 'METRICS') title = 'Metrics';
      else if (type === 'GUYTON_RIGHT') title = 'Guyton (Right/Sys)';
      else if (type === 'GUYTON_LEFT') title = 'Guyton (Left/Pulm)';
      else if (type === 'GUYTON_3D') title = 'Guyton 3D (Bi-V)';

      const newPanel: PanelDef = {
          id: Date.now().toString(),
          type,
          title,
          w: type === 'METRICS' ? 4 : 6, 
          h: type === 'METRICS' ? 6 : 8,
          config: newConfig,
          showGuides: type === 'PVLOOP',
          timeWindow: type === 'WAVEFORM' ? 10000 : undefined,
          isSettingsOpen: false
      };
      setPanels(prev => [...prev, newPanel]);
  };

  const removePanel = (id: string) => {
      setPanels(prev => prev.filter(p => p.id !== id));
  };

  const resizeState = useRef<{ panelId: string, startX: number, startY: number, startW: number, startH: number } | null>(null);

  const startResize = (e: React.MouseEvent, panel: PanelDef) => {
      e.stopPropagation();
      e.preventDefault();
      resizeState.current = {
          panelId: panel.id,
          startX: e.clientX,
          startY: e.clientY,
          startW: panel.w,
          startH: panel.h
      };
      document.addEventListener('mousemove', onResizeMove);
      document.addEventListener('mouseup', onResizeEnd);
  };

  const onResizeMove = (e: MouseEvent) => {
      if (!resizeState.current) return;
      const { panelId, startX, startY, startW, startH } = resizeState.current;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      const wDelta = Math.round(dx / 50);
      const hDelta = Math.round(dy / 50);
      const newW = Math.max(2, Math.min(12, startW + wDelta)); 
      const newH = Math.max(4, Math.min(20, startH + hDelta)); 

      setPanels(prev => prev.map(p => 
          p.id === panelId ? { ...p, w: newW, h: newH } : p
      ));
  };

  const onResizeEnd = () => {
      resizeState.current = null;
      document.removeEventListener('mousemove', onResizeMove);
      document.removeEventListener('mouseup', onResizeEnd);
  };


  // --- Config Logic ---
  const toggleSettings = (panelId: string) => {
      setPanels(prev => prev.map(p => 
        p.id === panelId ? { ...p, isSettingsOpen: !p.isSettingsOpen } : { ...p, isSettingsOpen: false }
      ));
  };

  const toggleInstanceVisibility = (panelId: string, instId: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, visible: !prevCfg.visible }
              }
          };
      }));
  };

  const updateInstanceSignals = (panelId: string, instId: string, signal: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          const currentSigs = new Set(prevCfg.selectedSignals);
          if (currentSigs.has(signal)) currentSigs.delete(signal); else currentSigs.add(signal);

          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, selectedSignals: Array.from(currentSigs) }
              }
          };
      }));
  };

  const updateCustomColor = (panelId: string, instId: string, signal: string, color: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { 
                      ...prevCfg, 
                      customColors: { ...prevCfg.customColors, [signal]: color } 
                  }
              }
          };
      }));
  }

  const toggleGuides = (panelId: string) => {
     setPanels(prev => prev.map(p => p.id === panelId ? { ...p, showGuides: !p.showGuides } : p));
  }

  const updateTimeWindow = (panelId: string, val: number) => {
      setPanels(prev => prev.map(p => p.id === panelId ? { ...p, timeWindow: val } : p));
  }

  // --- Drag & Drop ---
  const dragItemRef = useRef<number | null>(null);
  const dragOverItemRef = useRef<number | null>(null);

  const onDragStart = (e: React.DragEvent, index: number) => {
    dragItemRef.current = index;
    e.dataTransfer.effectAllowed = "move";
  };
  const onDragEnter = (e: React.DragEvent, index: number) => {
    dragOverItemRef.current = index;
  };
  const onDragEnd = () => {
    const srcIdx = dragItemRef.current;
    const dstIdx = dragOverItemRef.current;
    if (srcIdx !== null && dstIdx !== null && srcIdx !== dstIdx) {
       setPanels(prev => {
           const next = [...prev];
           const [removed] = next.splice(srcIdx, 1);
           next.splice(dstIdx, 0, removed);
           return next;
       });
    }
    dragItemRef.current = null;
    dragOverItemRef.current = null;
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      <aside className="w-80 h-full bg-slate-900 border-r border-slate-800 overflow-y-auto flex-shrink-0 z-20 shadow-xl">
        <div className="p-5">
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
            HemoSim 0D
          </h1>
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            updateInstanceVolume={updateInstanceVolume}
            updateInstanceColor={updateInstanceColor}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}

            addPanel={addPanel}
          />
        </div>
      </aside>

      <main className="flex-1 h-full overflow-y-auto overflow-x-hidden bg-slate-950 p-2">
          {/* 12 Column Grid for Fine control */}
          <div className="grid grid-cols-12 gap-2 auto-rows-[50px] grid-flow-dense pb-20">
              {panels.map((panel, index) => {
                  return (
                  <div 
                    key={panel.id} 
                    draggable
                    onDragStart={(e) => onDragStart(e, index)}
                    onDragEnter={(e) => onDragEnter(e, index)}
                    onDragEnd={onDragEnd}
                    onDragOver={(e) => e.preventDefault()}
                    style={{ gridColumn: `span ${panel.w}`, gridRow: `span ${panel.h}` }}
                    className="relative bg-slate-900/50 rounded-lg border border-slate-800 shadow-inner flex flex-col overflow-visible group hover:border-slate-600 transition-colors"
                  >
                      {/* Panel Header */}
                      <div className="absolute top-2 left-2 z-30 flex gap-2 items-center pointer-events-auto">
                           <div className="bg-slate-950/90 px-2 py-1 rounded border border-slate-700 backdrop-blur-sm shadow-sm flex items-center gap-2 cursor-move">
                                <span className="text-xs font-bold text-slate-300 select-none">⋮⋮ {panel.title}</span>
                                <div className="h-3 w-[1px] bg-slate-700 mx-1"></div>

                                {/* Settings Toggle (Click-based) */}
                                <div className="relative">
                                    <button 
                                        onClick={() => toggleSettings(panel.id)}
                                        className={`text-[10px] px-1 flex items-center gap-1 rounded hover:bg-slate-800 ${panel.isSettingsOpen ? 'text-blue-400 bg-slate-800' : 'text-slate-400'}`}
                                    >
                                        <span className="w-3 h-3 border border-current rounded-sm flex items-center justify-center">
                                            <span className="text-[8px]">⚙</span>
                                        </span>
                                    </button>

                                    {/* Dropdown Content */}
                                    {panel.isSettingsOpen && (
                                        <div className="absolute top-full left-0 mt-2 w-56 bg-slate-900 border border-slate-700 rounded shadow-2xl p-3 z-50">
                                            <div className="flex justify-between items-center mb-2 pb-2 border-b border-slate-800">
                                                <span className="text-[10px] font-bold text-slate-500 uppercase">Configuration</span>
                                                <button onClick={() => toggleSettings(panel.id)} className="text-xs text-slate-400 hover:text-white">✕</button>
                                            </div>

                                            {/* Panel Specific Settings */}
                                            {panel.type === 'PVLOOP' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800 flex items-center gap-2">
                                                    <input type="checkbox" checked={panel.showGuides} onChange={() => toggleGuides(panel.id)} />
                                                    <span className="text-xs text-slate-300">Show Guides</span>
                                                </div>
                                            )}
                                            {panel.type === 'WAVEFORM' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800">
                                                    <div className="flex justify-between text-[10px] text-slate-400 mb-1">
                                                        <span>Window</span>
                                                        <span>{(panel.timeWindow || 10000) / 1000}s</span>
                                                    </div>
                                                    <input 
                                                        type="range" min={2000} max={20000} step={1000} 
                                                        value={panel.timeWindow || 10000}
                                                        onChange={(e) => updateTimeWindow(panel.id, parseFloat(e.target.value))}
                                                        className="w-full h-1 bg-slate-700 rounded appearance-none cursor-pointer accent-blue-500"
                                                    />
                                                </div>
                                            )}

                                            <div className="max-h-64 overflow-y-auto space-y-3 custom-scrollbar">
                                                {instances.map(inst => (
                                                    <div key={inst.id}>
                                                        <div className="flex items-center gap-2 mb-1">
                                                            <input 
                                                                type="checkbox" 
                                                                checked={panel.config[inst.id]?.visible || false}
                                                                onChange={() => toggleInstanceVisibility(panel.id, inst.id)}
                                                            />
                                                            <span className="w-2 h-2 rounded-full" style={{backgroundColor: inst.color}}></span>
                                                            <span className="text-xs font-bold text-slate-300 truncate flex-1">{inst.name}</span>
                                                        </div>
                                                        {/* Sub Signals & Colors */}
                                                        {panel.config[inst.id]?.visible && (panel.type !== 'GUYTON_RIGHT' && panel.type !== 'GUYTON_LEFT' && panel.type !== 'GUYTON_3D') && (
                                                            <div className="pl-5 grid grid-cols-1 gap-1">
                                                                {((panel.type === 'PVLOOP' ? ALL_CHAMBERS : (panel.type === 'WAVEFORM' ? ALL_SIGNALS : ALL_METRICS))).map(sig => {
                                                                    const isSelected = panel.config[inst.id].selectedSignals.includes(sig);
                                                                    const customColor = panel.config[inst.id].customColors?.[sig];

                                                                    return (
                                                                    <div key={sig} className="flex items-center justify-between text-[10px] bg-slate-950/50 rounded px-1 py-0.5">
                                                                        <button 
                                                                            onClick={() => updateInstanceSignals(panel.id, inst.id, sig)}
                                                                            className={`flex-1 text-left ${isSelected ? 'text-slate-200' : 'text-slate-600'}`}
                                                                        >
                                                                            {sig}
                                                                        </button>
                                                                        {isSelected && panel.type !== 'METRICS' && (
                                                                            <input 
                                                                                type="color" 
                                                                                className="w-3 h-3 border-none p-0 bg-transparent cursor-pointer"
                                                                                value={customColor || inst.color} 
                                                                                onChange={(e) => updateCustomColor(panel.id, inst.id, sig, e.target.value)}
                                                                            />
                                                                        )}
                                                                    </div>
                                                                )})}
                                                            </div>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <button onClick={() => removePanel(panel.id)} className="text-slate-500 hover:text-red-400 ml-1">✕</button>
                           </div>
                      </div>

                      {/* Content */}
                      <div className="flex-1 min-h-0 w-full p-1 pt-2">
                          {panel.type === 'PVLOOP' && (
                              <PVLoopPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                config={panel.config}
                                showGuides={panel.showGuides}
                              />
                          )}
                          {panel.type === 'WAVEFORM' && (
                              <WaveformPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                timeWindow={panel.timeWindow || 10000}
                                config={panel.config}
                              />
                          )}
                          {panel.type === 'METRICS' && (
                               <MetricsPanel 
                                  physicsRefs={physicsRefs}
                                  instances={instances}
                                  config={panel.config}
                               />
                          )}
                          {(panel.type === 'GUYTON_RIGHT' || panel.type === 'GUYTON_LEFT' || panel.type === 'GUYTON_3D') && (
                                <GuytonPanel 
                                    physicsRefs={physicsRefs}
                                    instances={instances}
                                    config={panel.config}
                                    type={panel.type as any}
                                />
                          )}
                      </div>

                      {/* Resize Handle */}
                      <div 
                        onMouseDown={(e) => startResize(e, panel)}
                        className="absolute bottom-0 right-0 w-4 h-4 cursor-se-resize flex items-end justify-end p-0.5 z-40 group/handle"
                      >
                          <div className="w-0 h-0 border-l-[8px] border-l-transparent border-b-[8px] border-b-slate-600 group-hover/handle:border-b-blue-500"></div>
                      </div>
                  </div>
              )})}
          </div>
      </main>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { SimInstance, PhysicsRefState, ChamberId, SignalType, PanelInstanceConfig, MetricType, PanelType, SimulationParams } from '../types';

interface ChartPanelProps {
  physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
  instances: SimInstance[];
  config: PanelInstanceConfig;
  showGuides?: boolean;
}

interface WaveformProps extends ChartPanelProps {
    timeWindow: number; 
}

interface GuytonProps extends ChartPanelProps {
    type: 'GUYTON_RIGHT' | 'GUYTON_LEFT' | 'GUYTON_3D';
}

// Helper: Color logic
const getColor = (baseColor: string, signal: string, customColors?: { [key: string]: string }): string => {
    if (customColors && customColors[signal]) {
        return customColors[signal];
    }
    const c = d3.color(baseColor);
    if (!c) return baseColor;

    switch (signal) {
        // Waveform Signals
        case 'AoP': case 'PAP': case 'ABP':
            return c.brighter(1.5).formatHex(); 
        case 'Pla': case 'Pra': case 'CVP': case 'PCWP':
            return c.darker(1.2).formatHex();
        // PV Loop Chambers
        case 'LA': case 'RA':
             return c.darker(1.2).formatHex();
        default: return c.formatHex();
    }
};

// --------------------------------------------------------
// PV Loop Panel
// --------------------------------------------------------
export const PVLoopPanel: React.FC<ChartPanelProps> = ({ physicsRefs, instances, config, showGuides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const scaleRef = useRef({ maxV: 300, maxP: 200 });

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    const xScale = d3.scaleLinear().domain([0, 300]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 200]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // 1. Auto-scale calc
      let currentFrameMaxV = 0;
      let currentFrameMaxP = 0;
      let hasData = false;

      instances.forEach(inst => {
          const cfg = config[inst.id];
          if (!cfg || !cfg.visible || cfg.selectedSignals.length === 0) return;

          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          const data = physState.buffer.slice(-500); 
          for (let i = 0; i < data.length; i += 10) {
              const d = data[i];
              cfg.selectedSignals.forEach(chamber => {
                  let v = 0, p = 0;
                  switch(chamber) {
                      case 'LV': v = d.y.Qlv; p = d.aux.Plv; break;
                      case 'LA': v = d.y.Qla; p = d.aux.Pla; break;
                      case 'RV': v = d.y.Qrv; p = d.aux.Prv; break;
                      case 'RA': v = d.y.Qra; p = d.aux.Pra; break;
                  }
                  if (v > currentFrameMaxV) currentFrameMaxV = v;
                  if (p > currentFrameMaxP) currentFrameMaxP = p;
                  hasData = true;
              });
          }
      });

      if (hasData) {
          currentFrameMaxV *= 1.1; 
          currentFrameMaxP *= 1.1;
          // Smooth Lerp
          scaleRef.current.maxV = scaleRef.current.maxV * 0.9 + Math.max(150, Math.ceil(currentFrameMaxV / 50) * 50) * 0.1;
          scaleRef.current.maxP = scaleRef.current.maxP * 0.9 + Math.max(100, Math.ceil(currentFrameMaxP / 50) * 50) * 0.1;
      }

      xScale.domain([0, scaleRef.current.maxV]).range([50, width - 20]);
      yScale.domain([0, scaleRef.current.maxP]).range([height - 40, 20]);

      // 2. Draw Grid
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      xScale.ticks(6).forEach(t => { ctx.moveTo(xScale(t), height-40); ctx.lineTo(xScale(t), 20); });
      yScale.ticks(6).forEach(t => { ctx.moveTo(50, yScale(t)); ctx.lineTo(width-20, yScale(t)); });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xScale.ticks(6).forEach(t => ctx.fillText(t.toString(), xScale(t), height - 25));
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yScale.ticks(6).forEach(t => ctx.fillText(t.toString(), 45, yScale(t)));

      // Titles
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // 3. Draw Data
      instances.forEach(inst => {
          const cfg = config[inst.id];
          if (!cfg || !cfg.visible) return;

          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;
          const loopData = physState.buffer.slice(-1200); 

          if (showGuides && cfg.selectedSignals.includes('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;
              const vMax = scaleRef.current.maxV;
              // ESPVR
              ctx.beginPath();
              ctx.moveTo(xScale(inst.params.LV_V0), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(inst.params.LV_Ees * (vMax - inst.params.LV_V0)));
              ctx.stroke();
              // EDPVR
              ctx.beginPath();
              let firstPt = true;
              for (let v = Math.max(0, inst.params.LV_V0); v <= vMax; v += (vMax/50)) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > scaleRef.current.maxP) break;
                  const px = xScale(v), py = yScale(ped);
                  if(firstPt) { ctx.moveTo(px,py); firstPt=false;} else ctx.lineTo(px,py);
              }
              ctx.stroke();
              ctx.restore();
          }

          const drawLoop = (c: string) => {
              ctx.beginPath();
              ctx.strokeStyle = getColor(inst.color, c, cfg.customColors);
              ctx.lineWidth = 2;
              const getPt = (d: any) => {
                  switch(c) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              };
              if(loopData.length === 0) return;
              const [sV, sP] = getPt(loopData[0]);
              ctx.moveTo(xScale(sV), yScale(sP));
              for(let i=1; i<loopData.length; i++) {
                  const [v, p] = getPt(loopData[i]);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();
              const [eV, eP] = getPt(loopData[loopData.length-1]);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(eV), yScale(eP), 3, 0, 2*Math.PI);
              ctx.fill();
          }
          cfg.selectedSignals.forEach(c => drawLoop(c));
      });
      animationFrameId = requestAnimationFrame(render);
    };
    render();
    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(containerRef.current);
    return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
  }, [instances, config, showGuides]);

  return (
      <div ref={containerRef} className="w-full h-full relative">
         <canvas ref={canvasRef} className="block" />
      </div>
  );
};

// --------------------------------------------------------
// Waveform Panel (With Auto-Scaling)
// --------------------------------------------------------
export const WaveformPanel: React.FC<WaveformProps> = ({ physicsRefs, instances, timeWindow, config }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const scaleRef = useRef({ yMin: 0, yMax: 160 });

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        const margin = { top: 10, right: 10, bottom: 20, left: 40 };

        let animationFrameId: number;
        const render = () => {
            const innerWidth = width - margin.left - margin.right;
            const innerHeight = height - margin.top - margin.bottom;
            const yScale = d3.scaleLinear().range([margin.top + innerHeight, margin.top]);

            ctx.clearRect(0, 0, width, height);

            let localMin = 1000;
            let localMax = -1000;
            let hasData = false;
            let maxT = 0;

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys) return;
                if(phys.t > maxT) maxT = phys.t;

                if (phys.buffer.length < 2) return;
                const startTime = phys.t - timeWindow;
                const visibleData = phys.buffer.filter(p => p.t > startTime);

                if (visibleData.length === 0) return;
                const step = Math.max(1, Math.floor(visibleData.length / 200));

                for (let i = 0; i < visibleData.length; i += step) {
                     const pt = visibleData[i];
                     cfg.selectedSignals.forEach(sig => {
                         let val = 0;
                         switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                         }
                         if (val < localMin) localMin = val;
                         if (val > localMax) localMax = val;
                         hasData = true;
                     });
                }
            });

            if (hasData) {
                const range = localMax - localMin;
                const pad = Math.max(10, range * 0.1);
                const targetMin = Math.max(0, localMin - pad);
                const targetMax = localMax + pad;
                scaleRef.current.yMin = scaleRef.current.yMin * 0.9 + targetMin * 0.1;
                scaleRef.current.yMax = scaleRef.current.yMax * 0.9 + targetMax * 0.1;
            } else {
                scaleRef.current.yMin = scaleRef.current.yMin * 0.95;
                scaleRef.current.yMax = scaleRef.current.yMax * 0.95 + 160 * 0.05;
            }

            yScale.domain([scaleRef.current.yMin, scaleRef.current.yMax]);

            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(margin.left, margin.top);
            ctx.lineTo(margin.left, margin.top + innerHeight);
            ctx.stroke();

            ctx.fillStyle = '#94a3b8';
            ctx.font = '10px sans-serif';
            ctx.textAlign = 'right';
            ctx.textBaseline = 'middle';
            yScale.ticks(5).forEach(t => {
                const y = yScale(t);
                ctx.beginPath();
                ctx.moveTo(margin.left, y);
                ctx.lineTo(margin.left - 5, y);
                ctx.stroke();
                ctx.fillText(t.toString(), margin.left - 8, y);

                ctx.save();
                ctx.strokeStyle = '#334155';
                ctx.globalAlpha = 0.2;
                ctx.beginPath();
                ctx.moveTo(margin.left, y);
                ctx.lineTo(width - margin.right, y);
                ctx.stroke();
                ctx.restore();
            });

            if (maxT === 0) { animationFrameId = requestAnimationFrame(render); return; }

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;

                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 2) return;
                const validData = phys.buffer.filter(p => p.t > phys.t - timeWindow - 100);

                const drawSig = (sig: SignalType) => {
                    ctx.beginPath();
                    ctx.strokeStyle = getColor(inst.color, sig, cfg.customColors);
                    ctx.lineWidth = 2;
                    let first = true; let prevX = -1;

                    ctx.save();
                    ctx.beginPath();
                    ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
                    ctx.clip();
                    ctx.beginPath();

                    for(let i=0; i<validData.length; i+=2) {
                        const pt = validData[i];
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }
                        const xRel = (pt.t % timeWindow) / timeWindow;
                        const x = margin.left + xRel * innerWidth;
                        const y = yScale(val);

                        if(first) { ctx.moveTo(x,y); first=false; }
                        else { 
                            if(x < prevX) { ctx.stroke(); ctx.beginPath(); ctx.moveTo(x,y); }
                            else ctx.lineTo(x,y); 
                        }
                        prevX = x;
                    }
                    ctx.stroke();
                    ctx.restore();
                };
                cfg.selectedSignals.forEach(s => drawSig(s as SignalType));

                if(phys.buffer.length>0) {
                    const pt = phys.buffer[phys.buffer.length-1];
                    const xRel = (pt.t % timeWindow) / timeWindow;
                    const x = margin.left + xRel * innerWidth;

                    const drawHead = (sig: SignalType) => {
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }
                        ctx.beginPath();
                        ctx.fillStyle = getColor(inst.color, sig, cfg.customColors);
                        ctx.arc(x, yScale(val), 4, 0, 2*Math.PI);
                        ctx.fill();
                        ctx.strokeStyle='#fff'; ctx.lineWidth=1; ctx.stroke();
                    };
                    cfg.selectedSignals.forEach(s => drawHead(s as SignalType));
                }
            });

            const xRelCursor = (maxT % timeWindow) / timeWindow;
            const cursorX = margin.left + xRelCursor * innerWidth;
            const eraseWidth = (300 / timeWindow) * innerWidth; 

            ctx.save();
            ctx.beginPath();
            ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
            ctx.clip();
            ctx.clearRect(cursorX, margin.top, eraseWidth, innerHeight);
            if (cursorX + eraseWidth > width) {
                const remainder = (cursorX + eraseWidth) - (margin.left + innerWidth);
                if (remainder > 0) ctx.clearRect(margin.left, margin.top, remainder, innerHeight);
            }
            ctx.restore();

            animationFrameId = requestAnimationFrame(render);
        };
        render();
        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);
        return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
    }, [instances, timeWindow, config]);

    return (
        <div className="flex flex-col h-full w-full relative group">
            <div ref={containerRef} className="flex-1 w-full min-h-0 relative">
                <canvas ref={canvasRef} className="block relative z-10" />
            </div>
            <div className="absolute top-2 right-2 pointer-events-none z-20 opacity-50 text-[10px] text-slate-400">
                Window: {timeWindow/1000}s
            </div>
        </div>
    );
};

// --------------------------------------------------------
// Metrics Panel
// --------------------------------------------------------
export const MetricsPanel: React.FC<ChartPanelProps> = ({ physicsRefs, instances, config }) => {
    // We update metrics every 500ms to avoid UI flickering
    const [metricsData, setMetricsData] = useState<{[key:string]: {[key:string]: string}}>({});

    useEffect(() => {
        const interval = setInterval(() => {
            const nextData: any = {};

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible || cfg.selectedSignals.length === 0) return;

                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 100) return;

                const activeHR = phys.activeParams.HR;
                const cycleMs = 60000 / activeHR;

                // Get data for last cardiac cycle + buffer
                const endTime = phys.t;
                const startTime = endTime - cycleMs;
                const cycleData = phys.buffer.filter(d => d.t >= startTime);

                if (cycleData.length < 10) return;

                const calcMetrics: {[key:string]: string} = {};

                // Helpers
                const getArr = (fn: (d:any)=>number) => cycleData.map(fn);
                const max = (arr: number[]) => Math.max(...arr);
                const min = (arr: number[]) => Math.min(...arr);
                const mean = (arr: number[]) => arr.reduce((a,b)=>a+b,0)/arr.length;

                // 1. AoP (Sys/Dia)
                if (cfg.selectedSignals.includes('ABP')) {
                    const vals = getArr(d => d.aux.AoP);
                    calcMetrics['ABP'] = `${max(vals).toFixed(0)} / ${min(vals).toFixed(0)} mmHg`;
                }
                // 2. PAP (Sys/Dia)
                if (cfg.selectedSignals.includes('PAP')) {
                    const vals = getArr(d => d.aux.PAP);
                    calcMetrics['PAP'] = `${max(vals).toFixed(0)} / ${min(vals).toFixed(0)} mmHg`;
                }
                // 3. CVP (Mean Pra)
                if (cfg.selectedSignals.includes('CVP')) {
                    const vals = getArr(d => d.aux.Pra);
                    calcMetrics['CVP'] = `${mean(vals).toFixed(1)} mmHg`;
                }
                // 4. PCWP (Mean Pla)
                if (cfg.selectedSignals.includes('PCWP')) {
                    const vals = getArr(d => d.aux.Pla);
                    calcMetrics['PCWP'] = `${mean(vals).toFixed(1)} mmHg`;
                }
                // 5. SV (Max - Min LV Volume)
                const lvVols = getArr(d => d.y.Qlv);
                const sv = max(lvVols) - min(lvVols);
                if (cfg.selectedSignals.includes('SV')) {
                    calcMetrics['SV'] = `${sv.toFixed(1)} mL`;
                }
                // 6. CO
                if (cfg.selectedSignals.includes('CO')) {
                    const co = (sv * activeHR) / 1000;
                    calcMetrics['CO'] = `${co.toFixed(2)} L/min`;
                }
                // 7. Ea (Effective Arterial Elastance) approx ESP/SV
                // ESP approx max Plv.
                if (cfg.selectedSignals.includes('Ea_LV')) {
                   const plvVals = getArr(d => d.aux.Plv);
                   const esp = max(plvVals);
                   const ea = sv > 0 ? esp / sv : 0;
                   calcMetrics['Ea_LV'] = `${ea.toFixed(2)} mmHg/mL`;
                }

                nextData[inst.id] = calcMetrics;
            });
            setMetricsData(nextData);

        }, 200);
        return () => clearInterval(interval);
    }, [instances, config]);

    return (
        <div className="w-full h-full p-2 overflow-y-auto custom-scrollbar">
            {instances.map(inst => {
                const cfg = config[inst.id];
                const data = metricsData[inst.id];
                if (!cfg || !cfg.visible || !data) return null;

                return (
                    <div key={inst.id} className="mb-4 bg-slate-900/50 rounded border border-slate-800 p-2">
                         <div className="flex items-center gap-2 mb-2 border-b border-slate-700 pb-1">
                            <span className="w-2 h-2 rounded-full" style={{backgroundColor: inst.color}}></span>
                            <span className="text-xs font-bold text-slate-300">{inst.name}</span>
                         </div>
                         <div className="grid grid-cols-2 gap-2">
                             {cfg.selectedSignals.map(sig => (
                                 data[sig] ? (
                                     <div key={sig} className="flex flex-col bg-slate-950/50 p-1.5 rounded">
                                         <span className="text-[10px] text-slate-500 uppercase font-bold">{sig}</span>
                                         <span className="text-sm font-mono text-slate-200">{data[sig]}</span>
                                     </div>
                                 ) : null
                             ))}
                         </div>
                    </div>
                )
            })}
        </div>
    );
}

// --------------------------------------------------------
// Guyton & Starling Panel (2D and 3D)
// --------------------------------------------------------
export const GuytonPanel: React.FC<GuytonProps> = ({ physicsRefs, instances, config, type }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    // Calc helpers based on resistance chains for Guyton
    const getGuytonParams = (p: SimulationParams) => {
        // Systemic W calculation based on resistance chain
        // Chain: as_prox -> da -> as -> cs -> vs -> RA
        // Cas_prox sees: Rda + Ras + Rcs + Rvs
        // Cda sees: Ras + Rcs + Rvs
        // Cas sees: Rcs + Rvs
        // Cvs sees: Rvs

        const W_s = 
            p.Cas_prox * (p.Rda + p.Ras + p.Rcs + p.Rvs) +
            p.Cda * (p.Ras + p.Rcs + p.Rvs) +
            p.Cas * (p.Rcs + p.Rvs) +
            p.Cvs * (p.Rvs);
        const C_s = p.Cas_prox + p.Cda + p.Cas + p.Cvs;

        // Pulmonary W
        // Chain: ap_prox -> cp -> ap -> vp -> LA
        // Cap_prox sees: Rcp + Rap + Rvp
        // Cap sees: Rap + Rvp
        // Cvp sees: Rvp

        const W_p = 
            p.Cap_prox * (p.Rcp + p.Rap + p.Rvp) +
            p.Cap * (p.Rap + p.Rvp) +
            p.Cvp * (p.Rvp);
        const C_p = p.Cap_prox + p.Cap + p.Cvp;

        return { W_s, C_s, W_p, C_p };
    };

    const getStarlingCO = (P_ed: number, Ees: number, V0: number, alpha: number, beta: number, Ea: number, HR: number) => {
        // Analytical Starling Curve (Log approximation)
        // SV = Ees/(Ees+Ea) * 1/alpha * ln((P_ed + beta)/beta) - correction
        // Here we assume Voffset handled in formula structure or approximated.
        // Prompt formula: SV = Ees/(Ees+Ea) * 1/alpha * ln((P_ed + beta)/beta). 
        // We assume Volume offset cancels out or is small for this qualitative curve.

        if (P_ed < 0) return 0;
        const term = (Ees / (Ees + Ea)) * (1.0 / alpha) * Math.log((P_ed + beta) / beta);
        const sv_est = Math.max(0, term); 
        return (sv_est * HR) / 1000.0; // L/min
    };

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        let animationFrameId: number;

        const render = () => {
            ctx.clearRect(0, 0, width, height);

            // Common setup
            const margin = { top: 20, right: 20, bottom: 30, left: 40 };
            const innerWidth = width - margin.left - margin.right;
            const innerHeight = height - margin.top - margin.bottom;

            if (type !== 'GUYTON_3D') {
                // -----------------------
                // 2D RENDERING
                // -----------------------

                // Axis Ranges
                const xScale = d3.scaleLinear().domain([0, 20]).range([margin.left, margin.left + innerWidth]);
                const yScale = d3.scaleLinear().domain([0, 15]).range([margin.top + innerHeight, margin.top]);

                // Grid
                ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;
                ctx.beginPath();
                xScale.ticks(6).forEach(t => { ctx.moveTo(xScale(t), margin.top + innerHeight); ctx.lineTo(xScale(t), margin.top); });
                yScale.ticks(6).forEach(t => { ctx.moveTo(margin.left, yScale(t)); ctx.lineTo(margin.left + innerWidth, yScale(t)); });
                ctx.stroke();

                // Labels
                ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif';
                ctx.textAlign = 'center';
                xScale.ticks(6).forEach(t => ctx.fillText(t.toString(), xScale(t), margin.top + innerHeight + 15));
                ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
                yScale.ticks(6).forEach(t => ctx.fillText(t.toString(), margin.left - 5, yScale(t)));

                // Titles
                ctx.textAlign = 'center';
                ctx.fillText(type === 'GUYTON_RIGHT' ? "RA Pressure (mmHg)" : "LA Pressure (mmHg)", margin.left + innerWidth / 2, height - 5);
                ctx.save();
                ctx.translate(15, margin.top + innerHeight / 2);
                ctx.rotate(-Math.PI / 2);
                ctx.fillText("CO (L/min)", 0, 0);
                ctx.restore();

                instances.forEach(inst => {
                    const cfg = config[inst.id];
                    if (!cfg || !cfg.visible) return;
                    const phys = physicsRefs.current.get(inst.id);
                    if (!phys || phys.buffer.length < 10) return;
                    const p = phys.activeParams;

                    // Averages for Operating Point & Guyton Fixed Param (Other P)
                    const lastCycle = phys.buffer.slice(-Math.floor(60000/p.HR));
                    const meanPra = d3.mean(lastCycle, d => d.aux.Pra) || 0;
                    const meanPla = d3.mean(lastCycle, d => d.aux.Pla) || 0;
                    const meanP = type === 'GUYTON_RIGHT' ? meanPra : meanPla;

                    // CO Calculation (match Metrics)
                    const vols = lastCycle.map(d => d.y.Qlv);
                    const sv = (d3.max(vols)||0) - (d3.min(vols)||0);
                    const co = (sv * p.HR) / 1000.0;

                    // 1. Draw Guyton (Venous Return)
                    // CO = (SBV - C_s*Pra - C_p*Pla - Vch) / (Ws + Wp)
                    // For Right Panel: Plot CO vs Pra. Fix Pla = meanPla.
                    // For Left Panel: Plot CO vs Pla. Fix Pra = meanPra.

                    const { W_s, C_s, W_p, C_p } = getGuytonParams(p);
                    const W_t = W_s + W_p;
                    // SBV approx: Total Volume in system (Closed Loop)
                    // Note: In 0D sim, TotalVolume is conserved. 
                    // Equation: CO = (Vol_total - V_ch - C_other*P_other - C_x*P_x) / W_t ?
                    // Actually, simplify to: CO = (V_effective - C_x * P_x) / W_t
                    // Where V_effective = (Vol_total - V_ch - C_other * P_other_fixed)

                    const V_total = inst.targetVolume; 
                    const V_ch_mean = d3.mean(lastCycle, d => d.y.Qlv + d.y.Qla + d.y.Qrv + d.y.Qra) || 500;

                    const drawGuyton = () => {
                        ctx.beginPath();
                        ctx.strokeStyle = inst.color;
                        ctx.setLineDash([5, 5]);
                        ctx.lineWidth = 1.5;

                        // P range 0 to 20
                        const p1 = 0;
                        const p2 = 25; 

                        const calcCO = (px: number) => {
                            // Guyton Plane eq: CO * W_t = V_total - V_ch - C_s*Pra - C_p*Pla
                            let num = V_total - V_ch_mean;
                            if (type === 'GUYTON_RIGHT') {
                                // Variable is Pra (px), Fixed is Pla (meanPla)
                                num -= (C_s * px + C_p * meanPla);
                            } else {
                                // Variable is Pla (px), Fixed is Pra (meanPra)
                                num -= (C_s * meanPra + C_p * px);
                            }
                            return (num / W_t) * 60.0; // Conv mL/ms -> L/min
                        };

                        const co1 = calcCO(p1);
                        const co2 = calcCO(p2);

                        ctx.moveTo(xScale(p1), yScale(co1));
                        ctx.lineTo(xScale(p2), yScale(co2));
                        ctx.stroke();
                    };
                    drawGuyton();

                    // 2. Draw Starling (Cardiac Output)
                    const drawStarling = () => {
                        ctx.beginPath();
                        ctx.strokeStyle = inst.color;
                        ctx.setLineDash([]);
                        ctx.lineWidth = 2;

                        let Ees, alpha, beta, V0, Ea;

                        if (type === 'GUYTON_RIGHT') {
                            // RV Function (vs Pra)
                            Ees=p.RV_Ees; alpha=p.RV_alpha; beta=p.RV_beta; V0=p.RV_V0;
                            const R_pulm = p.Rap_prox + p.Rcp + p.Rap + p.Rvp;
                            Ea = R_pulm / (60000/p.HR);
                        } else {
                            // LV Function (vs Pla)
                            Ees=p.LV_Ees; alpha=p.LV_alpha; beta=p.LV_beta; V0=p.LV_V0;
                            const R_sys = p.Ras_prox + p.Rda + p.Ras + p.Rcs + p.Rvs;
                            Ea = R_sys / (60000/p.HR);
                        }

                        let first=true;
                        for(let px=0; px<=20; px+=0.5) {
                            const co_est = getStarlingCO(px, Ees, V0, alpha, beta, Ea, p.HR);
                            const x = xScale(px);
                            const y = yScale(co_est);
                            if(first) { ctx.moveTo(x,y); first=false; }
                            else ctx.lineTo(x,y);
                        }
                        ctx.stroke();
                    };
                    drawStarling();

                    // 3. Operating Point
                    ctx.beginPath();
                    ctx.fillStyle = inst.color;
                    ctx.arc(xScale(meanP), yScale(co), 4, 0, 2*Math.PI);
                    ctx.fill();
                    ctx.stroke();

                });

            } else {
                // -----------------------
                // 3D RENDERING
                // -----------------------
                // Axes: X=Pra (0-20), Z=Pla (0-25), Y=CO (0-15) (Y is up in 3D usually, but here let's map: X=Pra, Y=Pla, Z=CO vertical)

                // Isometric Projection Helper
                const iso = (x: number, y: number, z: number) => {
                    // x: Pra, y: Pla, z: CO
                    // Scale to normalized 0-1
                    const sx = x / 20;
                    const sy = y / 25;
                    const sz = z / 15;

                    // Simple ISO projection
                    const angle = Math.PI / 6; // 30 deg
                    const u = (sx - sy) * Math.cos(angle);
                    const v = (sx + sy) * Math.sin(angle) - sz;

                    // Map to Canvas
                    const scale = Math.min(width, height) * 0.5;
                    const cx = width / 2;
                    const cy = height * 0.75;

                    return { x: cx + u * scale, y: cy + v * scale };
                };

                // Draw Axes
                const origin = iso(0,0,0);
                const xEnd = iso(20,0,0);
                const yEnd = iso(0,25,0);
                const zEnd = iso(0,0,15);

                ctx.strokeStyle = '#64748b'; ctx.lineWidth=1;
                // Pra Axis
                ctx.beginPath(); ctx.moveTo(origin.x, origin.y); ctx.lineTo(xEnd.x, xEnd.y); ctx.stroke();
                ctx.fillStyle='#94a3b8'; ctx.textAlign='left'; ctx.fillText("Pra (CVP)", xEnd.x, xEnd.y);
                // Pla Axis
                ctx.beginPath(); ctx.moveTo(origin.x, origin.y); ctx.lineTo(yEnd.x, yEnd.y); ctx.stroke();
                ctx.textAlign='right'; ctx.fillText("Pla (PCWP)", yEnd.x, yEnd.y);
                // CO Axis
                ctx.beginPath(); ctx.moveTo(origin.x, origin.y); ctx.lineTo(zEnd.x, zEnd.y); ctx.stroke();
                ctx.textAlign='center'; ctx.fillText("CO", zEnd.x, zEnd.y - 10);

                // Draw Grid (Base)
                ctx.strokeStyle = '#334155'; ctx.lineWidth=0.5;
                for(let i=0; i<=20; i+=5) {
                    const p1 = iso(i, 0, 0); const p2 = iso(i, 25, 0);
                    ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
                }
                for(let i=0; i<=25; i+=5) {
                    const p1 = iso(0, i, 0); const p2 = iso(20, i, 0);
                    ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
                }

                instances.forEach(inst => {
                    const cfg = config[inst.id];
                    if (!cfg || !cfg.visible) return;
                    const phys = physicsRefs.current.get(inst.id);
                    if (!phys || phys.buffer.length < 10) return;
                    const p = phys.activeParams;

                    // Averages
                    const lastCycle = phys.buffer.slice(-Math.floor(60000/p.HR));
                    const meanPra = d3.mean(lastCycle, d => d.aux.Pra) || 0;
                    const meanPla = d3.mean(lastCycle, d => d.aux.Pla) || 0;
                    const vols = lastCycle.map(d => d.y.Qlv);
                    const sv = (d3.max(vols)||0) - (d3.min(vols)||0);
                    const meanCO = (sv * p.HR) / 1000.0;

                    // 1. Draw Starling Line (Intersection of RV and LV curves)
                    // The "Line" is the set of points (Pra, Pla, CO) where CO = RV(Pra) AND CO = LV(Pla)
                    // We generate points by stepping through CO
                    ctx.strokeStyle = inst.color;
                    ctx.lineWidth = 2;
                    ctx.beginPath();

                    let first = true;
                    // Step CO from 0 to max
                    for(let co=0.1; co<=15; co+=0.5) {
                        // Inverse Starling? Hard with Log.
                        // Easier: Step Pra, get CO_R, find Pla that gives same CO_L
                        // But strictly, Starling 3D is a line in space. 
                        // Let's just draw the "Operating Line" by varying Total Volume? No, that's complex.
                        // Let's draw the parametric curve: 
                        // x = t (Pra), z = RV(t) (CO), y = InverseLV(z) (Pla)

                        // We iterate Pra
                        // However, Pra and Pla are independent in 3D space unless coupled by the circuit.
                        // The "Starling Relation" describes a surface? No, independent ventricles mean 
                        // CO_R depends on Pra, CO_L depends on Pla.
                        // Equilibrium is CO_R = CO_L. This implies a relationship between Pra and Pla for the heart to be in steady state.
                        // This relationship is the "Cardiac Function Curve" in P-P-CO space?
                        // It's a line: (Pra, Pla(Pra), CO(Pra)).
                    }

                    // Let's draw the "Cardiac Function Line" (Steady State matching)
                    // Iterate Pra -> Get CO -> Solve Pla needed for that CO
                    // CO = k * ln((Pla+b)/b) -> Pla = b * (exp(CO/k) - 1)

                    // Pre-calc params
                    const R_sys = p.Ras_prox + p.Rda + p.Ras + p.Rcs + p.Rvs;
                    const Ea_L = R_sys / (60000/p.HR);
                    const k_L = (p.LV_Ees / (p.LV_Ees + Ea_L)) * (1.0 / p.LV_alpha);

                    const R_pulm = p.Rap_prox + p.Rcp + p.Rap + p.Rvp;
                    const Ea_R = R_pulm / (60000/p.HR);

                    ctx.beginPath();
                    first = true;
                    for (let pra = 0; pra <= 20; pra += 0.5) {
                        const co_est = getStarlingCO(pra, p.RV_Ees, p.RV_V0, p.RV_alpha, p.RV_beta, Ea_R, p.HR); // L/min
                        if (co_est <= 0.1 || co_est > 15) continue;

                        // Inverse LV to find Pla
                        // co = HR * k * ln(...)
                        // co / (HR * k) = ln(...)
                        // exp(...) = ...

                        if (k_L <= 0.001) continue;
                        const exponent = (co_est * 1000.0) / (p.HR * k_L); // careful with units (co_est L/min -> mL/min -> /HR = mL/beat)
                        // Wait, getStarlingCO returns L/min. Formula inside uses mL.
                        // Let's match units carefully. 
                        // function returns L/min. internal `sv_est` is mL.
                        // sv_est = co_est * 1000 / HR.

                        const sv_needed = co_est * 1000.0 / p.HR;
                        // sv = k_L * ln((Pla+b)/b)
                        // Pla = b * (exp(sv/k_L) - 1)

                        const pla = p.LV_beta * (Math.exp(sv_needed / k_L) - 1);

                        if (pla >= 0 && pla <= 25) {
                            const pt = iso(pra, pla, co_est);
                            if (first) { ctx.moveTo(pt.x, pt.y); first = false; }
                            else ctx.lineTo(pt.x, pt.y);
                        }
                    }
                    ctx.stroke(); // This is the "Cardiac Function Curve" in 3D

                    // 2. Draw Operating Point
                    const pt = iso(meanPra, meanPla, meanCO);
                    ctx.beginPath();
                    ctx.fillStyle = inst.color;
                    ctx.arc(pt.x, pt.y, 4, 0, 2*Math.PI);
                    ctx.fill(); ctx.stroke();

                    // 3. Drop lines
                    ctx.strokeStyle = inst.color; ctx.lineWidth=0.5; ctx.setLineDash([2,2]);
                    const base = iso(meanPra, meanPla, 0);
                    ctx.beginPath(); ctx.moveTo(pt.x, pt.y); ctx.lineTo(base.x, base.y); ctx.stroke(); // Vertical drop

                    const praAxis = iso(meanPra, 0, 0);
                    ctx.beginPath(); ctx.moveTo(base.x, base.y); ctx.lineTo(praAxis.x, praAxis.y); ctx.stroke();

                    const plaAxis = iso(0, meanPla, 0);
                    ctx.beginPath(); ctx.moveTo(base.x, base.y); ctx.lineTo(plaAxis.x, plaAxis.y); ctx.stroke();

                    ctx.setLineDash([]);
                });
            }

            animationFrameId = requestAnimationFrame(render);
        };
        render();
        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);
        return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
    }, [instances, config, type]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            <canvas ref={canvasRef} className="block" />
        </div>
    );
};

import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { SimInstance, PhysicsRefState, ChamberId, SignalType, PanelInstanceConfig, MetricType, PanelType, SimulationParams } from '../types';

interface ChartPanelProps {
  physicsRefs: React.MutableRefObject<Map<string, PhysicsRefState>>;
  instances: SimInstance[];
  config: PanelInstanceConfig;
  showGuides?: boolean;
}

interface WaveformProps extends ChartPanelProps {
    timeWindow: number; 
}

interface GuytonProps extends ChartPanelProps {
    type: 'GUYTON_RIGHT' | 'GUYTON_LEFT' | 'GUYTON_3D';
}

// Helper: Color logic
const getColor = (baseColor: string, signal: string, customColors?: { [key: string]: string }): string => {
    if (customColors && customColors[signal]) {
        return customColors[signal];
    }
    const c = d3.color(baseColor);
    if (!c) return baseColor;

    switch (signal) {
        // Waveform Signals
        case 'AoP': case 'PAP': case 'ABP':
            return c.brighter(1.5).formatHex(); 
        case 'Pla': case 'Pra': case 'CVP': case 'PCWP':
            return c.darker(1.2).formatHex();
        // PV Loop Chambers
        case 'LA': case 'RA':
             return c.darker(1.2).formatHex();
        default: return c.formatHex();
    }
};

// --------------------------------------------------------
// PV Loop Panel
// --------------------------------------------------------
export const PVLoopPanel: React.FC<ChartPanelProps> = ({ physicsRefs, instances, config, showGuides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const scaleRef = useRef({ maxV: 300, maxP: 200 });

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = containerRef.current.clientWidth;
    let height = containerRef.current.clientHeight;
    const dpr = window.devicePixelRatio || 1;

    const resize = () => {
        width = containerRef.current!.clientWidth;
        height = containerRef.current!.clientHeight;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
    };
    resize();

    const xScale = d3.scaleLinear().domain([0, 300]).range([50, width - 20]);
    const yScale = d3.scaleLinear().domain([0, 200]).range([height - 40, 20]);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // 1. Auto-scale calc
      let currentFrameMaxV = 0;
      let currentFrameMaxP = 0;
      let hasData = false;

      instances.forEach(inst => {
          const cfg = config[inst.id];
          if (!cfg || !cfg.visible || cfg.selectedSignals.length === 0) return;

          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;

          const data = physState.buffer.slice(-500); 
          for (let i = 0; i < data.length; i += 10) {
              const d = data[i];
              cfg.selectedSignals.forEach(chamber => {
                  let v = 0, p = 0;
                  switch(chamber) {
                      case 'LV': v = d.y.Qlv; p = d.aux.Plv; break;
                      case 'LA': v = d.y.Qla; p = d.aux.Pla; break;
                      case 'RV': v = d.y.Qrv; p = d.aux.Prv; break;
                      case 'RA': v = d.y.Qra; p = d.aux.Pra; break;
                  }
                  if (v > currentFrameMaxV) currentFrameMaxV = v;
                  if (p > currentFrameMaxP) currentFrameMaxP = p;
                  hasData = true;
              });
          }
      });

      if (hasData) {
          currentFrameMaxV *= 1.1; 
          currentFrameMaxP *= 1.1;
          // Smooth Lerp
          scaleRef.current.maxV = scaleRef.current.maxV * 0.9 + Math.max(150, Math.ceil(currentFrameMaxV / 50) * 50) * 0.1;
          scaleRef.current.maxP = scaleRef.current.maxP * 0.9 + Math.max(100, Math.ceil(currentFrameMaxP / 50) * 50) * 0.1;
      }

      xScale.domain([0, scaleRef.current.maxV]).range([50, width - 20]);
      yScale.domain([0, scaleRef.current.maxP]).range([height - 40, 20]);

      // 2. Draw Grid
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      xScale.ticks(6).forEach(t => { ctx.moveTo(xScale(t), height-40); ctx.lineTo(xScale(t), 20); });
      yScale.ticks(6).forEach(t => { ctx.moveTo(50, yScale(t)); ctx.lineTo(width-20, yScale(t)); });
      ctx.stroke();

      // Labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      xScale.ticks(6).forEach(t => ctx.fillText(t.toString(), xScale(t), height - 25));
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      yScale.ticks(6).forEach(t => ctx.fillText(t.toString(), 45, yScale(t)));

      // Titles
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Volume (mL)", width / 2, height - 10);
      ctx.save();
      ctx.translate(15, height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillText("Pressure (mmHg)", 0, 0);
      ctx.restore();

      // 3. Draw Data
      instances.forEach(inst => {
          const cfg = config[inst.id];
          if (!cfg || !cfg.visible) return;

          const physState = physicsRefs.current.get(inst.id);
          if (!physState || physState.buffer.length < 2) return;
          const loopData = physState.buffer.slice(-1200); 

          if (showGuides && cfg.selectedSignals.includes('LV')) {
              ctx.save();
              ctx.setLineDash([2, 4]);
              ctx.lineWidth = 1;
              ctx.globalAlpha = 0.5;
              ctx.strokeStyle = inst.color;
              const vMax = scaleRef.current.maxV;
              // ESPVR
              ctx.beginPath();
              ctx.moveTo(xScale(inst.params.LV_V0), yScale(0));
              ctx.lineTo(xScale(vMax), yScale(inst.params.LV_Ees * (vMax - inst.params.LV_V0)));
              ctx.stroke();
              // EDPVR
              ctx.beginPath();
              let firstPt = true;
              for (let v = Math.max(0, inst.params.LV_V0); v <= vMax; v += (vMax/50)) {
                  const ped = inst.params.LV_beta * (Math.exp(inst.params.LV_alpha * (v - inst.params.LV_V0)) - 1);
                  if (ped > scaleRef.current.maxP) break;
                  const px = xScale(v), py = yScale(ped);
                  if(firstPt) { ctx.moveTo(px,py); firstPt=false;} else ctx.lineTo(px,py);
              }
              ctx.stroke();
              ctx.restore();
          }

          const drawLoop = (c: string) => {
              ctx.beginPath();
              ctx.strokeStyle = getColor(inst.color, c, cfg.customColors);
              ctx.lineWidth = 2;
              const getPt = (d: any) => {
                  switch(c) {
                      case 'LV': return [d.y.Qlv, d.aux.Plv];
                      case 'LA': return [d.y.Qla, d.aux.Pla];
                      case 'RV': return [d.y.Qrv, d.aux.Prv];
                      case 'RA': return [d.y.Qra, d.aux.Pra];
                      default: return [0,0];
                  }
              };
              if(loopData.length === 0) return;
              const [sV, sP] = getPt(loopData[0]);
              ctx.moveTo(xScale(sV), yScale(sP));
              for(let i=1; i<loopData.length; i++) {
                  const [v, p] = getPt(loopData[i]);
                  ctx.lineTo(xScale(v), yScale(p));
              }
              ctx.stroke();
              const [eV, eP] = getPt(loopData[loopData.length-1]);
              ctx.beginPath();
              ctx.fillStyle = '#fff';
              ctx.arc(xScale(eV), yScale(eP), 3, 0, 2*Math.PI);
              ctx.fill();
          }
          cfg.selectedSignals.forEach(c => drawLoop(c));
      });
      animationFrameId = requestAnimationFrame(render);
    };
    render();
    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(containerRef.current);
    return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
  }, [instances, config, showGuides]);

  return (
      <div ref={containerRef} className="w-full h-full relative">
         <canvas ref={canvasRef} className="block" />
      </div>
  );
};

// --------------------------------------------------------
// Waveform Panel (With Auto-Scaling)
// --------------------------------------------------------
export const WaveformPanel: React.FC<WaveformProps> = ({ physicsRefs, instances, timeWindow, config }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const scaleRef = useRef({ yMin: 0, yMax: 160 });

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        const margin = { top: 10, right: 10, bottom: 20, left: 40 };

        let animationFrameId: number;
        const render = () => {
            const innerWidth = width - margin.left - margin.right;
            const innerHeight = height - margin.top - margin.bottom;
            const yScale = d3.scaleLinear().range([margin.top + innerHeight, margin.top]);

            ctx.clearRect(0, 0, width, height);

            let localMin = 1000;
            let localMax = -1000;
            let hasData = false;
            let maxT = 0;

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys) return;
                if(phys.t > maxT) maxT = phys.t;

                if (phys.buffer.length < 2) return;
                const startTime = phys.t - timeWindow;
                const visibleData = phys.buffer.filter(p => p.t > startTime);

                if (visibleData.length === 0) return;
                const step = Math.max(1, Math.floor(visibleData.length / 200));

                for (let i = 0; i < visibleData.length; i += step) {
                     const pt = visibleData[i];
                     cfg.selectedSignals.forEach(sig => {
                         let val = 0;
                         switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                         }
                         if (val < localMin) localMin = val;
                         if (val > localMax) localMax = val;
                         hasData = true;
                     });
                }
            });

            if (hasData) {
                const range = localMax - localMin;
                const pad = Math.max(10, range * 0.1);
                const targetMin = Math.max(0, localMin - pad);
                const targetMax = localMax + pad;
                scaleRef.current.yMin = scaleRef.current.yMin * 0.9 + targetMin * 0.1;
                scaleRef.current.yMax = scaleRef.current.yMax * 0.9 + targetMax * 0.1;
            } else {
                scaleRef.current.yMin = scaleRef.current.yMin * 0.95;
                scaleRef.current.yMax = scaleRef.current.yMax * 0.95 + 160 * 0.05;
            }

            yScale.domain([scaleRef.current.yMin, scaleRef.current.yMax]);

            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(margin.left, margin.top);
            ctx.lineTo(margin.left, margin.top + innerHeight);
            ctx.stroke();

            ctx.fillStyle = '#94a3b8';
            ctx.font = '10px sans-serif';
            ctx.textAlign = 'right';
            ctx.textBaseline = 'middle';
            yScale.ticks(5).forEach(t => {
                const y = yScale(t);
                ctx.beginPath();
                ctx.moveTo(margin.left, y);
                ctx.lineTo(margin.left - 5, y);
                ctx.stroke();
                ctx.fillText(t.toString(), margin.left - 8, y);

                ctx.save();
                ctx.strokeStyle = '#334155';
                ctx.globalAlpha = 0.2;
                ctx.beginPath();
                ctx.moveTo(margin.left, y);
                ctx.lineTo(width - margin.right, y);
                ctx.stroke();
                ctx.restore();
            });

            if (maxT === 0) { animationFrameId = requestAnimationFrame(render); return; }

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;

                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 2) return;
                const validData = phys.buffer.filter(p => p.t > phys.t - timeWindow - 100);

                const drawSig = (sig: SignalType) => {
                    ctx.beginPath();
                    ctx.strokeStyle = getColor(inst.color, sig, cfg.customColors);
                    ctx.lineWidth = 2;
                    let first = true; let prevX = -1;

                    ctx.save();
                    ctx.beginPath();
                    ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
                    ctx.clip();
                    ctx.beginPath();

                    for(let i=0; i<validData.length; i+=2) {
                        const pt = validData[i];
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }
                        const xRel = (pt.t % timeWindow) / timeWindow;
                        const x = margin.left + xRel * innerWidth;
                        const y = yScale(val);

                        if(first) { ctx.moveTo(x,y); first=false; }
                        else { 
                            if(x < prevX) { ctx.stroke(); ctx.beginPath(); ctx.moveTo(x,y); }
                            else ctx.lineTo(x,y); 
                        }
                        prevX = x;
                    }
                    ctx.stroke();
                    ctx.restore();
                };
                cfg.selectedSignals.forEach(s => drawSig(s as SignalType));

                if(phys.buffer.length>0) {
                    const pt = phys.buffer[phys.buffer.length-1];
                    const xRel = (pt.t % timeWindow) / timeWindow;
                    const x = margin.left + xRel * innerWidth;

                    const drawHead = (sig: SignalType) => {
                        let val = 0;
                        switch(sig) {
                            case 'Plv': val = pt.aux.Plv; break;
                            case 'Pla': val = pt.aux.Pla; break;
                            case 'Prv': val = pt.aux.Prv; break;
                            case 'Pra': val = pt.aux.Pra; break;
                            case 'AoP': val = pt.aux.AoP; break;
                            case 'PAP': val = pt.aux.PAP; break;
                        }
                        ctx.beginPath();
                        ctx.fillStyle = getColor(inst.color, sig, cfg.customColors);
                        ctx.arc(x, yScale(val), 4, 0, 2*Math.PI);
                        ctx.fill();
                        ctx.strokeStyle='#fff'; ctx.lineWidth=1; ctx.stroke();
                    };
                    cfg.selectedSignals.forEach(s => drawHead(s as SignalType));
                }
            });

            const xRelCursor = (maxT % timeWindow) / timeWindow;
            const cursorX = margin.left + xRelCursor * innerWidth;
            const eraseWidth = (300 / timeWindow) * innerWidth; 

            ctx.save();
            ctx.beginPath();
            ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
            ctx.clip();
            ctx.clearRect(cursorX, margin.top, eraseWidth, innerHeight);
            if (cursorX + eraseWidth > width) {
                const remainder = (cursorX + eraseWidth) - (margin.left + innerWidth);
                if (remainder > 0) ctx.clearRect(margin.left, margin.top, remainder, innerHeight);
            }
            ctx.restore();

            animationFrameId = requestAnimationFrame(render);
        };
        render();
        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);
        return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
    }, [instances, timeWindow, config]);

    return (
        <div className="flex flex-col h-full w-full relative group">
            <div ref={containerRef} className="flex-1 w-full min-h-0 relative">
                <canvas ref={canvasRef} className="block relative z-10" />
            </div>
            <div className="absolute top-2 right-2 pointer-events-none z-20 opacity-50 text-[10px] text-slate-400">
                Window: {timeWindow/1000}s
            </div>
        </div>
    );
};

// --------------------------------------------------------
// Metrics Panel
// --------------------------------------------------------
export const MetricsPanel: React.FC<ChartPanelProps> = ({ physicsRefs, instances, config }) => {
    // We update metrics every 500ms to avoid UI flickering
    const [metricsData, setMetricsData] = useState<{[key:string]: {[key:string]: string}}>({});

    useEffect(() => {
        const interval = setInterval(() => {
            const nextData: any = {};

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible || cfg.selectedSignals.length === 0) return;

                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 100) return;

                const activeHR = phys.activeParams.HR;
                const cycleMs = 60000 / activeHR;

                // Get data for last cardiac cycle + buffer
                const endTime = phys.t;
                const startTime = endTime - cycleMs;
                const cycleData = phys.buffer.filter(d => d.t >= startTime);

                if (cycleData.length < 10) return;

                const calcMetrics: {[key:string]: string} = {};

                // Helpers
                const getArr = (fn: (d:any)=>number) => cycleData.map(fn);
                const max = (arr: number[]) => Math.max(...arr);
                const min = (arr: number[]) => Math.min(...arr);
                const mean = (arr: number[]) => arr.reduce((a,b)=>a+b,0)/arr.length;

                // 1. AoP (Sys/Dia)
                if (cfg.selectedSignals.includes('ABP')) {
                    const vals = getArr(d => d.aux.AoP);
                    calcMetrics['ABP'] = `${max(vals).toFixed(0)} / ${min(vals).toFixed(0)} mmHg`;
                }
                // 2. PAP (Sys/Dia)
                if (cfg.selectedSignals.includes('PAP')) {
                    const vals = getArr(d => d.aux.PAP);
                    calcMetrics['PAP'] = `${max(vals).toFixed(0)} / ${min(vals).toFixed(0)} mmHg`;
                }
                // 3. CVP (Mean Pra)
                if (cfg.selectedSignals.includes('CVP')) {
                    const vals = getArr(d => d.aux.Pra);
                    calcMetrics['CVP'] = `${mean(vals).toFixed(1)} mmHg`;
                }
                // 4. PCWP (Mean Pla)
                if (cfg.selectedSignals.includes('PCWP')) {
                    const vals = getArr(d => d.aux.Pla);
                    calcMetrics['PCWP'] = `${mean(vals).toFixed(1)} mmHg`;
                }
                // 5. SV (Max - Min LV Volume)
                const lvVols = getArr(d => d.y.Qlv);
                const sv = max(lvVols) - min(lvVols);
                if (cfg.selectedSignals.includes('SV')) {
                    calcMetrics['SV'] = `${sv.toFixed(1)} mL`;
                }
                // 6. CO
                if (cfg.selectedSignals.includes('CO')) {
                    const co = (sv * activeHR) / 1000;
                    calcMetrics['CO'] = `${co.toFixed(2)} L/min`;
                }
                // 7. Ea (Effective Arterial Elastance) approx ESP/SV
                // ESP approx max Plv.
                if (cfg.selectedSignals.includes('Ea_LV')) {
                   const plvVals = getArr(d => d.aux.Plv);
                   const esp = max(plvVals);
                   const ea = sv > 0 ? esp / sv : 0;
                   calcMetrics['Ea_LV'] = `${ea.toFixed(2)} mmHg/mL`;
                }

                nextData[inst.id] = calcMetrics;
            });
            setMetricsData(nextData);

        }, 200);
        return () => clearInterval(interval);
    }, [instances, config]);

    return (
        <div className="w-full h-full p-2 overflow-y-auto custom-scrollbar">
            {instances.map(inst => {
                const cfg = config[inst.id];
                const data = metricsData[inst.id];
                if (!cfg || !cfg.visible || !data) return null;

                return (
                    <div key={inst.id} className="mb-4 bg-slate-900/50 rounded border border-slate-800 p-2">
                         <div className="flex items-center gap-2 mb-2 border-b border-slate-700 pb-1">
                            <span className="w-2 h-2 rounded-full" style={{backgroundColor: inst.color}}></span>
                            <span className="text-xs font-bold text-slate-300">{inst.name}</span>
                         </div>
                         <div className="grid grid-cols-2 gap-2">
                             {cfg.selectedSignals.map(sig => (
                                 data[sig] ? (
                                     <div key={sig} className="flex flex-col bg-slate-950/50 p-1.5 rounded">
                                         <span className="text-[10px] text-slate-500 uppercase font-bold">{sig}</span>
                                         <span className="text-sm font-mono text-slate-200">{data[sig]}</span>
                                     </div>
                                 ) : null
                             ))}
                         </div>
                    </div>
                )
            })}
        </div>
    );
}

// --------------------------------------------------------
// Guyton & Starling Panel (2D and 3D)
// --------------------------------------------------------
export const GuytonPanel: React.FC<GuytonProps> = ({ physicsRefs, instances, config, type }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    // Scaling state to smooth transitions
    const scaleRef = useRef({
        maxPra: 20,
        maxPla: 25,
        maxCO: 15
    });

    // Calc helpers based on resistance chains for Guyton
    const getGuytonParams = (p: SimulationParams) => {
        // Systemic W calculation based on resistance chain
        const W_s = 
            p.Cas_prox * (p.Rda + p.Ras + p.Rcs + p.Rvs) +
            p.Cda * (p.Ras + p.Rcs + p.Rvs) +
            p.Cas * (p.Rcs + p.Rvs) +
            p.Cvs * (p.Rvs);
        const C_s = p.Cas_prox + p.Cda + p.Cas + p.Cvs;

        // Pulmonary W
        const W_p = 
            p.Cap_prox * (p.Rcp + p.Rap + p.Rvp) +
            p.Cap * (p.Rap + p.Rvp) +
            p.Cvp * (p.Rvp);
        const C_p = p.Cap_prox + p.Cap + p.Cvp;

        return { W_s, C_s, W_p, C_p };
    };

    const getStarlingCO = (P_ed: number, Ees: number, V0: number, alpha: number, beta: number, Ea: number, HR: number) => {
        if (P_ed < 0) return 0;
        const term = (Ees / (Ees + Ea)) * (1.0 / alpha) * Math.log((P_ed + beta) / beta);
        const sv_est = Math.max(0, term); 
        return (sv_est * HR) / 1000.0; // L/min
    };

    useEffect(() => {
        if (!containerRef.current || !canvasRef.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = containerRef.current.clientWidth;
        let height = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        const resize = () => {
            width = containerRef.current!.clientWidth;
            height = containerRef.current!.clientHeight;
            canvas.width = width * dpr;
            canvas.height = height * dpr;
            ctx.scale(dpr, dpr);
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
        };
        resize();

        let animationFrameId: number;

        const render = () => {
            ctx.clearRect(0, 0, width, height);

            // Common setup
            const margin = { top: 20, right: 20, bottom: 30, left: 40 };
            const innerWidth = width - margin.left - margin.right;
            const innerHeight = height - margin.top - margin.bottom;

            // 1. Auto-scaling Logic
            let maxPraFound = 10;
            let maxPlaFound = 10;
            let maxCOFound = 5;

            instances.forEach(inst => {
                const cfg = config[inst.id];
                if (!cfg || !cfg.visible) return;
                const phys = physicsRefs.current.get(inst.id);
                if (!phys || phys.buffer.length < 10) return;
                const p = phys.activeParams;

                const lastCycle = phys.buffer.slice(-Math.floor(60000/p.HR));
                const meanPra = d3.mean(lastCycle, d => d.aux.Pra) || 0;
                const meanPla = d3.mean(lastCycle, d => d.aux.Pla) || 0;
                const vols = lastCycle.map(d => d.y.Qlv);
                const sv = (d3.max(vols)||0) - (d3.min(vols)||0);
                const meanCO = (sv * p.HR) / 1000.0;

                if (meanPra > maxPraFound) maxPraFound = meanPra;
                if (meanPla > maxPlaFound) maxPlaFound = meanPla;
                if (meanCO > maxCOFound) maxCOFound = meanCO;
            });

            // Target limits with padding (e.g., +30%)
            const targetMaxPra = Math.max(20, maxPraFound * 1.3);
            const targetMaxPla = Math.max(25, maxPlaFound * 1.3);
            const targetMaxCO = Math.max(15, maxCOFound * 1.3);

            // Smooth Lerp
            scaleRef.current.maxPra = scaleRef.current.maxPra * 0.9 + targetMaxPra * 0.1;
            scaleRef.current.maxPla = scaleRef.current.maxPla * 0.9 + targetMaxPla * 0.1;
            scaleRef.current.maxCO = scaleRef.current.maxCO * 0.9 + targetMaxCO * 0.1;

            const { maxPra, maxPla, maxCO } = scaleRef.current;


            if (type !== 'GUYTON_3D') {
                // -----------------------
                // 2D RENDERING
                // -----------------------

                const xMax = type === 'GUYTON_RIGHT' ? maxPra : maxPla;
                const xScale = d3.scaleLinear().domain([0, xMax]).range([margin.left, margin.left + innerWidth]);
                const yScale = d3.scaleLinear().domain([0, maxCO]).range([margin.top + innerHeight, margin.top]);

                // Grid
                ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;
                ctx.beginPath();
                xScale.ticks(6).forEach(t => { ctx.moveTo(xScale(t), margin.top + innerHeight); ctx.lineTo(xScale(t), margin.top); });
                yScale.ticks(6).forEach(t => { ctx.moveTo(margin.left, yScale(t)); ctx.lineTo(margin.left + innerWidth, yScale(t)); });
                ctx.stroke();

                // Labels
                ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif';
                ctx.textAlign = 'center';
                xScale.ticks(6).forEach(t => ctx.fillText(t.toString(), xScale(t), margin.top + innerHeight + 15));
                ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
                yScale.ticks(6).forEach(t => ctx.fillText(t.toString(), margin.left - 5, yScale(t)));

                // Titles
                ctx.textAlign = 'center';
                ctx.fillText(type === 'GUYTON_RIGHT' ? "RA Pressure (mmHg)" : "LA Pressure (mmHg)", margin.left + innerWidth / 2, height - 5);
                ctx.save();
                ctx.translate(15, margin.top + innerHeight / 2);
                ctx.rotate(-Math.PI / 2);
                ctx.fillText("CO (L/min)", 0, 0);
                ctx.restore();

                instances.forEach(inst => {
                    const cfg = config[inst.id];
                    if (!cfg || !cfg.visible) return;
                    const phys = physicsRefs.current.get(inst.id);
                    if (!phys || phys.buffer.length < 10) return;
                    const p = phys.activeParams;

                    const lastCycle = phys.buffer.slice(-Math.floor(60000/p.HR));
                    const meanPra = d3.mean(lastCycle, d => d.aux.Pra) || 0;
                    const meanPla = d3.mean(lastCycle, d => d.aux.Pla) || 0;
                    const meanP = type === 'GUYTON_RIGHT' ? meanPra : meanPla;

                    const vols = lastCycle.map(d => d.y.Qlv);
                    const sv = (d3.max(vols)||0) - (d3.min(vols)||0);
                    const co = (sv * p.HR) / 1000.0;

                    // 1. Draw Guyton
                    const { W_s, C_s, W_p, C_p } = getGuytonParams(p);
                    const W_t = W_s + W_p;

                    const V_total = inst.targetVolume; 
                    const V_ch_mean = d3.mean(lastCycle, d => d.y.Qlv + d.y.Qla + d.y.Qrv + d.y.Qra) || 500;

                    const drawGuyton = () => {
                        ctx.beginPath();
                        ctx.strokeStyle = inst.color;
                        ctx.setLineDash([5, 5]);
                        ctx.lineWidth = 1.5;

                        const p1 = 0;
                        const p2 = xMax; 

                        const calcCO = (px: number) => {
                            let num = V_total - V_ch_mean;
                            if (type === 'GUYTON_RIGHT') {
                                num -= (C_s * px + C_p * meanPla);
                            } else {
                                num -= (C_s * meanPra + C_p * px);
                            }
                            return (num / W_t) * 60.0; // Conv mL/ms -> L/min
                        };

                        const co1 = calcCO(p1);
                        const co2 = calcCO(p2);

                        ctx.moveTo(xScale(p1), yScale(co1));
                        ctx.lineTo(xScale(p2), yScale(co2));
                        ctx.stroke();
                    };
                    drawGuyton();

                    // 2. Draw Starling
                    const drawStarling = () => {
                        ctx.beginPath();
                        ctx.strokeStyle = inst.color;
                        ctx.setLineDash([]);
                        ctx.lineWidth = 2;

                        let Ees, alpha, beta, V0, Ea;

                        if (type === 'GUYTON_RIGHT') {
                            Ees=p.RV_Ees; alpha=p.RV_alpha; beta=p.RV_beta; V0=p.RV_V0;
                            const R_pulm = p.Rap_prox + p.Rcp + p.Rap + p.Rvp;
                            Ea = R_pulm / (60000/p.HR);
                        } else {
                            Ees=p.LV_Ees; alpha=p.LV_alpha; beta=p.LV_beta; V0=p.LV_V0;
                            const R_sys = p.Ras_prox + p.Rda + p.Ras + p.Rcs + p.Rvs;
                            Ea = R_sys / (60000/p.HR);
                        }

                        let first=true;
                        for(let px=0; px<=xMax; px+= (xMax/40)) {
                            const co_est = getStarlingCO(px, Ees, V0, alpha, beta, Ea, p.HR);
                            const x = xScale(px);
                            const y = yScale(co_est);
                            if (y >= margin.top && y <= margin.top + innerHeight) {
                                if(first) { ctx.moveTo(x,y); first=false; }
                                else ctx.lineTo(x,y);
                            }
                        }
                        ctx.stroke();
                    };
                    drawStarling();

                    // 3. Operating Point
                    ctx.beginPath();
                    ctx.fillStyle = inst.color;
                    ctx.arc(xScale(meanP), yScale(co), 4, 0, 2*Math.PI);
                    ctx.fill();
                    ctx.stroke();

                });

            } else {
                // -----------------------
                // 3D RENDERING
                // -----------------------

                // Isometric Projection Helper (Normalized by Max Limits)
                const iso = (x: number, y: number, z: number) => {
                    const sx = x / maxPra;
                    const sy = y / maxPla;
                    const sz = z / maxCO;

                    const angle = Math.PI / 6; // 30 deg
                    const u = (sx - sy) * Math.cos(angle);
                    const v = (sx + sy) * Math.sin(angle) - sz;

                    const scale = Math.min(width, height) * 0.5;
                    const cx = width / 2;
                    const cy = height * 0.75;

                    return { x: cx + u * scale, y: cy + v * scale };
                };

                // Draw Axes
                const origin = iso(0,0,0);
                const xEnd = iso(maxPra,0,0);
                const yEnd = iso(0,maxPla,0);
                const zEnd = iso(0,0,maxCO);

                ctx.strokeStyle = '#64748b'; ctx.lineWidth=1;
                // Pra Axis
                ctx.beginPath(); ctx.moveTo(origin.x, origin.y); ctx.lineTo(xEnd.x, xEnd.y); ctx.stroke();
                ctx.fillStyle='#94a3b8'; ctx.textAlign='left'; ctx.fillText(`Pra (0-${maxPra.toFixed(0)})`, xEnd.x, xEnd.y);
                // Pla Axis
                ctx.beginPath(); ctx.moveTo(origin.x, origin.y); ctx.lineTo(yEnd.x, yEnd.y); ctx.stroke();
                ctx.textAlign='right'; ctx.fillText(`Pla (0-${maxPla.toFixed(0)})`, yEnd.x, yEnd.y);
                // CO Axis
                ctx.beginPath(); ctx.moveTo(origin.x, origin.y); ctx.lineTo(zEnd.x, zEnd.y); ctx.stroke();
                ctx.textAlign='center'; ctx.fillText(`CO (0-${maxCO.toFixed(0)})`, zEnd.x, zEnd.y - 10);

                // Draw Grid (Base)
                const steps = 5;
                ctx.strokeStyle = '#334155'; ctx.lineWidth=0.5;

                // Lines along X (Pra) varying Y (Pla)
                for(let i=0; i<=steps; i++) {
                    const val = (i/steps) * maxPra;
                    const p1 = iso(val, 0, 0); 
                    const p2 = iso(val, maxPla, 0);
                    ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
                }
                // Lines along Y (Pla) varying X (Pra)
                for(let i=0; i<=steps; i++) {
                    const val = (i/steps) * maxPla;
                    const p1 = iso(0, val, 0); 
                    const p2 = iso(maxPra, val, 0);
                    ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
                }

                instances.forEach(inst => {
                    const cfg = config[inst.id];
                    if (!cfg || !cfg.visible) return;
                    const phys = physicsRefs.current.get(inst.id);
                    if (!phys || phys.buffer.length < 10) return;
                    const p = phys.activeParams;

                    // Averages
                    const lastCycle = phys.buffer.slice(-Math.floor(60000/p.HR));
                    const meanPra = d3.mean(lastCycle, d => d.aux.Pra) || 0;
                    const meanPla = d3.mean(lastCycle, d => d.aux.Pla) || 0;
                    const vols = lastCycle.map(d => d.y.Qlv);
                    const sv = (d3.max(vols)||0) - (d3.min(vols)||0);
                    const meanCO = (sv * p.HR) / 1000.0;

                    // 1. Draw Starling Line (Cardiac Function Curve in 3D)
                    // Iterate Pra -> Get CO -> Solve Pla needed for that CO

                    const R_sys = p.Ras_prox + p.Rda + p.Ras + p.Rcs + p.Rvs;
                    const Ea_L = R_sys / (60000/p.HR);
                    const k_L = (p.LV_Ees / (p.LV_Ees + Ea_L)) * (1.0 / p.LV_alpha);

                    const R_pulm = p.Rap_prox + p.Rcp + p.Rap + p.Rvp;
                    const Ea_R = R_pulm / (60000/p.HR);

                    ctx.strokeStyle = inst.color;
                    ctx.lineWidth = 2;
                    ctx.beginPath();

                    let first = true;
                    // Draw continuous curve
                    for (let pra = 0; pra <= maxPra; pra += (maxPra/40)) {
                        const co_est = getStarlingCO(pra, p.RV_Ees, p.RV_V0, p.RV_alpha, p.RV_beta, Ea_R, p.HR); // L/min
                        if (co_est <= 0.01 || co_est > maxCO) continue;

                        // Inverse LV to find Pla
                        if (k_L <= 0.001) continue;
                        const sv_needed = co_est * 1000.0 / p.HR;
                        // Pla = b * (exp(sv/k_L) - 1)
                        const pla = p.LV_beta * (Math.exp(sv_needed / k_L) - 1);

                        if (pla >= 0 && pla <= maxPla) {
                            const pt = iso(pra, pla, co_est);
                            if (first) { ctx.moveTo(pt.x, pt.y); first = false; }
                            else ctx.lineTo(pt.x, pt.y);
                        }
                    }
                    ctx.stroke();

                    // 2. Draw Operating Point
                    const pt = iso(meanPra, meanPla, meanCO);
                    ctx.beginPath();
                    ctx.fillStyle = inst.color;
                    ctx.arc(pt.x, pt.y, 4, 0, 2*Math.PI);
                    ctx.fill(); ctx.stroke();

                    // 3. Drop lines
                    ctx.strokeStyle = inst.color; ctx.lineWidth=0.5; ctx.setLineDash([2,2]);
                    const base = iso(meanPra, meanPla, 0);
                    ctx.beginPath(); ctx.moveTo(pt.x, pt.y); ctx.lineTo(base.x, base.y); ctx.stroke(); // Vertical drop

                    const praAxis = iso(meanPra, 0, 0);
                    ctx.beginPath(); ctx.moveTo(base.x, base.y); ctx.lineTo(praAxis.x, praAxis.y); ctx.stroke();

                    const plaAxis = iso(0, meanPla, 0);
                    ctx.beginPath(); ctx.moveTo(base.x, base.y); ctx.lineTo(plaAxis.x, plaAxis.y); ctx.stroke();

                    ctx.setLineDash([]);
                });
            }

            animationFrameId = requestAnimationFrame(render);
        };
        render();
        const resizeObserver = new ResizeObserver(resize);
        resizeObserver.observe(containerRef.current);
        return () => { cancelAnimationFrame(animationFrameId); resizeObserver.disconnect(); }
    }, [instances, config, type]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            <canvas ref={canvasRef} className="block" />
        </div>
    );
};

import React, { useState } from 'react';
import { SimulationParams, SimInstance, PanelType } from '../types';

interface ControlsProps {
  instances: SimInstance[];
  activeInstanceId: string;
  setActiveInstanceId: (id: string) => void;
  updateInstanceParams: (id: string, params: Partial<SimulationParams>) => void;
  updateInstanceVolume: (id: string, vol: number) => void;
  updateInstanceColor: (id: string, color: string) => void;
  addInstance: () => void;
  removeInstance: (id: string) => void;

  timeScale: number;
  setTimeScale: (v: number) => void;
  isPlaying: boolean;
  togglePlay: () => void;

  addPanel: (type: PanelType) => void;
}

const Slider = ({ label, value, min, max, step, onChange, unit }: { label: string, value: number, min: number, max: number, step: number, onChange: (val: number) => void, unit?: string }) => (
  <div className="mb-3">
    <div className="flex justify-between text-xs text-slate-400 mb-1">
      <span>{label}</span>
      <span>{value.toFixed(2)} {unit}</span>
    </div>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={(e) => onChange(parseFloat(e.target.value))}
      className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500 hover:accent-blue-400"
    />
  </div>
);

const GroupHeader = ({ title, isOpen, toggle }: { title: string, isOpen: boolean, toggle: () => void }) => (
    <div 
        onClick={toggle}
        className="flex justify-between items-center cursor-pointer bg-slate-800 p-2 rounded mt-2 hover:bg-slate-700 transition-colors"
    >
        <span className="text-xs font-bold text-slate-200 uppercase">{title}</span>
        <span className="text-xs text-slate-400">{isOpen ? '▼' : '▶'}</span>
    </div>
);

export const Controls: React.FC<ControlsProps> = ({ 
    instances, activeInstanceId, setActiveInstanceId, updateInstanceParams, updateInstanceVolume, updateInstanceColor, addInstance, removeInstance,
    timeScale, setTimeScale, isPlaying, togglePlay,
    addPanel
}) => {

  const activeInstance = instances.find(i => i.id === activeInstanceId) || instances[0];
  const params = activeInstance?.params;

  // Tab State
  const [openGroups, setOpenGroups] = useState<{ [key: string]: boolean }>({
      general: true,
      lv: true,
      sys: false,
      rv: false,
      pulm: false,
      la: false,
      ra: false
  });

  const toggleGroup = (key: string) => setOpenGroups(prev => ({ ...prev, [key]: !prev[key] }));

  const update = (key: keyof SimulationParams, val: number) => {
      if (activeInstance) {
        updateInstanceParams(activeInstance.id, { [key]: val });
      }
  };

  // Helper for Macro Sliders
  // Systemic R components: Ras, Rcs, Rvs, Ras_prox, Rda
  const getSystemicR = () => params.Ras + params.Rcs + params.Rvs + params.Ras_prox + params.Rda;
  const setSystemicR = (newTotal: number) => {
      const currentTotal = getSystemicR();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Ras: params.Ras * ratio,
          Rcs: params.Rcs * ratio,
          Rvs: params.Rvs * ratio,
          Ras_prox: params.Ras_prox * ratio,
          Rda: params.Rda * ratio
      });
  };

  // Systemic C components: Cas, Cvs, Cas_prox, Cda
  const getSystemicC = () => params.Cas + params.Cvs + params.Cas_prox + params.Cda;
  const setSystemicC = (newTotal: number) => {
      const currentTotal = getSystemicC();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Cas: params.Cas * ratio,
          Cvs: params.Cvs * ratio,
          Cas_prox: params.Cas_prox * ratio,
          Cda: params.Cda * ratio
      });
  };

  // Pulmonary R: Rap, Rvp, Rap_prox, Rcp
  const getPulmR = () => params.Rap + params.Rvp + params.Rap_prox + params.Rcp;
  const setPulmR = (newTotal: number) => {
      const currentTotal = getPulmR();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Rap: params.Rap * ratio,
          Rvp: params.Rvp * ratio,
          Rap_prox: params.Rap_prox * ratio,
          Rcp: params.Rcp * ratio
      });
  };

  // Pulmonary C: Cap, Cvp, Cap_prox
  const getPulmC = () => params.Cap + params.Cvp + params.Cap_prox;
  const setPulmC = (newTotal: number) => {
      const currentTotal = getPulmC();
      if(currentTotal === 0) return;
      const ratio = newTotal / currentTotal;
      updateInstanceParams(activeInstance.id, {
          Cap: params.Cap * ratio,
          Cvp: params.Cvp * ratio,
          Cap_prox: params.Cap_prox * ratio
      });
  };


  return (
    <div className="space-y-6 pb-20">

      {/* Simulation Control */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
        <h3 className="text-sm font-bold text-slate-100 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Global Physics</h3>

        <div className="mb-4 flex items-center gap-2">
            <button 
                onClick={togglePlay}
                className={`flex-1 py-2 rounded font-bold text-sm transition-colors ${isPlaying ? 'bg-amber-600 hover:bg-amber-500 text-white' : 'bg-emerald-600 hover:bg-emerald-500 text-white'}`}
            >
                {isPlaying ? 'PAUSE' : 'PLAY'}
            </button>
        </div>

        <div className="mb-4">
             <div className="flex justify-between text-xs text-slate-400 mb-1">
                <span>Sim Speed</span>
                <span>{timeScale.toFixed(1)}x</span>
            </div>
            <input
                type="range"
                min={0.1}
                max={2.0}
                step={0.1}
                value={timeScale}
                onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
            />
        </div>
      </div>

      {/* Dashboard Layout */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
         <h3 className="text-sm font-bold text-slate-100 uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">Layout</h3>
         <div className="grid grid-cols-2 gap-2">
            <button onClick={() => addPanel('PVLOOP')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + PV Loop
            </button>
            <button onClick={() => addPanel('WAVEFORM')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + Waveform
            </button>
            <button onClick={() => addPanel('GUYTON_RIGHT')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + Guyton (Right)
            </button>
            <button onClick={() => addPanel('GUYTON_LEFT')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center">
               + Guyton (Left)
            </button>
            <button onClick={() => addPanel('GUYTON_3D')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center col-span-2">
               + Guyton 3D (Bi-V)
            </button>
            <button onClick={() => addPanel('METRICS')} className="p-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-700 text-[10px] font-bold text-slate-300 text-center col-span-2">
               + Metrics
            </button>
         </div>
      </div>

      {/* Instances Management */}
      <div className="p-4 bg-slate-900 rounded-xl border border-slate-800">
          <div className="flex justify-between items-center mb-2 border-b border-slate-800 pb-2">
            <h3 className="text-sm font-bold text-white uppercase tracking-wider">Models</h3>
            <button onClick={addInstance} className="text-xs bg-indigo-600 hover:bg-indigo-500 px-2 py-1 rounded text-white">+ Duplicate</button>
          </div>
          <div className="space-y-2">
              {instances.map(inst => (
                  <div 
                    key={inst.id} 
                    className={`flex items-center justify-between p-2 rounded cursor-pointer border ${activeInstanceId === inst.id ? 'bg-slate-800 border-indigo-500/50' : 'bg-slate-950 border-slate-800 hover:border-slate-700'}`}
                    onClick={() => setActiveInstanceId(inst.id)}
                  >
                      <div className="flex items-center gap-2">
                          <input 
                            type="color" 
                            value={inst.color}
                            onChange={(e) => updateInstanceColor(inst.id, e.target.value)}
                            className="w-4 h-4 rounded overflow-hidden border-none p-0 cursor-pointer"
                          />
                          <span className="text-xs font-semibold text-slate-200">{inst.name}</span>
                      </div>
                      <div className="flex items-center gap-2">
                          {instances.length > 1 && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); removeInstance(inst.id); }}
                                className="text-slate-500 hover:text-red-400 px-1"
                            >
                                ✕
                            </button>
                          )}
                      </div>
                  </div>
              ))}
          </div>
      </div>

      {/* Params for Active Instance */}
      {params && (
          <div className="p-4 bg-slate-900 rounded-xl border border-slate-800 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-1 h-full" style={{ backgroundColor: activeInstance.color }}></div>
                <h3 className="text-sm font-bold text-white uppercase tracking-wider mb-4 border-b border-slate-800 pb-2">
                    {activeInstance.name} Config
                </h3>

                {/* General Group */}
                <GroupHeader title="General" isOpen={openGroups.general} toggle={() => toggleGroup('general')} />
                {openGroups.general && (
                    <div className="mt-3 pl-1 border-l-2 border-slate-700">
                        <Slider label="Heart Rate" value={params.HR} min={30} max={200} step={1} onChange={(v) => update('HR', v)} unit="bpm" />
                        <Slider label="Total Volume" value={activeInstance.targetVolume} min={1000} max={8000} step={50} onChange={(v) => updateInstanceVolume(activeInstance.id, v)} unit="mL" />
                    </div>
                )}

                {/* Left Ventricle */}
                <GroupHeader title="Left Ventricle" isOpen={openGroups.lv} toggle={() => toggleGroup('lv')} />
                {openGroups.lv && (
                    <div className="mt-3 pl-1 border-l-2 border-purple-500/30">
                        <Slider label="Ees (Contractility)" value={params.LV_Ees} min={0.5} max={10.0} step={0.1} onChange={(v) => update('LV_Ees', v)} unit="mmHg/mL" />
                        <Slider label="V0 (Unstressed Vol)" value={params.LV_V0} min={-50} max={100} step={5} onChange={(v) => update('LV_V0', v)} unit="mL" />
                        <Slider label="Alpha (Stiffness)" value={params.LV_alpha} min={0.01} max={0.1} step={0.001} onChange={(v) => update('LV_alpha', v)} unit="/mL" />
                        <Slider label="Beta (EDP Scale)" value={params.LV_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('LV_beta', v)} unit="mmHg" />
                        <Slider label="Tau (Relaxation)" value={params.LV_tau} min={10} max={100} step={1} onChange={(v) => update('LV_tau', v)} unit="ms" />
                    </div>
                )}

                {/* Systemic */}
                <GroupHeader title="Systemic Circulation" isOpen={openGroups.sys} toggle={() => toggleGroup('sys')} />
                {openGroups.sys && (
                    <div className="mt-3 pl-1 border-l-2 border-blue-500/30">
                        {/* Default ~900 */}
                        <Slider label="Total Resistance" value={getSystemicR()} min={100} max={3000} step={50} onChange={setSystemicR} unit="R" />
                        {/* Default ~73 */}
                        <Slider label="Total Compliance" value={getSystemicC()} min={10} max={200} step={1} onChange={setSystemicC} unit="mL/mmHg" />
                    </div>
                )}

                 {/* Right Ventricle */}
                <GroupHeader title="Right Ventricle" isOpen={openGroups.rv} toggle={() => toggleGroup('rv')} />
                {openGroups.rv && (
                    <div className="mt-3 pl-1 border-l-2 border-teal-500/30">
                        <Slider label="Ees (Contractility)" value={params.RV_Ees} min={0.1} max={5.0} step={0.1} onChange={(v) => update('RV_Ees', v)} unit="mmHg/mL" />
                        <Slider label="V0 (Unstressed Vol)" value={params.RV_V0} min={-50} max={100} step={5} onChange={(v) => update('RV_V0', v)} unit="mL" />
                        <Slider label="Alpha (Stiffness)" value={params.RV_alpha} min={0.01} max={0.1} step={0.001} onChange={(v) => update('RV_alpha', v)} unit="/mL" />
                        <Slider label="Beta (EDP Scale)" value={params.RV_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('RV_beta', v)} unit="mmHg" />
                        <Slider label="Tau (Relaxation)" value={params.RV_tau} min={10} max={100} step={1} onChange={(v) => update('RV_tau', v)} unit="ms" />
                    </div>
                )}

                {/* Pulmonary */}
                <GroupHeader title="Pulmonary Circulation" isOpen={openGroups.pulm} toggle={() => toggleGroup('pulm')} />
                {openGroups.pulm && (
                    <div className="mt-3 pl-1 border-l-2 border-cyan-500/30">
                         {/* Default ~53 */}
                        <Slider label="Total Resistance" value={getPulmR()} min={10} max={200} step={5} onChange={setPulmR} unit="R" />
                         {/* Default ~28 */}
                        <Slider label="Total Compliance" value={getPulmC()} min={5} max={100} step={1} onChange={setPulmC} unit="mL/mmHg" />
                    </div>
                )}

                 {/* Left Atrium */}
                <GroupHeader title="Left Atrium" isOpen={openGroups.la} toggle={() => toggleGroup('la')} />
                {openGroups.la && (
                    <div className="mt-3 pl-1 border-l-2 border-slate-700">
                        <Slider label="Ees" value={params.LA_Ees} min={0.1} max={2.0} step={0.05} onChange={(v) => update('LA_Ees', v)} unit="mmHg/mL" />
                        <Slider label="Beta" value={params.LA_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('LA_beta', v)} unit="mmHg" />
                    </div>
                )}

                 {/* Right Atrium */}
                <GroupHeader title="Right Atrium" isOpen={openGroups.ra} toggle={() => toggleGroup('ra')} />
                {openGroups.ra && (
                    <div className="mt-3 pl-1 border-l-2 border-slate-700">
                         <Slider label="Ees" value={params.RA_Ees} min={0.1} max={2.0} step={0.05} onChange={(v) => update('RA_Ees', v)} unit="mmHg/mL" />
                         <Slider label="Beta" value={params.RA_beta} min={0.1} max={1.0} step={0.01} onChange={(v) => update('RA_beta', v)} unit="mmHg" />
                    </div>
                )}

          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, SimInstance, PhysicsRefState, PanelDef, PanelType, PanelInstanceConfig, ChamberId, SignalType, MetricType } from './types';
import { stepRK4, getTotalVolume } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopPanel, WaveformPanel, MetricsPanel, GuytonPanel } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

const ALL_CHAMBERS: ChamberId[] = ['LV', 'LA', 'RV', 'RA'];
const ALL_SIGNALS: SignalType[] = ['Plv', 'AoP', 'Pla', 'Prv', 'PAP', 'Pra'];
const ALL_METRICS: MetricType[] = ['ABP', 'CVP', 'PAP', 'PCWP', 'SV', 'CO', 'Ea_LV'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState<boolean>(false);
  const [isMobile, setIsMobile] = useState<boolean>(window.innerWidth < 768);

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { 
          id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], 
          params: { ...DEFAULT_PARAMS }, 
          targetVolume: getTotalVolume(INITIAL_STATE_VECTOR), 
          isVisible: true 
      }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Panel Management State ---
  const [panels, setPanels] = useState<PanelDef[]>([
      { 
          id: 'p1', type: 'PVLOOP', title: 'LV PV Loop', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['LV'] } },
          showGuides: true, isSettingsOpen: false
      },
      { 
          id: 'p2', type: 'WAVEFORM', title: 'Monitor', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['Plv', 'AoP'] } },
          timeWindow: 10000,
          isSettingsOpen: false
      }
  ]);

  // --- Refs for Physics Loop ---
  const timeScaleRef = useRef(timeScale);
  const isPlayingRef = useRef(isPlaying);
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());
  const instanceRefs = useRef<SimInstance[]>(instances);

  useEffect(() => { timeScaleRef.current = timeScale; }, [timeScale]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { instanceRefs.current = instances; }, [instances]);

  // Window Resize Hook for Mobile Detection
  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Init physics refs
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              let syncTime = INITIAL_TIME;
              if (physicsRefs.current.size > 0) {
                  for (const p of physicsRefs.current.values()) {
                      if (p.t > syncTime) syncTime = p.t;
                  }
              }
              physicsRefs.current.set(inst.id, {
                  t: syncTime, 
                  y: [...INITIAL_STATE_VECTOR], 
                  buffer: [], 
                  lastRenderX: 0,
                  activeParams: { ...inst.params } 
              });

              setPanels(prev => prev.map(p => {
                 if (p.config[inst.id]) return p;
                 const newConfig = { ...p.config };

                 // Default config for new instance based on panel type
                 let defaultSigs: string[] = [];
                 if (p.type === 'PVLOOP') defaultSigs = ['LV'];
                 else if (p.type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
                 else if (p.type === 'METRICS') defaultSigs = ['ABP', 'CO'];
                 else if (p.type === 'GUYTON_RIGHT' || p.type === 'GUYTON_LEFT' || p.type === 'GUYTON_3D') defaultSigs = ['default'];

                 newConfig[inst.id] = { 
                     visible: true, 
                     selectedSignals: defaultSigs
                 };
                 return { ...p, config: newConfig };
              }));
          }
      });
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) physicsRefs.current.delete(id);
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; 
    const baseStepsPerFrame = 8; 

    const loop = () => {
      if (!isPlayingRef.current) {
          animationFrameId = requestAnimationFrame(loop);
          return;
      }

      const currentScale = timeScaleRef.current;
      const stepsToRun = Math.round(baseStepsPerFrame * currentScale);

      for (let i = 0; i < stepsToRun; i++) {
         instanceRefs.current.forEach(uiInst => {
             const phys = physicsRefs.current.get(uiInst.id);
             if (!phys) return;

             const T = 60000.0 / phys.activeParams.HR; 
             const prevPhase = (phys.t - dt) % T;
             const currPhase = phys.t % T;

             const isEndDiastole = currPhase < prevPhase;
             const tMax = phys.activeParams.LV_Tmax;
             const isEndSystole = prevPhase < tMax && currPhase >= tMax;

             if (isEndDiastole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.HR = p.HR;

                 ap.Ras = p.Ras; ap.Rcs = p.Rcs; ap.Rvs = p.Rvs; ap.Ras_prox = p.Ras_prox; ap.Rda = p.Rda;
                 ap.Rap = p.Rap; ap.Rvp = p.Rvp; ap.Rap_prox = p.Rap_prox; ap.Rcp = p.Rcp;
                 ap.Rmv = p.Rmv; ap.Rtv = p.Rtv;

                 ap.Cas = p.Cas; ap.Cvs = p.Cvs; ap.Cas_prox = p.Cas_prox; ap.Cda = p.Cda;
                 ap.Cap = p.Cap; ap.Cvp = p.Cvp; ap.Cap_prox = p.Cap_prox;

                 ap.LV_Ees = p.LV_Ees; ap.LV_V0 = p.LV_V0;
                 ap.RV_Ees = p.RV_Ees; ap.RV_V0 = p.RV_V0;
                 ap.LA_Ees = p.LA_Ees; ap.LA_V0 = p.LA_V0;
                 ap.RA_Ees = p.RA_Ees; ap.RA_V0 = p.RA_V0;

                 const currentTotal = getTotalVolume(phys.y);
                 const targetTotal = uiInst.targetVolume;
                 const diff = targetTotal - currentTotal;
                 const maxDelta = 500; 
                 const delta = Math.max(-maxDelta, Math.min(maxDelta, diff));

                 if (Math.abs(delta) > 1.0) {
                     phys.y[0] += delta;
                 }
             }

             if (isEndSystole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.LV_alpha = p.LV_alpha; ap.LV_beta = p.LV_beta; ap.LV_tau = p.LV_tau; ap.LV_Tmax = p.LV_Tmax;
                 ap.RV_alpha = p.RV_alpha; ap.RV_beta = p.RV_beta; ap.RV_tau = p.RV_tau; ap.RV_Tmax = p.RV_Tmax;
                 ap.LA_alpha = p.LA_alpha; ap.LA_beta = p.LA_beta; ap.LA_tau = p.LA_tau;
                 ap.RA_alpha = p.RA_alpha; ap.RA_beta = p.RA_beta; ap.RA_tau = p.RA_tau;
             }

             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, phys.activeParams);
             phys.t = tNext;
             phys.y = yNext;

             const bufferRequiredMs = 21000;
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };
            phys.buffer.push(output);
            const cutoffTime = tNext - bufferRequiredMs;
            if (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }
      animationFrameId = requestAnimationFrame(loop);
    };
    animationFrameId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const updateInstanceVolume = (id: string, vol: number) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, targetVolume: vol } : inst
      ));
  }

  const updateInstanceColor = (id: string, color: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, color: color } : inst
    ));
  }
  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];

      // Clone params from active instance or use default
      const sourceInstance = instances.find(i => i.id === activeInstanceId);
      const initialParams = sourceInstance ? JSON.parse(JSON.stringify(sourceInstance.params)) : { ...DEFAULT_PARAMS };
      const initialVol = sourceInstance ? sourceInstance.targetVolume : getTotalVolume(INITIAL_STATE_VECTOR);

      setInstances(prev => [...prev, {
          id: newId, name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color, 
          params: initialParams, 
          targetVolume: initialVol,
          isVisible: true
      }]);
      setActiveInstanceId(newId);
  };
  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) setActiveInstanceId(instances[0]?.id || '');
  };

  // --- Panel Handlers ---
  const addPanel = (type: PanelType) => {
      const newConfig: PanelInstanceConfig = {};
      instances.forEach(i => {
          let defaultSigs: string[] = [];
          if (type === 'PVLOOP') defaultSigs = ['LV'];
          else if (type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
          else if (type === 'METRICS') defaultSigs = ['ABP', 'CO'];
          else if (type === 'GUYTON_RIGHT' || type === 'GUYTON_LEFT' || type === 'GUYTON_3D') defaultSigs = ['Default'];

          newConfig[i.id] = {
              visible: true,
              selectedSignals: defaultSigs
          };
      });

      let title = 'Panel';
      if (type === 'PVLOOP') title = 'PV Loop';
      else if (type === 'WAVEFORM') title = 'Waveforms';
      else if (type === 'METRICS') title = 'Metrics';
      else if (type === 'GUYTON_RIGHT') title = 'Guyton (Right/Sys)';
      else if (type === 'GUYTON_LEFT') title = 'Guyton (Left/Pulm)';
      else if (type === 'GUYTON_3D') title = 'Guyton 3D (Bi-V)';

      const newPanel: PanelDef = {
          id: Date.now().toString(),
          type,
          title,
          w: type === 'METRICS' ? 4 : 6, 
          h: type === 'METRICS' ? 6 : 8,
          config: newConfig,
          showGuides: type === 'PVLOOP',
          timeWindow: type === 'WAVEFORM' ? 10000 : undefined,
          isSettingsOpen: false
      };
      setPanels(prev => [...prev, newPanel]);
      // On mobile, close sidebar after adding panel
      if (isMobile) setIsSidebarOpen(false);
  };

  const removePanel = (id: string) => {
      setPanels(prev => prev.filter(p => p.id !== id));
  };

  const resizeState = useRef<{ panelId: string, startX: number, startY: number, startW: number, startH: number } | null>(null);

  const startResize = (e: React.MouseEvent, panel: PanelDef) => {
      e.stopPropagation();
      e.preventDefault();
      resizeState.current = {
          panelId: panel.id,
          startX: e.clientX,
          startY: e.clientY,
          startW: panel.w,
          startH: panel.h
      };
      document.addEventListener('mousemove', onResizeMove);
      document.addEventListener('mouseup', onResizeEnd);
  };

  const onResizeMove = (e: MouseEvent) => {
      if (!resizeState.current) return;
      const { panelId, startX, startY, startW, startH } = resizeState.current;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      const wDelta = Math.round(dx / 50);
      const hDelta = Math.round(dy / 50);
      const newW = Math.max(2, Math.min(12, startW + wDelta)); 
      const newH = Math.max(4, Math.min(20, startH + hDelta)); 

      setPanels(prev => prev.map(p => 
          p.id === panelId ? { ...p, w: newW, h: newH } : p
      ));
  };

  const onResizeEnd = () => {
      resizeState.current = null;
      document.removeEventListener('mousemove', onResizeMove);
      document.removeEventListener('mouseup', onResizeEnd);
  };


  // --- Config Logic ---
  const toggleSettings = (panelId: string) => {
      setPanels(prev => prev.map(p => 
        p.id === panelId ? { ...p, isSettingsOpen: !p.isSettingsOpen } : { ...p, isSettingsOpen: false }
      ));
  };

  const toggleInstanceVisibility = (panelId: string, instId: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, visible: !prevCfg.visible }
              }
          };
      }));
  };

  const updateInstanceSignals = (panelId: string, instId: string, signal: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          const currentSigs = new Set(prevCfg.selectedSignals);
          if (currentSigs.has(signal)) currentSigs.delete(signal); else currentSigs.add(signal);

          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, selectedSignals: Array.from(currentSigs) }
              }
          };
      }));
  };

  const updateCustomColor = (panelId: string, instId: string, signal: string, color: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { 
                      ...prevCfg, 
                      customColors: { ...prevCfg.customColors, [signal]: color } 
                  }
              }
          };
      }));
  }

  const toggleGuides = (panelId: string) => {
     setPanels(prev => prev.map(p => p.id === panelId ? { ...p, showGuides: !p.showGuides } : p));
  }

  const updateTimeWindow = (panelId: string, val: number) => {
      setPanels(prev => prev.map(p => p.id === panelId ? { ...p, timeWindow: val } : p));
  }

  // --- Drag & Drop ---
  const dragItemRef = useRef<number | null>(null);
  const dragOverItemRef = useRef<number | null>(null);

  const onDragStart = (e: React.DragEvent, index: number) => {
    dragItemRef.current = index;
    e.dataTransfer.effectAllowed = "move";
  };
  const onDragEnter = (e: React.DragEvent, index: number) => {
    dragOverItemRef.current = index;
  };
  const onDragEnd = () => {
    const srcIdx = dragItemRef.current;
    const dstIdx = dragOverItemRef.current;
    if (srcIdx !== null && dstIdx !== null && srcIdx !== dstIdx) {
       setPanels(prev => {
           const next = [...prev];
           const [removed] = next.splice(srcIdx, 1);
           next.splice(dstIdx, 0, removed);
           return next;
       });
    }
    dragItemRef.current = null;
    dragOverItemRef.current = null;
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans relative">

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-14 bg-slate-900 border-b border-slate-800 z-50 flex items-center px-4 justify-between">
          <h1 className="text-lg font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400">
            HemoSim 0D
          </h1>
          <button 
             onClick={() => setIsSidebarOpen(!isSidebarOpen)}
             className="text-slate-300 p-2 hover:bg-slate-800 rounded"
          >
             {isSidebarOpen ? '✕' : '☰'}
          </button>
      </div>

      {/* Sidebar - Desktop: Fixed left, Mobile: Fixed Overlay */}
      <aside 
        className={`
            fixed inset-y-0 left-0 bg-slate-900 border-r border-slate-800 overflow-y-auto z-40 shadow-xl transition-transform duration-300 ease-in-out w-80
            ${isMobile ? 'top-14' : 'top-0'}
            ${isMobile && !isSidebarOpen ? '-translate-x-full' : 'translate-x-0'}
            md:relative md:translate-x-0 md:top-0
        `}
      >
        <div className="p-5 pb-20">
          {!isMobile && (
              <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
                HemoSim 0D
              </h1>
          )}
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            updateInstanceVolume={updateInstanceVolume}
            updateInstanceColor={updateInstanceColor}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}

            addPanel={addPanel}
          />
        </div>
      </aside>

      {/* Mobile Overlay Backdrop */}
      {isMobile && isSidebarOpen && (
          <div 
            className="fixed inset-0 bg-black/50 z-30" 
            onClick={() => setIsSidebarOpen(false)}
          />
      )}

      <main className={`flex-1 h-full overflow-y-auto overflow-x-hidden bg-slate-950 p-2 ${isMobile ? 'pt-16' : ''}`}>
          {/* Grid Container */}
          <div className="grid grid-cols-12 gap-2 auto-rows-[50px] grid-flow-dense pb-20">
              {panels.map((panel, index) => {
                  // Mobile: Force span 12 (full width). Desktop: Use panel.w
                  const gridColStyle = isMobile ? { gridColumn: 'span 12' } : { gridColumn: `span ${panel.w}` };

                  return (
                  <div 
                    key={panel.id} 
                    draggable={!isMobile} // Disable drag on mobile to prevent scroll issues
                    onDragStart={(e) => onDragStart(e, index)}
                    onDragEnter={(e) => onDragEnter(e, index)}
                    onDragEnd={onDragEnd}
                    onDragOver={(e) => e.preventDefault()}
                    style={{ ...gridColStyle, gridRow: `span ${panel.h}` }}
                    className="relative bg-slate-900/50 rounded-lg border border-slate-800 shadow-inner flex flex-col overflow-visible group hover:border-slate-600 transition-colors"
                  >
                      {/* Panel Header */}
                      <div className="absolute top-2 left-2 z-30 flex gap-2 items-center pointer-events-auto">
                           <div className="bg-slate-950/90 px-2 py-1 rounded border border-slate-700 backdrop-blur-sm shadow-sm flex items-center gap-2 cursor-move">
                                <span className="text-xs font-bold text-slate-300 select-none">⋮⋮ {panel.title}</span>
                                <div className="h-3 w-[1px] bg-slate-700 mx-1"></div>

                                {/* Settings Toggle (Click-based) */}
                                <div className="relative">
                                    <button 
                                        onClick={() => toggleSettings(panel.id)}
                                        className={`text-[10px] px-1 flex items-center gap-1 rounded hover:bg-slate-800 ${panel.isSettingsOpen ? 'text-blue-400 bg-slate-800' : 'text-slate-400'}`}
                                    >
                                        <span className="w-3 h-3 border border-current rounded-sm flex items-center justify-center">
                                            <span className="text-[8px]">⚙</span>
                                        </span>
                                    </button>

                                    {/* Dropdown Content */}
                                    {panel.isSettingsOpen && (
                                        <div className="absolute top-full left-0 mt-2 w-56 bg-slate-900 border border-slate-700 rounded shadow-2xl p-3 z-50">
                                            <div className="flex justify-between items-center mb-2 pb-2 border-b border-slate-800">
                                                <span className="text-[10px] font-bold text-slate-500 uppercase">Configuration</span>
                                                <button onClick={() => toggleSettings(panel.id)} className="text-xs text-slate-400 hover:text-white">✕</button>
                                            </div>

                                            {/* Panel Specific Settings */}
                                            {panel.type === 'PVLOOP' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800 flex items-center gap-2">
                                                    <input type="checkbox" checked={panel.showGuides} onChange={() => toggleGuides(panel.id)} />
                                                    <span className="text-xs text-slate-300">Show Guides</span>
                                                </div>
                                            )}
                                            {panel.type === 'WAVEFORM' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800">
                                                    <div className="flex justify-between text-[10px] text-slate-400 mb-1">
                                                        <span>Window</span>
                                                        <span>{(panel.timeWindow || 10000) / 1000}s</span>
                                                    </div>
                                                    <input 
                                                        type="range" min={2000} max={20000} step={1000} 
                                                        value={panel.timeWindow || 10000}
                                                        onChange={(e) => updateTimeWindow(panel.id, parseFloat(e.target.value))}
                                                        className="w-full h-1 bg-slate-700 rounded appearance-none cursor-pointer accent-blue-500"
                                                    />
                                                </div>
                                            )}

                                            <div className="max-h-64 overflow-y-auto space-y-3 custom-scrollbar">
                                                {instances.map(inst => (
                                                    <div key={inst.id}>
                                                        <div className="flex items-center gap-2 mb-1">
                                                            <input 
                                                                type="checkbox" 
                                                                checked={panel.config[inst.id]?.visible || false}
                                                                onChange={() => toggleInstanceVisibility(panel.id, inst.id)}
                                                            />
                                                            <span className="w-2 h-2 rounded-full" style={{backgroundColor: inst.color}}></span>
                                                            <span className="text-xs font-bold text-slate-300 truncate flex-1">{inst.name}</span>
                                                        </div>
                                                        {/* Sub Signals & Colors */}
                                                        {panel.config[inst.id]?.visible && (panel.type !== 'GUYTON_RIGHT' && panel.type !== 'GUYTON_LEFT' && panel.type !== 'GUYTON_3D') && (
                                                            <div className="pl-5 grid grid-cols-1 gap-1">
                                                                {((panel.type === 'PVLOOP' ? ALL_CHAMBERS : (panel.type === 'WAVEFORM' ? ALL_SIGNALS : ALL_METRICS))).map(sig => {
                                                                    const isSelected = panel.config[inst.id].selectedSignals.includes(sig);
                                                                    const customColor = panel.config[inst.id].customColors?.[sig];

                                                                    return (
                                                                    <div key={sig} className="flex items-center justify-between text-[10px] bg-slate-950/50 rounded px-1 py-0.5">
                                                                        <button 
                                                                            onClick={() => updateInstanceSignals(panel.id, inst.id, sig)}
                                                                            className={`flex-1 text-left ${isSelected ? 'text-slate-200' : 'text-slate-600'}`}
                                                                        >
                                                                            {sig}
                                                                        </button>
                                                                        {isSelected && panel.type !== 'METRICS' && (
                                                                            <input 
                                                                                type="color" 
                                                                                className="w-3 h-3 border-none p-0 bg-transparent cursor-pointer"
                                                                                value={customColor || inst.color} 
                                                                                onChange={(e) => updateCustomColor(panel.id, inst.id, sig, e.target.value)}
                                                                            />
                                                                        )}
                                                                    </div>
                                                                )})}
                                                            </div>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <button onClick={() => removePanel(panel.id)} className="text-slate-500 hover:text-red-400 ml-1">✕</button>
                           </div>
                      </div>

                      {/* Content */}
                      <div className="flex-1 min-h-0 w-full p-1 pt-2">
                          {panel.type === 'PVLOOP' && (
                              <PVLoopPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                config={panel.config}
                                showGuides={panel.showGuides}
                              />
                          )}
                          {panel.type === 'WAVEFORM' && (
                              <WaveformPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                timeWindow={panel.timeWindow || 10000}
                                config={panel.config}
                              />
                          )}
                          {panel.type === 'METRICS' && (
                               <MetricsPanel 
                                  physicsRefs={physicsRefs}
                                  instances={instances}
                                  config={panel.config}
                               />
                          )}
                          {(panel.type === 'GUYTON_RIGHT' || panel.type === 'GUYTON_LEFT' || panel.type === 'GUYTON_3D') && (
                                <GuytonPanel 
                                    physicsRefs={physicsRefs}
                                    instances={instances}
                                    config={panel.config}
                                    type={panel.type as any}
                                />
                          )}
                      </div>

                      {/* Resize Handle - Hide on mobile */}
                      {!isMobile && (
                        <div 
                            onMouseDown={(e) => startResize(e, panel)}
                            className="absolute bottom-0 right-0 w-4 h-4 cursor-se-resize flex items-end justify-end p-0.5 z-40 group/handle"
                        >
                            <div className="w-0 h-0 border-l-[8px] border-l-transparent border-b-[8px] border-b-slate-600 group-hover/handle:border-b-blue-500"></div>
                        </div>
                      )}
                  </div>
              )})}
          </div>
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, SimInstance, PhysicsRefState, PanelDef, PanelType, PanelInstanceConfig, ChamberId, SignalType, MetricType } from './types';
import { stepRK4, getTotalVolume } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopPanel, WaveformPanel, MetricsPanel, GuytonPanel } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

const ALL_CHAMBERS: ChamberId[] = ['LV', 'LA', 'RV', 'RA'];
const ALL_SIGNALS: SignalType[] = ['Plv', 'AoP', 'Pla', 'Prv', 'PAP', 'Pra'];
const ALL_METRICS: MetricType[] = ['ABP', 'CVP', 'PAP', 'PCWP', 'SV', 'CO', 'Ea_LV'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState<boolean>(false);
  const [isMobile, setIsMobile] = useState<boolean>(window.innerWidth < 768);

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { 
          id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], 
          params: { ...DEFAULT_PARAMS }, 
          targetVolume: getTotalVolume(INITIAL_STATE_VECTOR), 
          isVisible: true 
      }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Panel Management State ---
  const [panels, setPanels] = useState<PanelDef[]>([
      { 
          id: 'p1', type: 'PVLOOP', title: 'LV PV Loop', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['LV'] } },
          showGuides: true, isSettingsOpen: false
      },
      { 
          id: 'p2', type: 'WAVEFORM', title: 'Monitor', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['Plv', 'AoP'] } },
          timeWindow: 5000,
          isSettingsOpen: false
      },
      {
          id: 'p3', type: 'METRICS', title: 'Metrics', w: 4, h: 6,
          config: { '1': { visible: true, selectedSignals: ['ABP', 'CO', 'CVP', 'PCWP'] } },
          isSettingsOpen: false
      },
      {
          id: 'p4', type: 'GUYTON_RIGHT', title: 'Guyton (Right)', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['Default'] } },
          isSettingsOpen: false
      },
      {
          id: 'p5', type: 'GUYTON_LEFT', title: 'Guyton (Left)', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['Default'] } },
          isSettingsOpen: false
      }
  ]);

  // --- Refs for Physics Loop ---
  const timeScaleRef = useRef(timeScale);
  const isPlayingRef = useRef(isPlaying);
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());
  const instanceRefs = useRef<SimInstance[]>(instances);

  useEffect(() => { timeScaleRef.current = timeScale; }, [timeScale]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { instanceRefs.current = instances; }, [instances]);

  // Window Resize Hook for Mobile Detection
  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Init physics refs
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              let syncTime = INITIAL_TIME;
              if (physicsRefs.current.size > 0) {
                  for (const p of physicsRefs.current.values()) {
                      if (p.t > syncTime) syncTime = p.t;
                  }
              }
              physicsRefs.current.set(inst.id, {
                  t: syncTime, 
                  y: [...INITIAL_STATE_VECTOR], 
                  buffer: [], 
                  lastRenderX: 0,
                  activeParams: { ...inst.params } 
              });

              setPanels(prev => prev.map(p => {
                 if (p.config[inst.id]) return p;
                 const newConfig = { ...p.config };

                 // Default config for new instance based on panel type
                 let defaultSigs: string[] = [];
                 if (p.type === 'PVLOOP') defaultSigs = ['LV'];
                 else if (p.type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
                 else if (p.type === 'METRICS') defaultSigs = ['ABP', 'CO'];
                 else if (p.type === 'GUYTON_RIGHT' || p.type === 'GUYTON_LEFT' || p.type === 'GUYTON_3D') defaultSigs = ['default'];

                 newConfig[inst.id] = { 
                     visible: true, 
                     selectedSignals: defaultSigs
                 };
                 return { ...p, config: newConfig };
              }));
          }
      });
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) physicsRefs.current.delete(id);
      }
  }, [instances]);

  // --- Physics Loop ---
  useEffect(() => {
    let animationFrameId: number;
    const dt = 2.0; 
    const baseStepsPerFrame = 8; 

    const loop = () => {
      if (!isPlayingRef.current) {
          animationFrameId = requestAnimationFrame(loop);
          return;
      }

      const currentScale = timeScaleRef.current;
      const stepsToRun = Math.round(baseStepsPerFrame * currentScale);

      for (let i = 0; i < stepsToRun; i++) {
         instanceRefs.current.forEach(uiInst => {
             const phys = physicsRefs.current.get(uiInst.id);
             if (!phys) return;

             const T = 60000.0 / phys.activeParams.HR; 
             const prevPhase = (phys.t - dt) % T;
             const currPhase = phys.t % T;

             const isEndDiastole = currPhase < prevPhase;
             const tMax = phys.activeParams.LV_Tmax;
             const isEndSystole = prevPhase < tMax && currPhase >= tMax;

             if (isEndDiastole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.HR = p.HR;

                 ap.Ras = p.Ras; ap.Rcs = p.Rcs; ap.Rvs = p.Rvs; ap.Ras_prox = p.Ras_prox; ap.Rda = p.Rda;
                 ap.Rap = p.Rap; ap.Rvp = p.Rvp; ap.Rap_prox = p.Rap_prox; ap.Rcp = p.Rcp;
                 ap.Rmv = p.Rmv; ap.Rtv = p.Rtv;

                 ap.Cas = p.Cas; ap.Cvs = p.Cvs; ap.Cas_prox = p.Cas_prox; ap.Cda = p.Cda;
                 ap.Cap = p.Cap; ap.Cvp = p.Cvp; ap.Cap_prox = p.Cap_prox;

                 ap.LV_Ees = p.LV_Ees; ap.LV_V0 = p.LV_V0;
                 ap.RV_Ees = p.RV_Ees; ap.RV_V0 = p.RV_V0;
                 ap.LA_Ees = p.LA_Ees; ap.LA_V0 = p.LA_V0;
                 ap.RA_Ees = p.RA_Ees; ap.RA_V0 = p.RA_V0;

                 const currentTotal = getTotalVolume(phys.y);
                 const targetTotal = uiInst.targetVolume;
                 const diff = targetTotal - currentTotal;
                 const maxDelta = 500; 
                 const delta = Math.max(-maxDelta, Math.min(maxDelta, diff));

                 if (Math.abs(delta) > 1.0) {
                     phys.y[0] += delta;
                 }
             }

             if (isEndSystole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.LV_alpha = p.LV_alpha; ap.LV_beta = p.LV_beta; ap.LV_tau = p.LV_tau; ap.LV_Tmax = p.LV_Tmax;
                 ap.RV_alpha = p.RV_alpha; ap.RV_beta = p.RV_beta; ap.RV_tau = p.RV_tau; ap.RV_Tmax = p.RV_Tmax;
                 ap.LA_alpha = p.LA_alpha; ap.LA_beta = p.LA_beta; ap.LA_tau = p.LA_tau;
                 ap.RA_alpha = p.RA_alpha; ap.RA_beta = p.RA_beta; ap.RA_tau = p.RA_tau;
             }

             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, dt, phys.activeParams);
             phys.t = tNext;
             phys.y = yNext;

             const bufferRequiredMs = 21000;
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };
            phys.buffer.push(output);
            const cutoffTime = tNext - bufferRequiredMs;
            if (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }
      animationFrameId = requestAnimationFrame(loop);
    };
    animationFrameId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const updateInstanceVolume = (id: string, vol: number) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, targetVolume: vol } : inst
      ));
  }

  const updateInstanceColor = (id: string, color: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, color: color } : inst
    ));
  }
  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];

      // Clone params from active instance or use default
      const sourceInstance = instances.find(i => i.id === activeInstanceId);
      const initialParams = sourceInstance ? JSON.parse(JSON.stringify(sourceInstance.params)) : { ...DEFAULT_PARAMS };
      const initialVol = sourceInstance ? sourceInstance.targetVolume : getTotalVolume(INITIAL_STATE_VECTOR);

      setInstances(prev => [...prev, {
          id: newId, name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color, 
          params: initialParams, 
          targetVolume: initialVol,
          isVisible: true
      }]);
      setActiveInstanceId(newId);
  };
  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) setActiveInstanceId(instances[0]?.id || '');
  };

  // --- Panel Handlers ---
  const addPanel = (type: PanelType) => {
      const newConfig: PanelInstanceConfig = {};
      instances.forEach(i => {
          let defaultSigs: string[] = [];
          if (type === 'PVLOOP') defaultSigs = ['LV'];
          else if (type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
          else if (type === 'METRICS') defaultSigs = ['ABP', 'CO'];
          else if (type === 'GUYTON_RIGHT' || type === 'GUYTON_LEFT' || type === 'GUYTON_3D') defaultSigs = ['Default'];

          newConfig[i.id] = {
              visible: true,
              selectedSignals: defaultSigs
          };
      });

      let title = 'Panel';
      if (type === 'PVLOOP') title = 'PV Loop';
      else if (type === 'WAVEFORM') title = 'Waveforms';
      else if (type === 'METRICS') title = 'Metrics';
      else if (type === 'GUYTON_RIGHT') title = 'Guyton (Right/Sys)';
      else if (type === 'GUYTON_LEFT') title = 'Guyton (Left/Pulm)';
      else if (type === 'GUYTON_3D') title = 'Guyton 3D (Bi-V)';

      const newPanel: PanelDef = {
          id: Date.now().toString(),
          type,
          title,
          w: type === 'METRICS' ? 4 : 6, 
          h: type === 'METRICS' ? 6 : 8,
          config: newConfig,
          showGuides: type === 'PVLOOP',
          timeWindow: type === 'WAVEFORM' ? 5000 : undefined,
          isSettingsOpen: false
      };
      setPanels(prev => [...prev, newPanel]);
      // On mobile, close sidebar after adding panel
      if (isMobile) setIsSidebarOpen(false);
  };

  const removePanel = (id: string) => {
      setPanels(prev => prev.filter(p => p.id !== id));
  };

  const resizeState = useRef<{ panelId: string, startX: number, startY: number, startW: number, startH: number } | null>(null);

  const startResize = (e: React.MouseEvent, panel: PanelDef) => {
      e.stopPropagation();
      e.preventDefault();
      resizeState.current = {
          panelId: panel.id,
          startX: e.clientX,
          startY: e.clientY,
          startW: panel.w,
          startH: panel.h
      };
      document.addEventListener('mousemove', onResizeMove);
      document.addEventListener('mouseup', onResizeEnd);
  };

  const onResizeMove = (e: MouseEvent) => {
      if (!resizeState.current) return;
      const { panelId, startX, startY, startW, startH } = resizeState.current;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      const wDelta = Math.round(dx / 50);
      const hDelta = Math.round(dy / 50);
      const newW = Math.max(2, Math.min(12, startW + wDelta)); 
      const newH = Math.max(4, Math.min(20, startH + hDelta)); 

      setPanels(prev => prev.map(p => 
          p.id === panelId ? { ...p, w: newW, h: newH } : p
      ));
  };

  const onResizeEnd = () => {
      resizeState.current = null;
      document.removeEventListener('mousemove', onResizeMove);
      document.removeEventListener('mouseup', onResizeEnd);
  };


  // --- Config Logic ---
  const toggleSettings = (panelId: string) => {
      setPanels(prev => prev.map(p => 
        p.id === panelId ? { ...p, isSettingsOpen: !p.isSettingsOpen } : { ...p, isSettingsOpen: false }
      ));
  };

  const toggleInstanceVisibility = (panelId: string, instId: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, visible: !prevCfg.visible }
              }
          };
      }));
  };

  const updateInstanceSignals = (panelId: string, instId: string, signal: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          const currentSigs = new Set(prevCfg.selectedSignals);
          if (currentSigs.has(signal)) currentSigs.delete(signal); else currentSigs.add(signal);

          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, selectedSignals: Array.from(currentSigs) }
              }
          };
      }));
  };

  const updateCustomColor = (panelId: string, instId: string, signal: string, color: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { 
                      ...prevCfg, 
                      customColors: { ...prevCfg.customColors, [signal]: color } 
                  }
              }
          };
      }));
  }

  const toggleGuides = (panelId: string) => {
     setPanels(prev => prev.map(p => p.id === panelId ? { ...p, showGuides: !p.showGuides } : p));
  }

  const updateTimeWindow = (panelId: string, val: number) => {
      setPanels(prev => prev.map(p => p.id === panelId ? { ...p, timeWindow: val } : p));
  }

  // --- Drag & Drop ---
  const dragItemRef = useRef<number | null>(null);
  const dragOverItemRef = useRef<number | null>(null);

  const onDragStart = (e: React.DragEvent, index: number) => {
    dragItemRef.current = index;
    e.dataTransfer.effectAllowed = "move";
  };
  const onDragEnter = (e: React.DragEvent, index: number) => {
    dragOverItemRef.current = index;
  };
  const onDragEnd = () => {
    const srcIdx = dragItemRef.current;
    const dstIdx = dragOverItemRef.current;
    if (srcIdx !== null && dstIdx !== null && srcIdx !== dstIdx) {
       setPanels(prev => {
           const next = [...prev];
           const [removed] = next.splice(srcIdx, 1);
           next.splice(dstIdx, 0, removed);
           return next;
       });
    }
    dragItemRef.current = null;
    dragOverItemRef.current = null;
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans relative">

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-14 bg-slate-900 border-b border-slate-800 z-50 flex items-center px-4 justify-between">
          <h1 className="text-lg font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400">
            HemoSim 0D
          </h1>
          <button 
             onClick={() => setIsSidebarOpen(!isSidebarOpen)}
             className="text-slate-300 p-2 hover:bg-slate-800 rounded"
          >
             {isSidebarOpen ? '✕' : '☰'}
          </button>
      </div>

      {/* Sidebar - Desktop: Fixed left, Mobile: Fixed Overlay (Right side) */}
      <aside 
        className={`
            fixed inset-y-0 right-0 bg-slate-900 overflow-y-auto z-40 shadow-xl transition-transform duration-300 ease-in-out w-80
            md:border-r md:border-slate-800
            ${isMobile ? 'top-14 border-l border-slate-800' : 'top-0'}
            ${isMobile && !isSidebarOpen ? 'translate-x-full' : 'translate-x-0'}
            md:relative md:translate-x-0 md:top-0 md:left-0 md:right-auto
        `}
      >
        <div className="p-5 pb-20">
          {!isMobile && (
              <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
                HemoSim 0D
              </h1>
          )}
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            updateInstanceVolume={updateInstanceVolume}
            updateInstanceColor={updateInstanceColor}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}

            addPanel={addPanel}
          />
        </div>
      </aside>

      {/* Mobile Overlay Backdrop */}
      {isMobile && isSidebarOpen && (
          <div 
            className="fixed inset-0 bg-black/50 z-30" 
            onClick={() => setIsSidebarOpen(false)}
          />
      )}

      <main className={`flex-1 h-full overflow-y-auto overflow-x-hidden bg-slate-950 p-2 ${isMobile ? 'pt-16' : ''}`}>
          {/* Grid Container */}
          <div className="grid grid-cols-12 gap-2 auto-rows-[50px] grid-flow-dense pb-20">
              {panels.map((panel, index) => {
                  // Mobile: Force span 12 (full width). Desktop: Use panel.w
                  const gridColStyle = isMobile ? { gridColumn: 'span 12' } : { gridColumn: `span ${panel.w}` };
                  // Mobile: Use fixed rows for better aspect ratio (Metrics smaller, Charts larger). Desktop: Use panel.h
                  const mobileRowSpan = panel.type === 'METRICS' ? 5 : 7;
                  const rowSpan = isMobile ? mobileRowSpan : panel.h;

                  return (
                  <div 
                    key={panel.id} 
                    draggable={!isMobile} // Disable drag on mobile to prevent scroll issues
                    onDragStart={(e) => onDragStart(e, index)}
                    onDragEnter={(e) => onDragEnter(e, index)}
                    onDragEnd={onDragEnd}
                    onDragOver={(e) => e.preventDefault()}
                    style={{ ...gridColStyle, gridRow: `span ${rowSpan}` }}
                    className="relative bg-slate-900/50 rounded-lg border border-slate-800 shadow-inner flex flex-col overflow-visible group hover:border-slate-600 transition-colors"
                  >
                      {/* Panel Header */}
                      <div className="absolute top-2 left-2 z-30 flex gap-2 items-center pointer-events-auto">
                           <div className="bg-slate-950/90 px-2 py-1 rounded border border-slate-700 backdrop-blur-sm shadow-sm flex items-center gap-2 cursor-move">
                                <span className="text-xs font-bold text-slate-300 select-none">⋮⋮ {panel.title}</span>
                                <div className="h-3 w-[1px] bg-slate-700 mx-1"></div>

                                {/* Settings Toggle (Click-based) */}
                                <div className="relative">
                                    <button 
                                        onClick={() => toggleSettings(panel.id)}
                                        className={`text-[10px] px-1 flex items-center gap-1 rounded hover:bg-slate-800 ${panel.isSettingsOpen ? 'text-blue-400 bg-slate-800' : 'text-slate-400'}`}
                                    >
                                        <span className="w-3 h-3 border border-current rounded-sm flex items-center justify-center">
                                            <span className="text-[8px]">⚙</span>
                                        </span>
                                    </button>

                                    {/* Dropdown Content */}
                                    {panel.isSettingsOpen && (
                                        <div className="absolute top-full left-0 mt-2 w-56 bg-slate-900 border border-slate-700 rounded shadow-2xl p-3 z-50">
                                            <div className="flex justify-between items-center mb-2 pb-2 border-b border-slate-800">
                                                <span className="text-[10px] font-bold text-slate-500 uppercase">Configuration</span>
                                                <button onClick={() => toggleSettings(panel.id)} className="text-xs text-slate-400 hover:text-white">✕</button>
                                            </div>

                                            {/* Panel Specific Settings */}
                                            {panel.type === 'PVLOOP' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800 flex items-center gap-2">
                                                    <input type="checkbox" checked={panel.showGuides} onChange={() => toggleGuides(panel.id)} />
                                                    <span className="text-xs text-slate-300">Show Guides</span>
                                                </div>
                                            )}
                                            {panel.type === 'WAVEFORM' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800">
                                                    <div className="flex justify-between text-[10px] text-slate-400 mb-1">
                                                        <span>Window</span>
                                                        <span>{(panel.timeWindow || 10000) / 1000}s</span>
                                                    </div>
                                                    <input 
                                                        type="range" min={2000} max={20000} step={1000} 
                                                        value={panel.timeWindow || 10000}
                                                        onChange={(e) => updateTimeWindow(panel.id, parseFloat(e.target.value))}
                                                        className="w-full h-1 bg-slate-700 rounded appearance-none cursor-pointer accent-blue-500"
                                                    />
                                                </div>
                                            )}

                                            <div className="max-h-64 overflow-y-auto space-y-3 custom-scrollbar">
                                                {instances.map(inst => (
                                                    <div key={inst.id}>
                                                        <div className="flex items-center gap-2 mb-1">
                                                            <input 
                                                                type="checkbox" 
                                                                checked={panel.config[inst.id]?.visible || false}
                                                                onChange={() => toggleInstanceVisibility(panel.id, inst.id)}
                                                            />
                                                            <span className="w-2 h-2 rounded-full" style={{backgroundColor: inst.color}}></span>
                                                            <span className="text-xs font-bold text-slate-300 truncate flex-1">{inst.name}</span>
                                                        </div>
                                                        {/* Sub Signals & Colors */}
                                                        {panel.config[inst.id]?.visible && (panel.type !== 'GUYTON_RIGHT' && panel.type !== 'GUYTON_LEFT' && panel.type !== 'GUYTON_3D') && (
                                                            <div className="pl-5 grid grid-cols-1 gap-1">
                                                                {((panel.type === 'PVLOOP' ? ALL_CHAMBERS : (panel.type === 'WAVEFORM' ? ALL_SIGNALS : ALL_METRICS))).map(sig => {
                                                                    const isSelected = panel.config[inst.id].selectedSignals.includes(sig);
                                                                    const customColor = panel.config[inst.id].customColors?.[sig];

                                                                    return (
                                                                    <div key={sig} className="flex items-center justify-between text-[10px] bg-slate-950/50 rounded px-1 py-0.5">
                                                                        <button 
                                                                            onClick={() => updateInstanceSignals(panel.id, inst.id, sig)}
                                                                            className={`flex-1 text-left ${isSelected ? 'text-slate-200' : 'text-slate-600'}`}
                                                                        >
                                                                            {sig}
                                                                        </button>
                                                                        {isSelected && panel.type !== 'METRICS' && (
                                                                            <input 
                                                                                type="color" 
                                                                                className="w-3 h-3 border-none p-0 bg-transparent cursor-pointer"
                                                                                value={customColor || inst.color} 
                                                                                onChange={(e) => updateCustomColor(panel.id, inst.id, sig, e.target.value)}
                                                                            />
                                                                        )}
                                                                    </div>
                                                                )})}
                                                            </div>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <button onClick={() => removePanel(panel.id)} className="text-slate-500 hover:text-red-400 ml-1">✕</button>
                           </div>
                      </div>

                      {/* Content */}
                      <div className="flex-1 min-h-0 w-full p-1 pt-2">
                          {panel.type === 'PVLOOP' && (
                              <PVLoopPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                config={panel.config}
                                showGuides={panel.showGuides}
                              />
                          )}
                          {panel.type === 'WAVEFORM' && (
                              <WaveformPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                timeWindow={panel.timeWindow || 10000}
                                config={panel.config}
                              />
                          )}
                          {panel.type === 'METRICS' && (
                               <MetricsPanel 
                                  physicsRefs={physicsRefs}
                                  instances={instances}
                                  config={panel.config}
                               />
                          )}
                          {(panel.type === 'GUYTON_RIGHT' || panel.type === 'GUYTON_LEFT' || panel.type === 'GUYTON_3D') && (
                                <GuytonPanel 
                                    physicsRefs={physicsRefs}
                                    instances={instances}
                                    config={panel.config}
                                    type={panel.type as any}
                                />
                          )}
                      </div>

                      {/* Resize Handle - Hide on mobile */}
                      {!isMobile && (
                        <div 
                            onMouseDown={(e) => startResize(e, panel)}
                            className="absolute bottom-0 right-0 w-4 h-4 cursor-se-resize flex items-end justify-end p-0.5 z-40 group/handle"
                        >
                            <div className="w-0 h-0 border-l-[8px] border-l-transparent border-b-[8px] border-b-slate-600 group-hover/handle:border-b-blue-500"></div>
                        </div>
                      )}
                  </div>
              )})}
          </div>
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_STATE_VECTOR, INITIAL_TIME, DEFAULT_PARAMS } from './constants';
import { SimulationParams, SimulationOutput, SimInstance, PhysicsRefState, PanelDef, PanelType, PanelInstanceConfig, ChamberId, SignalType, MetricType } from './types';
import { stepRK4, getTotalVolume } from './services/physics';
import { Controls } from './components/Controls';
import { PVLoopPanel, WaveformPanel, MetricsPanel, GuytonPanel } from './components/Charts';

// Colors for instances
const INSTANCE_COLORS = ['#a855f7', '#f472b6', '#22c55e', '#38bdf8', '#fbbf24'];

const ALL_CHAMBERS: ChamberId[] = ['LV', 'LA', 'RV', 'RA'];
const ALL_SIGNALS: SignalType[] = ['Plv', 'AoP', 'Pla', 'Prv', 'PAP', 'Pra'];
const ALL_METRICS: MetricType[] = ['ABP', 'CVP', 'PAP', 'PCWP', 'SV', 'CO', 'Ea_LV'];

function App() {
  // --- State ---
  const [timeScale, setTimeScale] = useState<number>(1.0);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState<boolean>(false);
  const [isMobile, setIsMobile] = useState<boolean>(window.innerWidth < 768);

  // Instance Management
  const [instances, setInstances] = useState<SimInstance[]>([
      { 
          id: '1', name: 'Heart A', color: INSTANCE_COLORS[0], 
          params: { ...DEFAULT_PARAMS }, 
          targetVolume: getTotalVolume(INITIAL_STATE_VECTOR), 
          isVisible: true 
      }
  ]);
  const [activeInstanceId, setActiveInstanceId] = useState<string>('1');

  // --- Panel Management State ---
  // Initial Layout: Guyton (Right), Guyton (Left), Metrics
  const [panels, setPanels] = useState<PanelDef[]>([
      {
          id: 'p1', type: 'GUYTON_RIGHT', title: 'Guyton (Right)', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['Default'] } },
          isSettingsOpen: false
      },
      {
          id: 'p2', type: 'GUYTON_LEFT', title: 'Guyton (Left)', w: 6, h: 8,
          config: { '1': { visible: true, selectedSignals: ['Default'] } },
          isSettingsOpen: false
      },
      {
          id: 'p3', type: 'METRICS', title: 'Metrics', w: 12, h: 4,
          config: { '1': { visible: true, selectedSignals: ['ABP', 'CO', 'CVP', 'PCWP', 'SV', 'Ea_LV'] } },
          isSettingsOpen: false
      }
  ]);

  // --- Refs for Physics Loop ---
  const timeScaleRef = useRef(timeScale);
  const isPlayingRef = useRef(isPlaying);
  const physicsRefs = useRef<Map<string, PhysicsRefState>>(new Map());
  const instanceRefs = useRef<SimInstance[]>(instances);

  // Physics Timing Refs
  const lastFrameTimeRef = useRef<number>(0);
  const residueTimeRef = useRef<number>(0);

  useEffect(() => { timeScaleRef.current = timeScale; }, [timeScale]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { instanceRefs.current = instances; }, [instances]);

  // Window Resize Hook for Mobile Detection
  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Init physics refs
  useEffect(() => {
      instances.forEach(inst => {
          if (!physicsRefs.current.has(inst.id)) {
              let syncTime = INITIAL_TIME;
              if (physicsRefs.current.size > 0) {
                  for (const p of physicsRefs.current.values()) {
                      if (p.t > syncTime) syncTime = p.t;
                  }
              }
              physicsRefs.current.set(inst.id, {
                  t: syncTime, 
                  y: [...INITIAL_STATE_VECTOR], 
                  buffer: [], 
                  lastRenderX: 0,
                  activeParams: { ...inst.params } 
              });

              setPanels(prev => prev.map(p => {
                 if (p.config[inst.id]) return p;
                 const newConfig = { ...p.config };

                 // Default config for new instance based on panel type
                 let defaultSigs: string[] = [];
                 if (p.type === 'PVLOOP') defaultSigs = ['LV'];
                 else if (p.type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
                 else if (p.type === 'METRICS') defaultSigs = ['ABP', 'CO'];
                 else if (p.type === 'GUYTON_RIGHT' || p.type === 'GUYTON_LEFT' || p.type === 'GUYTON_3D') defaultSigs = ['default'];

                 newConfig[inst.id] = { 
                     visible: true, 
                     selectedSignals: defaultSigs
                 };
                 return { ...p, config: newConfig };
              }));
          }
      });
      const currentIds = new Set(instances.map(i => i.id));
      for (const id of physicsRefs.current.keys()) {
          if (!currentIds.has(id)) physicsRefs.current.delete(id);
      }
  }, [instances]);

  // --- Physics Loop (Delta-Time Based) ---
  useEffect(() => {
    let animationFrameId: number;
    const PHYSICS_DT = 2.0; // Fixed physics step size (ms)
    const MAX_STEPS_PER_FRAME = 20; // Prevent spiral of death on lag spikes

    const loop = (now: number) => {
      if (!lastFrameTimeRef.current) lastFrameTimeRef.current = now;
      const deltaTimeMs = now - lastFrameTimeRef.current;
      lastFrameTimeRef.current = now;

      if (!isPlayingRef.current) {
          residueTimeRef.current = 0; // Reset accumulated time if paused
          animationFrameId = requestAnimationFrame(loop);
          return;
      }

      // Add time to accumulator, scaled by playback speed
      residueTimeRef.current += deltaTimeMs * timeScaleRef.current;

      // Calculate how many fixed steps fit in the accumulated time
      let stepsToRun = Math.floor(residueTimeRef.current / PHYSICS_DT);

      // Prevent freeze if tab was backgrounded or huge lag spike
      if (stepsToRun > MAX_STEPS_PER_FRAME) {
          stepsToRun = MAX_STEPS_PER_FRAME;
          residueTimeRef.current = 0; // Reset residue to avoid endless catch-up
      } else {
          residueTimeRef.current -= stepsToRun * PHYSICS_DT;
      }

      for (let i = 0; i < stepsToRun; i++) {
         instanceRefs.current.forEach(uiInst => {
             const phys = physicsRefs.current.get(uiInst.id);
             if (!phys) return;

             const T = 60000.0 / phys.activeParams.HR; 
             const prevPhase = (phys.t - PHYSICS_DT) % T;
             const currPhase = phys.t % T;

             const isEndDiastole = currPhase < prevPhase;
             const tMax = phys.activeParams.LV_Tmax;
             const isEndSystole = prevPhase < tMax && currPhase >= tMax;

             if (isEndDiastole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.HR = p.HR;

                 ap.Ras = p.Ras; ap.Rcs = p.Rcs; ap.Rvs = p.Rvs; ap.Ras_prox = p.Ras_prox; ap.Rda = p.Rda;
                 ap.Rap = p.Rap; ap.Rvp = p.Rvp; ap.Rap_prox = p.Rap_prox; ap.Rcp = p.Rcp;
                 ap.Rmv = p.Rmv; ap.Rtv = p.Rtv;

                 ap.Cas = p.Cas; ap.Cvs = p.Cvs; ap.Cas_prox = p.Cas_prox; ap.Cda = p.Cda;
                 ap.Cap = p.Cap; ap.Cvp = p.Cvp; ap.Cap_prox = p.Cap_prox;

                 ap.LV_Ees = p.LV_Ees; ap.LV_V0 = p.LV_V0;
                 ap.RV_Ees = p.RV_Ees; ap.RV_V0 = p.RV_V0;
                 ap.LA_Ees = p.LA_Ees; ap.LA_V0 = p.LA_V0;
                 ap.RA_Ees = p.RA_Ees; ap.RA_V0 = p.RA_V0;

                 const currentTotal = getTotalVolume(phys.y);
                 const targetTotal = uiInst.targetVolume;
                 const diff = targetTotal - currentTotal;
                 const maxDelta = 500; 
                 const delta = Math.max(-maxDelta, Math.min(maxDelta, diff));

                 if (Math.abs(delta) > 1.0) {
                     phys.y[0] += delta;
                 }
             }

             if (isEndSystole) {
                 const p = uiInst.params;
                 const ap = phys.activeParams;

                 ap.LV_alpha = p.LV_alpha; ap.LV_beta = p.LV_beta; ap.LV_tau = p.LV_tau; ap.LV_Tmax = p.LV_Tmax;
                 ap.RV_alpha = p.RV_alpha; ap.RV_beta = p.RV_beta; ap.RV_tau = p.RV_tau; ap.RV_Tmax = p.RV_Tmax;
                 ap.LA_alpha = p.LA_alpha; ap.LA_beta = p.LA_beta; ap.LA_tau = p.LA_tau;
                 ap.RA_alpha = p.RA_alpha; ap.RA_beta = p.RA_beta; ap.RA_tau = p.RA_tau;
             }

             const { tNext, yNext, aux } = stepRK4(phys.t, phys.y, PHYSICS_DT, phys.activeParams);
             phys.t = tNext;
             phys.y = yNext;

             const bufferRequiredMs = 21000;
             const output: SimulationOutput = {
                t: tNext,
                y: {
                    Qvs: yNext[0], Qas: yNext[1], Qap: yNext[2], Qvp: yNext[3],
                    Qlv: yNext[4], Qla: yNext[5], Qrv: yNext[6], Qra: yNext[7],
                    Qas_prox: yNext[8], Qda: yNext[9], Qap_prox: yNext[10], Qtube: yNext[11]
                },
                aux
            };
            phys.buffer.push(output);
            const cutoffTime = tNext - bufferRequiredMs;
            if (phys.buffer.length > 0 && phys.buffer[0].t < cutoffTime) {
                phys.buffer.shift();
            }
         });
      }
      animationFrameId = requestAnimationFrame(loop);
    };
    animationFrameId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  // --- Handlers ---
  const updateInstanceParams = (id: string, newParams: Partial<SimulationParams>) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, params: { ...inst.params, ...newParams } } : inst
      ));
  };

  const updateInstanceVolume = (id: string, vol: number) => {
      setInstances(prev => prev.map(inst => 
          inst.id === id ? { ...inst, targetVolume: vol } : inst
      ));
  }

  const updateInstanceColor = (id: string, color: string) => {
      setInstances(prev => prev.map(inst => 
        inst.id === id ? { ...inst, color: color } : inst
    ));
  }
  const addInstance = () => {
      const newId = Date.now().toString();
      const color = INSTANCE_COLORS[instances.length % INSTANCE_COLORS.length];

      // Clone params from active instance or use default
      const sourceInstance = instances.find(i => i.id === activeInstanceId);
      const initialParams = sourceInstance ? JSON.parse(JSON.stringify(sourceInstance.params)) : { ...DEFAULT_PARAMS };
      const initialVol = sourceInstance ? sourceInstance.targetVolume : getTotalVolume(INITIAL_STATE_VECTOR);

      setInstances(prev => [...prev, {
          id: newId, name: `Heart ${String.fromCharCode(65 + instances.length)}`,
          color, 
          params: initialParams, 
          targetVolume: initialVol,
          isVisible: true
      }]);
      setActiveInstanceId(newId);
  };
  const removeInstance = (id: string) => {
      setInstances(prev => prev.filter(i => i.id !== id));
      if (activeInstanceId === id) setActiveInstanceId(instances[0]?.id || '');
  };

  // --- Panel Handlers ---
  const addPanel = (type: PanelType) => {
      const newConfig: PanelInstanceConfig = {};
      instances.forEach(i => {
          let defaultSigs: string[] = [];
          if (type === 'PVLOOP') defaultSigs = ['LV'];
          else if (type === 'WAVEFORM') defaultSigs = ['Plv', 'AoP'];
          else if (type === 'METRICS') defaultSigs = ['ABP', 'CO'];
          else if (type === 'GUYTON_RIGHT' || type === 'GUYTON_LEFT' || type === 'GUYTON_3D') defaultSigs = ['Default'];

          newConfig[i.id] = {
              visible: true,
              selectedSignals: defaultSigs
          };
      });

      let title = 'Panel';
      if (type === 'PVLOOP') title = 'PV Loop';
      else if (type === 'WAVEFORM') title = 'Waveforms';
      else if (type === 'METRICS') title = 'Metrics';
      else if (type === 'GUYTON_RIGHT') title = 'Guyton (Right/Sys)';
      else if (type === 'GUYTON_LEFT') title = 'Guyton (Left/Pulm)';
      else if (type === 'GUYTON_3D') title = 'Guyton 3D (Bi-V)';

      const newPanel: PanelDef = {
          id: Date.now().toString(),
          type,
          title,
          w: type === 'METRICS' ? 4 : 6, 
          h: type === 'METRICS' ? 6 : 8,
          config: newConfig,
          showGuides: type === 'PVLOOP',
          timeWindow: type === 'WAVEFORM' ? 5000 : undefined,
          isSettingsOpen: false
      };
      setPanels(prev => [...prev, newPanel]);
      // On mobile, close sidebar after adding panel
      if (isMobile) setIsSidebarOpen(false);
  };

  const removePanel = (id: string) => {
      setPanels(prev => prev.filter(p => p.id !== id));
  };

  const resizeState = useRef<{ panelId: string, startX: number, startY: number, startW: number, startH: number } | null>(null);

  const startResize = (e: React.MouseEvent, panel: PanelDef) => {
      e.stopPropagation();
      e.preventDefault();
      resizeState.current = {
          panelId: panel.id,
          startX: e.clientX,
          startY: e.clientY,
          startW: panel.w,
          startH: panel.h
      };
      document.addEventListener('mousemove', onResizeMove);
      document.addEventListener('mouseup', onResizeEnd);
  };

  const onResizeMove = (e: MouseEvent) => {
      if (!resizeState.current) return;
      const { panelId, startX, startY, startW, startH } = resizeState.current;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      const wDelta = Math.round(dx / 50);
      const hDelta = Math.round(dy / 50);
      const newW = Math.max(2, Math.min(12, startW + wDelta)); 
      const newH = Math.max(4, Math.min(20, startH + hDelta)); 

      setPanels(prev => prev.map(p => 
          p.id === panelId ? { ...p, w: newW, h: newH } : p
      ));
  };

  const onResizeEnd = () => {
      resizeState.current = null;
      document.removeEventListener('mousemove', onResizeMove);
      document.removeEventListener('mouseup', onResizeEnd);
  };


  // --- Config Logic ---
  const toggleSettings = (panelId: string) => {
      setPanels(prev => prev.map(p => 
        p.id === panelId ? { ...p, isSettingsOpen: !p.isSettingsOpen } : { ...p, isSettingsOpen: false }
      ));
  };

  const toggleInstanceVisibility = (panelId: string, instId: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, visible: !prevCfg.visible }
              }
          };
      }));
  };

  const updateInstanceSignals = (panelId: string, instId: string, signal: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          const currentSigs = new Set(prevCfg.selectedSignals);
          if (currentSigs.has(signal)) currentSigs.delete(signal); else currentSigs.add(signal);

          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { ...prevCfg, selectedSignals: Array.from(currentSigs) }
              }
          };
      }));
  };

  const updateCustomColor = (panelId: string, instId: string, signal: string, color: string) => {
      setPanels(prev => prev.map(p => {
          if (p.id !== panelId) return p;
          const prevCfg = p.config[instId];
          return {
              ...p,
              config: {
                  ...p.config,
                  [instId]: { 
                      ...prevCfg, 
                      customColors: { ...prevCfg.customColors, [signal]: color } 
                  }
              }
          };
      }));
  }

  const toggleGuides = (panelId: string) => {
     setPanels(prev => prev.map(p => p.id === panelId ? { ...p, showGuides: !p.showGuides } : p));
  }

  const updateTimeWindow = (panelId: string, val: number) => {
      setPanels(prev => prev.map(p => p.id === panelId ? { ...p, timeWindow: val } : p));
  }

  // --- Drag & Drop ---
  const dragItemRef = useRef<number | null>(null);
  const dragOverItemRef = useRef<number | null>(null);

  const onDragStart = (e: React.DragEvent, index: number) => {
    dragItemRef.current = index;
    e.dataTransfer.effectAllowed = "move";
  };
  const onDragEnter = (e: React.DragEvent, index: number) => {
    dragOverItemRef.current = index;
  };
  const onDragEnd = () => {
    const srcIdx = dragItemRef.current;
    const dstIdx = dragOverItemRef.current;
    if (srcIdx !== null && dstIdx !== null && srcIdx !== dstIdx) {
       setPanels(prev => {
           const next = [...prev];
           const [removed] = next.splice(srcIdx, 1);
           next.splice(dstIdx, 0, removed);
           return next;
       });
    }
    dragItemRef.current = null;
    dragOverItemRef.current = null;
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans relative">

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-14 bg-slate-900 border-b border-slate-800 z-50 flex items-center px-4 justify-between">
          <h1 className="text-lg font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400">
            HemoSim 0D
          </h1>
          <button 
             onClick={() => setIsSidebarOpen(!isSidebarOpen)}
             className="text-slate-300 p-2 hover:bg-slate-800 rounded"
          >
             {isSidebarOpen ? '✕' : '☰'}
          </button>
      </div>

      {/* Sidebar - Desktop: Fixed left, Mobile: Fixed Overlay (Right side) */}
      <aside 
        className={`
            fixed inset-y-0 right-0 bg-slate-900 overflow-y-auto z-40 shadow-xl transition-transform duration-300 ease-in-out w-80
            md:border-r md:border-slate-800
            ${isMobile ? 'top-14 border-l border-slate-800' : 'top-0'}
            ${isMobile && !isSidebarOpen ? 'translate-x-full' : 'translate-x-0'}
            md:relative md:translate-x-0 md:top-0 md:left-0 md:right-auto
        `}
      >
        <div className="p-5 pb-20">
          {!isMobile && (
              <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-6">
                HemoSim 0D
              </h1>
          )}
          <Controls 
            instances={instances}
            activeInstanceId={activeInstanceId}
            setActiveInstanceId={setActiveInstanceId}
            updateInstanceParams={updateInstanceParams}
            updateInstanceVolume={updateInstanceVolume}
            updateInstanceColor={updateInstanceColor}
            addInstance={addInstance}
            removeInstance={removeInstance}

            timeScale={timeScale} setTimeScale={setTimeScale}
            isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}

            addPanel={addPanel}
          />
        </div>
      </aside>

      {/* Mobile Overlay Backdrop */}
      {isMobile && isSidebarOpen && (
          <div 
            className="fixed inset-0 bg-black/50 z-30" 
            onClick={() => setIsSidebarOpen(false)}
          />
      )}

      <main className={`flex-1 h-full overflow-y-auto overflow-x-hidden bg-slate-950 p-2 ${isMobile ? 'pt-16' : ''}`}>
          {/* Grid Container */}
          <div className="grid grid-cols-12 gap-2 auto-rows-[50px] grid-flow-dense pb-20">
              {panels.map((panel, index) => {
                  // Mobile: Force span 12 (full width). Desktop: Use panel.w
                  const gridColStyle = isMobile ? { gridColumn: 'span 12' } : { gridColumn: `span ${panel.w}` };
                  // Mobile: Use fixed rows for better aspect ratio (Metrics smaller, Charts larger). Desktop: Use panel.h
                  const mobileRowSpan = panel.type === 'METRICS' ? 5 : 7;
                  const rowSpan = isMobile ? mobileRowSpan : panel.h;

                  return (
                  <div 
                    key={panel.id} 
                    draggable={!isMobile} // Disable drag on mobile to prevent scroll issues
                    onDragStart={(e) => onDragStart(e, index)}
                    onDragEnter={(e) => onDragEnter(e, index)}
                    onDragEnd={onDragEnd}
                    onDragOver={(e) => e.preventDefault()}
                    style={{ ...gridColStyle, gridRow: `span ${rowSpan}` }}
                    className="relative bg-slate-900/50 rounded-lg border border-slate-800 shadow-inner flex flex-col overflow-visible group hover:border-slate-600 transition-colors"
                  >
                      {/* Panel Header */}
                      <div className="absolute top-2 left-2 z-30 flex gap-2 items-center pointer-events-auto">
                           <div className="bg-slate-950/90 px-2 py-1 rounded border border-slate-700 backdrop-blur-sm shadow-sm flex items-center gap-2 cursor-move">
                                <span className="text-xs font-bold text-slate-300 select-none">⋮⋮ {panel.title}</span>
                                <div className="h-3 w-[1px] bg-slate-700 mx-1"></div>

                                {/* Settings Toggle (Click-based) */}
                                <div className="relative">
                                    <button 
                                        onClick={() => toggleSettings(panel.id)}
                                        className={`text-[10px] px-1 flex items-center gap-1 rounded hover:bg-slate-800 ${panel.isSettingsOpen ? 'text-blue-400 bg-slate-800' : 'text-slate-400'}`}
                                    >
                                        <span className="w-3 h-3 border border-current rounded-sm flex items-center justify-center">
                                            <span className="text-[8px]">⚙</span>
                                        </span>
                                    </button>

                                    {/* Dropdown Content */}
                                    {panel.isSettingsOpen && (
                                        <div className="absolute top-full left-0 mt-2 w-56 bg-slate-900 border border-slate-700 rounded shadow-2xl p-3 z-50">
                                            <div className="flex justify-between items-center mb-2 pb-2 border-b border-slate-800">
                                                <span className="text-[10px] font-bold text-slate-500 uppercase">Configuration</span>
                                                <button onClick={() => toggleSettings(panel.id)} className="text-xs text-slate-400 hover:text-white">✕</button>
                                            </div>

                                            {/* Panel Specific Settings */}
                                            {panel.type === 'PVLOOP' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800 flex items-center gap-2">
                                                    <input type="checkbox" checked={panel.showGuides} onChange={() => toggleGuides(panel.id)} />
                                                    <span className="text-xs text-slate-300">Show Guides</span>
                                                </div>
                                            )}
                                            {panel.type === 'WAVEFORM' && (
                                                <div className="mb-2 pb-2 border-b border-slate-800">
                                                    <div className="flex justify-between text-[10px] text-slate-400 mb-1">
                                                        <span>Window</span>
                                                        <span>{(panel.timeWindow || 10000) / 1000}s</span>
                                                    </div>
                                                    <input 
                                                        type="range" min={2000} max={20000} step={1000} 
                                                        value={panel.timeWindow || 10000}
                                                        onChange={(e) => updateTimeWindow(panel.id, parseFloat(e.target.value))}
                                                        className="w-full h-1 bg-slate-700 rounded appearance-none cursor-pointer accent-blue-500"
                                                    />
                                                </div>
                                            )}

                                            <div className="max-h-64 overflow-y-auto space-y-3 custom-scrollbar">
                                                {instances.map(inst => (
                                                    <div key={inst.id}>
                                                        <div className="flex items-center gap-2 mb-1">
                                                            <input 
                                                                type="checkbox" 
                                                                checked={panel.config[inst.id]?.visible || false}
                                                                onChange={() => toggleInstanceVisibility(panel.id, inst.id)}
                                                            />
                                                            <span className="w-2 h-2 rounded-full" style={{backgroundColor: inst.color}}></span>
                                                            <span className="text-xs font-bold text-slate-300 truncate flex-1">{inst.name}</span>
                                                        </div>
                                                        {/* Sub Signals & Colors */}
                                                        {panel.config[inst.id]?.visible && (panel.type !== 'GUYTON_RIGHT' && panel.type !== 'GUYTON_LEFT' && panel.type !== 'GUYTON_3D') && (
                                                            <div className="pl-5 grid grid-cols-1 gap-1">
                                                                {((panel.type === 'PVLOOP' ? ALL_CHAMBERS : (panel.type === 'WAVEFORM' ? ALL_SIGNALS : ALL_METRICS))).map(sig => {
                                                                    const isSelected = panel.config[inst.id].selectedSignals.includes(sig);
                                                                    const customColor = panel.config[inst.id].customColors?.[sig];

                                                                    return (
                                                                    <div key={sig} className="flex items-center justify-between text-[10px] bg-slate-950/50 rounded px-1 py-0.5">
                                                                        <button 
                                                                            onClick={() => updateInstanceSignals(panel.id, inst.id, sig)}
                                                                            className={`flex-1 text-left ${isSelected ? 'text-slate-200' : 'text-slate-600'}`}
                                                                        >
                                                                            {sig}
                                                                        </button>
                                                                        {isSelected && panel.type !== 'METRICS' && (
                                                                            <input 
                                                                                type="color" 
                                                                                className="w-3 h-3 border-none p-0 bg-transparent cursor-pointer"
                                                                                value={customColor || inst.color} 
                                                                                onChange={(e) => updateCustomColor(panel.id, inst.id, sig, e.target.value)}
                                                                            />
                                                                        )}
                                                                    </div>
                                                                )})}
                                                            </div>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <button onClick={() => removePanel(panel.id)} className="text-slate-500 hover:text-red-400 ml-1">✕</button>
                           </div>
                      </div>

                      {/* Content */}
                      <div className="flex-1 min-h-0 w-full p-1 pt-2">
                          {panel.type === 'PVLOOP' && (
                              <PVLoopPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                config={panel.config}
                                showGuides={panel.showGuides}
                              />
                          )}
                          {panel.type === 'WAVEFORM' && (
                              <WaveformPanel 
                                physicsRefs={physicsRefs}
                                instances={instances}
                                timeWindow={panel.timeWindow || 10000}
                                config={panel.config}
                              />
                          )}
                          {panel.type === 'METRICS' && (
                               <MetricsPanel 
                                  physicsRefs={physicsRefs}
                                  instances={instances}
                                  config={panel.config}
                               />
                          )}
                          {(panel.type === 'GUYTON_RIGHT' || panel.type === 'GUYTON_LEFT' || panel.type === 'GUYTON_3D') && (
                                <GuytonPanel 
                                    physicsRefs={physicsRefs}
                                    instances={instances}
                                    config={panel.config}
                                    type={panel.type as any}
                                />
                          )}
                      </div>

                      {/* Resize Handle - Hide on mobile */}
                      {!isMobile && (
                        <div 
                            onMouseDown={(e) => startResize(e, panel)}
                            className="absolute bottom-0 right-0 w-4 h-4 cursor-se-resize flex items-end justify-end p-0.5 z-40 group/handle"
                        >
                            <div className="w-0 h-0 border-l-[8px] border-l-transparent border-b-[8px] border-b-slate-600 group-hover/handle:border-b-blue-500"></div>
                        </div>
                      )}
                  </div>
              )})}
          </div>
      </main>
    </div>
  );
}

export default App;
